	$post[5455] = array( 'title' => 'ইসলামী আকীদা বিষয়ক কতিপয় গুরুত্বপূর্ণ মাসয়ালা', 'excerpt' => ' অত্র পুস্তিকায় শায়খ মুহাম্মদ জামীল যাইনু কুরআন ও বিশুদ্ধ হাদীসের আলোকে ইসলামী আকীদা শিরোনামে কতিপয় গুরুত্বপূর্ণ মাসয়ালা প্রশ্নোত্তরের আদলে পেশ করেছেন। মাসয়ালাগুলো যদিও কতক মুসলমানের জানা, তবে অধিকাংশের কাছে অস্পষ্টতা রয়ে গেছে অনেক ক্ষেত্রেই। পুস্তিকাটি সংক্ষিপ্ত পরিসরে এ বিষয়গুলো স্পষ্ট করতে সক্ষম হবে বলে আশা রাখি', 'url' => $url.'/bengali/%e0%a6%87%e0%a6%b8%e0%a6%b2%e0%a6%be%e0%a6%ae%e0%a7%80-%e0%a6%86%e0%a6%95%e0%a7%80%e0%a6%a6%e0%a6%be-%e0%a6%ac%e0%a6%bf%e0%a6%b7%e0%a6%af%e0%a6%bc%e0%a6%95-%e0%a6%95%e0%a6%a4%e0%a6%bf%e0%a6%aa/', 'image' => $url.'/wp-content/uploads/2013/12/5455.png', 'author_id' => '2363', 'author_name' => 'শাইখ মুহাম্মদ ইবন জামীল যাইনূ', 'book_url' => $url.'/dl/books/bn5455.pdf' );
	$post[5456] = array( 'title' => 'আশুরা: করনীয় ও বর্জনীয়', 'excerpt' => ' আশুরা : করনীয় ও বর্জনীয় : আশুরা বিষয়ক গুরুত্বপূর্ণ গ্রন্থ। আশুরা দিবসে কোন কোন আমল জায়েয আর কি কি নাজায়েয তার উল্লেখ রয়েছে বইটিতে। মানুষ এ দিবসকে কেন্দ্র করে যে সকল বিদআত ও কুসংস্কারের আবিষ্কার করেছে তারও বিস্তারিতভাবে আলোচনা এসেছে এখানে।', 'url' => $url.'/bengali/%e0%a6%86%e0%a6%b6%e0%a7%81%e0%a6%b0%e0%a6%be-%e0%a6%95%e0%a6%b0%e0%a6%a8%e0%a7%80%e0%a6%af%e0%a6%bc-%e0%a6%93-%e0%a6%ac%e0%a6%b0%e0%a7%8d%e0%a6%9c%e0%a6%a8%e0%a7%80%e0%a6%af%e0%a6%bc/', 'image' => $url.'/wp-content/uploads/2013/12/5456.png', 'author_id' => '2336', 'author_name' => 'আব্দুল্লাহ শহীদ আব্দুর রহমান', 'book_url' => $url.'/dl/books/bn5456.pdf', 'publisher' => 'www.islamhouse.com' );
