	$post[5458] = array( 'title' => 'আল আকীদা আত-তাহাবিয়া', 'excerpt' => ' আল আকীদা আত-তাহাবিয়া : প্রখ্যাত মুহাদ্দিস, আল্লামা আবু জাফর আহমদ বিন মুহাম্মদ বিন সালামা আল-ইযদী আত-তাহাবী (মৃতু ৩২১ হিজরী) কর্তৃক সংকলিত আহলে সুন্নাত ওয়াল জাসাআতের আকীদা সমগ্রের সারসংক্ষেপ এ বইটি সকল মাজহাবের অনুসারী আহলে সুন্নাহর সকল ইমাম ও আলেমদের নিকট সমাদৃত হয়েছে সমানভাবে। আরবিসহ বহু ভাষায় এর তর্জমা ও ব্যাখ্যা লেখা হয়েছে।', 'url' => $url.'/bengali/%e0%a6%86%e0%a6%b2-%e0%a6%86%e0%a6%95%e0%a7%80%e0%a6%a6%e0%a6%be-%e0%a6%86%e0%a6%a4-%e0%a6%a4%e0%a6%be%e0%a6%b9%e0%a6%be%e0%a6%ac%e0%a6%bf%e0%a6%af%e0%a6%bc%e0%a6%be/', 'image' => $url.'/wp-content/uploads/2013/12/5458.png', 'author_id' => '2324', 'author_name' => 'আবু জাফর আততাহাবী', 'book_url' => $url.'/dl/books/bn5458.pdf' );
	$post[5459] = array( 'title' => 'হারাম শরীফের দেশ, ফজিলত ও আহকাম', 'excerpt' => ' বইটি উম্মুল কুরা বিশ্ব বিদ্যালয়ের দাওয়া ও উসুলুদ্দীন ফ্যাকাল্টি কর্তৃক সংকলিত। বইটিতে পবিত্র মক্কায় অবস্থিত মাশায়েরসমূহের পরিচিতি ও ইতিহাস, সেখানে গমনকারীর করণীয় ও বর্জনীয় বিষয়ে সবিস্তারে আলোচনা স্থান পেয়েছে। সাথে সাথে এ বিষয়ে প্রচলিত কুসংস্কার- ভুলত্রুটি সম্পর্কেও দিক-নির্দেশনা দেয়া হয়েছে যথার্থভাবে। বইটি সাধারনভাবে সকল মানুষ, ও বিশেষভাবে হজ পালনকারীদের উপকারে আসবে বলে আমাদের দৃঢ় বিশ্বাস', 'url' => $url.'/bengali/%e0%a6%b9%e0%a6%be%e0%a6%b0%e0%a6%be%e0%a6%ae-%e0%a6%b6%e0%a6%b0%e0%a7%80%e0%a6%ab%e0%a7%87%e0%a6%b0-%e0%a6%a6%e0%a7%87%e0%a6%b6-%e0%a6%ab%e0%a6%9c%e0%a6%bf%e0%a6%b2%e0%a6%a4-%e0%a6%93-%e0%a6%86/', 'image' => $url.'/wp-content/uploads/2013/12/5459.png', 'author_id' => '2353', 'author_name' => 'মোহাম্মদ মানজুরে ইলাহী - হাসান মঈন উদ্দীন', 'book_url' => $url.'/dl/books/bn5459.pdf' );
