	$post[5479] = array( 'title' => 'আল-গিরাস : চিন্তার উন্মেষ ও কর্মবিকাশের অনুশীলন (১ম খণ্ড)', 'excerpt' => ' এ বইয়ের কোথাও, কোন ছত্রে, এমন কিছু খুঁজে পাওয়া যাবে না, প্রথাগত ভাষায় যাকে বলা হয় অসত্যের সঙ্গে সত্যের বিতর্ক, কিংবা নিরেট বিশুদ্ধ কালচার, নির্জীব চিন্তা ও জ্ঞানের চর্চা; বরং এ হচ্ছে সদা কল্যাণে ধাবমান এক জীবনময়তা, কিংবা জীবনের প্রতিটি পরতে কল্যাণের বিস্তার। অথবা সাদাকায়ে জারিয়ায় জীবনকে অনন্ত প্রবাহে বিধৌত করণ। এ বই ও তার আলোচনার-সূচনা হতে সমাপ্তি অবধি-এই হচ্ছে একমাত্রিক লক্ষ্য ও উদ্দেশ্য।', 'url' => $url.'/bengali/%e0%a6%86%e0%a6%b2-%e0%a6%97%e0%a6%bf%e0%a6%b0%e0%a6%be%e0%a6%b8-%e0%a6%9a%e0%a6%bf%e0%a6%a8%e0%a7%8d%e0%a6%a4%e0%a6%be%e0%a6%b0-%e0%a6%89%e0%a6%a8%e0%a7%8d%e0%a6%ae%e0%a7%87%e0%a6%b7-%e0%a6%93/', 'image' => $url.'/wp-content/uploads/2013/12/5479.png', 'author_id' => '2344', 'author_name' => 'কাউসার বিন খালিদ', 'book_url' => $url.'/dl/books/bn5479.pdf' );
