	$post[5481] = array( 'title' => 'ইসলামী বিধান ও আধুনিক বিজ্ঞান', 'excerpt' => ' এ বইয়ে ইসলামী অনুশাসন ও বিধানাবলিকে আধুনিক জ্ঞান-বিজ্ঞান ও চিকিৎসা বিজ্ঞানের সঙ্গে তুলনা করে প্রমাণ করা হয়েছে যে, ইসলামের বিধানসমূহ মানব কল্যাণের জন্য প্রণীত এবং বিশ্বের সকল মানুষের জন্য প্রযোজ্য। যেমন, ইসলাম কেন মৃত প্রাণীর গোস্ত ও শুকরের গোস্ত হারাম করেছে, ইসলাম কেন রক্ত, মদ ও নেশা জাতীয় বস্তু হারাম করেছে, ইসলামে নিষিদ্ধ সমকামিতার ভয়াবহ পরিণতি কী, হায়েয অবস্থায় নারীগমন নিষেধ কেন এ জাতীয় বিষয় বৈজ্ঞানিক বিচার বিশ্লেষণের আলোকে তুলে ধরা হয়েছে।', 'url' => $url.'/bengali/%e0%a6%87%e0%a6%b8%e0%a6%b2%e0%a6%be%e0%a6%ae%e0%a7%80-%e0%a6%ac%e0%a6%bf%e0%a6%a7%e0%a6%be%e0%a6%a8-%e0%a6%93-%e0%a6%86%e0%a6%a7%e0%a7%81%e0%a6%a8%e0%a6%bf%e0%a6%95-%e0%a6%ac%e0%a6%bf%e0%a6%9c/', 'image' => $url.'/wp-content/uploads/2013/12/5481.png', 'author_id' => '2368', 'author_name' => 'সানাউল্লাহ নজির আহমদ', 'book_url' => $url.'/dl/books/bn5481.pdf' );
