	$post[5510] = array( 'title' => 'মুসলমানদের পতন : অতীত ও বর্তমান', 'excerpt' => 'মুসলমানদের পতন : অতীত ও বর্তমান  বইটিতে গাজী সালাহউদ্দিন আইয়ুবীর আবির্ভাবপূর্ব সময়ে মুসলমানদের অধঃপতনের কারণসমূহ ও বর্তমান অবস্থার সাথে তার কতখানি মিল রয়েছে সেটা তুলে ধরা হয়েছে। সাথে সাথে মুসলিম উম্মাহর বিরুদ্ধে বাতেনী ও শিয়া সম্প্রদায়ের ষড়যন্ত্রের ইতিহাসও আলোচনা করা হয়েছে।    كتاب يتتبع أسباب انحطاط المسلمين فيما قبل عهد صلاح الدين الأيوبي ويجري مقارنات ما بين أحداث الماضي والحاضر،', 'url' => $url.'/bengali/%e0%a6%ae%e0%a7%81%e0%a6%b8%e0%a6%b2%e0%a6%ae%e0%a6%be%e0%a6%a8%e0%a6%a6%e0%a7%87%e0%a6%b0-%e0%a6%aa%e0%a6%a4%e0%a6%a8-%e0%a6%85%e0%a6%a4%e0%a7%80%e0%a6%a4-%e0%a6%93-%e0%a6%ac%e0%a6%b0%e0%a7%8d/', 'image' => $url.'/wp-content/uploads/2013/12/5510.png', 'author_id' => '2371', 'author_name' => 'হাফেয নেছার উদ্দিন', 'book_url' => $url.'/dl/books/bn5510.pdf' );
	$post[5511] = array( 'title' => 'আকীদার মানদণ্ডে তাবীজ', 'excerpt' => 'অত্র কিতাবে কুরআন ও হাদীসের দৃষ্টি তাবীযের বিধান সম্পর্কে আলোচনা করা হয়েছে।   موقف الشرع من التمائم', 'url' => $url.'/bengali/%e0%a6%86%e0%a6%95%e0%a7%80%e0%a6%a6%e0%a6%be%e0%a6%b0-%e0%a6%ae%e0%a6%be%e0%a6%a8%e0%a6%a6%e0%a6%a3%e0%a7%8d%e0%a6%a1%e0%a7%87-%e0%a6%a4%e0%a6%be%e0%a6%ac%e0%a7%80%e0%a6%9c/', 'image' => $url.'/wp-content/uploads/2013/12/5511.png', 'author_id' => '2340', 'author_name' => 'আলী বিন নুফাই আল- উলইয়ানী', 'book_url' => $url.'/dl/books/bn5511.pdf' );
	$post[5512] = array( 'title' => 'নারীর জান্নাত যে পথে', 'excerpt' => 'এ বইয়ে কুরআন ও সহিহ হাদিসের দৃষ্টিকোণ থেকে একজন নেককার নারীর গুনাবলি কী হবে তা উল্লেখ করা হয়েছে।  صفات الزوجة الصالحة على ضوء الآيات القرآنية والآحاديث النبوية، كما تتحدث عن حقوق الزوج على زوجته وحقوق الزوجة على زوجها.', 'url' => $url.'/bengali/%e0%a6%a8%e0%a6%be%e0%a6%b0%e0%a7%80%e0%a6%b0-%e0%a6%9c%e0%a6%be%e0%a6%a8%e0%a7%8d%e0%a6%a8%e0%a6%be%e0%a6%a4-%e0%a6%af%e0%a7%87-%e0%a6%aa%e0%a6%a5%e0%a7%87/', 'image' => $url.'/wp-content/uploads/2013/12/5512.png', 'author_id' => '2368', 'author_name' => 'সানাউল্লাহ নজির আহমদ', 'book_url' => $url.'/dl/books/bn5512.pdf' );
	$post[5513] = array( 'title' => 'ইসলাম প্রচারে মনোবিজ্ঞানের ভূমিকা', 'excerpt' => 'মানুষের জ্ঞান, অভিজ্ঞতা- বিশেষ করে মনোবিজ্ঞান- কীভাবে আল্লাহর পথে আহ্বান ও ইসলাম প্রচার প্রক্রিয়ায় সহায়তা দিতে পারে সে বিষয়টি গুরুত্ব পেয়েছে আমাদের বর্তমান বইটিতে। দাওয়াতী ময়দানে কর্মরত যে কোন ব্যক্তি এত্থেকে উপকৃত হবেন বলে আমাদের আশা।  هذا الكتاب يبين كيفية توظيف خبرات الناس وعلومهم في دعم العمل الإسلامي باختلاف أنواعه وأشكاله', 'url' => $url.'/bengali/%e0%a6%87%e0%a6%b8%e0%a6%b2%e0%a6%be%e0%a6%ae-%e0%a6%aa%e0%a7%8d%e0%a6%b0%e0%a6%9a%e0%a6%be%e0%a6%b0%e0%a7%87-%e0%a6%ae%e0%a6%a8%e0%a7%8b%e0%a6%ac%e0%a6%bf%e0%a6%9c%e0%a7%8d%e0%a6%9e%e0%a6%be%e0%a6%a8/', 'image' => $url.'/wp-content/uploads/2013/12/5513.png', 'author_id' => '2331', 'author_name' => 'আব্দুল্লাহ আল খাতির', 'book_url' => $url.'/dl/books/bn5513.pdf' );
	$post[5514] = array( 'title' => 'আল্লাহর দিকে আহবান ও দায়ীর গুণাবলি', 'excerpt' => ' বইটিতে আল্লাহর প্রতি আহবানের গুরুত্ব এবং দায়ীদের গুণাবলি সম্পর্কে বিস্তারিতভাবে আলোচনা করা হয়েছে।  الكتاب يتحدث عن حكم الدعوة إلى الله وفضلها، كيفية أدائها وأساليبها، بيان الأخلاق والصفات التي ينبغي للدعاة أن يتخلقوا بها وأن يسيروا عليها.', 'url' => $url.'/bengali/%e0%a6%86%e0%a6%b2%e0%a7%8d%e0%a6%b2%e0%a6%be%e0%a6%b9%e0%a6%b0-%e0%a6%a6%e0%a6%bf%e0%a6%95%e0%a7%87-%e0%a6%86%e0%a6%b9%e0%a6%ac%e0%a6%be%e0%a6%a8-%e0%a6%93-%e0%a6%a6%e0%a6%be%e0%a6%af%e0%a6%bc/', 'image' => $url.'/wp-content/uploads/2013/12/5514.png', 'author_id' => '2329', 'author_name' => 'আব্দুল আযীয ইবন আবদুল্লাহ ইবন বায', 'book_url' => $url.'/dl/books/bn5514.pdf' );
	$post[5515] = array( 'title' => 'নারীদের প্রাকৃতিক রক্তস্রাব', 'excerpt' => ' নারীদের প্রাকৃতিক রক্তস্রাব বিষয়ে খুবই গুরুত্বপূর্ণ একটি গ্রন্থ। রক্তস্রাব সংক্রান্ত্র গুরুত্বপূর্ণ সকল তথ্য, সাতটি পরিচ্ছেদে বিন্যস্ত করে, গ্রন্থটিতে উপস্থাপন করা হয়েছে সুগঠিত ভাষায়। পরিচ্ছেদগুলো নিম্নরূপ।   رسالة في الدماء الطبيعية للنساء: بحث يفصل فيه فضيلة الشيخ أحكام الدماء الطبيعية للنساء، وتنقسم الرسالة إلى سبعة فصول', 'url' => $url.'/bengali/%e0%a6%a8%e0%a6%be%e0%a6%b0%e0%a7%80%e0%a6%a6%e0%a7%87%e0%a6%b0-%e0%a6%aa%e0%a7%8d%e0%a6%b0%e0%a6%be%e0%a6%95%e0%a7%83%e0%a6%a4%e0%a6%bf%e0%a6%95-%e0%a6%b0%e0%a6%95%e0%a7%8d%e0%a6%a4%e0%a6%b8%e0%a7%8d/', 'image' => $url.'/wp-content/uploads/2013/12/5515.png', 'author_id' => '2329', 'author_name' => 'আব্দুল আযীয ইবন আবদুল্লাহ ইবন বায', 'book_url' => $url.'/dl/books/bn5515.pdf' );
	$post[5516] = array( 'title' => 'দুআ-মুনাজাত : কখন ও কিভাবে', 'excerpt' => 'দুআ-মুনাজাত : কখন ও কিভাবে    ইখলাস ও সমর্পিত হৃদয়ে দুআ আল্লাহর নৈকট্য অর্জনের অন্যতম মাধ্যম। বক্ষ্যমাণ গ্রন্থে দুআর আদব', 'url' => $url.'/bengali/%e0%a6%a6%e0%a7%81%e0%a6%86-%e0%a6%ae%e0%a7%81%e0%a6%a8%e0%a6%be%e0%a6%9c%e0%a6%be%e0%a6%a4-%e0%a6%95%e0%a6%96%e0%a6%a8-%e0%a6%93-%e0%a6%95%e0%a6%bf%e0%a6%ad%e0%a6%be%e0%a6%ac%e0%a7%87/', 'image' => $url.'/wp-content/uploads/2013/12/5516.png', 'author_id' => '2351', 'author_name' => 'ফায়সাল বিন আলী আল-বাদানী', 'book_url' => $url.'/dl/books/bn5516.pdf', 'publisher' => 'www.islamhouse.com' );
	$post[5517] = array( 'title' => 'মুসলিম নারীর অধিকার ও দায়িত্ব ; ইসলামের ইশতিহার ও সনদ', 'excerpt' => ' মুসলিম নারীর অধিকার ও দায়িত্ব , ইসলামের ইশতিহার ও সনদ : ইসলাম নারীর মর্যাদা সমুন্নত করেছে। দিয়েছে তাকে উপযুক্ত সম্মান, প্রাপ্য অধিকার। অন্যপক্ষে পাশ্চত্যজগৎ বস্তুবাদী সভ্যতার করুণ কষাঘাতে নারীকে করেছে বিপন্ন নানাভাবে, কেড়ে নিয়েছে তার সম্ভ্রম, মর্যাদা, এবং ঠেলে দিয়েছে কদর্যতার অতল গহ্বরে। বইটিতে ইসলাম ও পাশ্চত্য সভ্যতায় নারীর অধিকার ও সনদ বিষয়ে বস্তুনিষ্ঠ ও বিজ্ঞানময় আলোচনা করা হয়েছে। ইসলামে নারীর অধিকার বিষয়ে এখনো যারা সন্দেহে নিপতিত বইটি তাদেরকে সকল দ্বৈতবোধ থেকে মুক্ত করবে বলে বিশ্বাস।  وثيقة حقوق المرأة المسلمة وواجباتها: كتاب قيم مكتوب بأسلوب علمي رصين، وقد أبرز فيه أهم جوانب الحقوق والواجبات التي منحها الإسلام للمرأة فأعلى من شأنها و ضمن لها ما تستحق من المكانة والكرامة اللائقتين', 'url' => $url.'/bengali/%e0%a6%ae%e0%a7%81%e0%a6%b8%e0%a6%b2%e0%a6%bf%e0%a6%ae-%e0%a6%a8%e0%a6%be%e0%a6%b0%e0%a7%80%e0%a6%b0-%e0%a6%85%e0%a6%a7%e0%a6%bf%e0%a6%95%e0%a6%be%e0%a6%b0-%e0%a6%93-%e0%a6%a6%e0%a6%be%e0%a6%af/', 'image' => $url.'/wp-content/uploads/2013/12/5517.png', 'author_id' => '2361', 'author_name' => 'মুহাম্মদ শামসুল হক সিদ্দিক', 'book_url' => $url.'/dl/books/bn5517.pdf', 'publisher' => 'www.islamhouse.com' );
	$post[5518] = array( 'title' => 'আল্লাহর বাণী আল-কুরআন ও আধুনিক বিজ্ঞান', 'excerpt' => ' আধুনিক বিজ্ঞান আল কুরআনের বিপক্ষে নয় বরং পক্ষে পেশ করেছে-করছে বহু প্রমাণ যা বিশ্বাসীদের দাঁড়াবার ভূমিকে করে দিচ্ছে আরো মজবুত-দৃঢ়।বক্ষ্যমাণ বইটি এ দৃষ্টিকোণ থেকেই লেখা। আশা করি যেকোনো পাঠক বইটি পড়ে উপকৃত হবেন।   يتحدث هذا الكتاب عن المكتشفات العلمية الحديثة التي جاءت مؤيدة لما ورد في القرآن الكريم من المفاهيم والمعلومات.', 'url' => $url.'/bengali/%e0%a6%86%e0%a6%b2%e0%a7%8d%e0%a6%b2%e0%a6%be%e0%a6%b9%e0%a6%b0-%e0%a6%ac%e0%a6%be%e0%a6%a3%e0%a7%80-%e0%a6%86%e0%a6%b2-%e0%a6%95%e0%a7%81%e0%a6%b0%e0%a6%86%e0%a6%a8-%e0%a6%93-%e0%a6%86%e0%a6%a7/', 'image' => $url.'/wp-content/uploads/2013/12/5518.png', 'author_id' => '2337', 'author_name' => 'আব্দুল্লাহ শহীদ আব্দুর রহমান - চৌধুরী আবুল কালাম আজাদ', 'book_url' => $url.'/dl/books/bn5518.pdf' );
	$post[5519] = array( 'title' => 'কবীরা গুনাহ', 'excerpt' => ' কবীরা গুনাহ : ইমাম শামসুদ্দীন আয যাহবী সংকলিত প্রসিদ্ধ গ্রন্থ মুখতাসার আল কাবায়ের, যা বাংলা ভাষায় অনুবাদ করে নাম দেয়া হয়েছে কবীরা গুনাহ। এ বইটি মানুষের মাঝে ব্যাপক সাড়া জাগিয়েছে। মানুষ এ বইয়ের সাহায্যো প্রমাণসহ জানতে পারে আল্লাহ কি কি বিষয় নিষিদ্ধ করেছেন। বড় বড় গুনাহ চিহ্নিত করা ও সেগুলো থেকে বেঁচে থাকার ক্ষেত্রে এ বইটি একটি গুরুত্বপূর্ণ পথনির্দেশক।  كتاب الكبائر: لاقَت هذه الرسالة قبولاً واسعًا بين الناس، بيَّن المؤلف فيها كبائر الذنوب كلها بإيجاز وبأدلة من القرآن والسنة', 'url' => $url.'/bengali/%e0%a6%95%e0%a6%ac%e0%a7%80%e0%a6%b0%e0%a6%be-%e0%a6%97%e0%a7%81%e0%a6%a8%e0%a6%be%e0%a6%b9/', 'image' => $url.'/wp-content/uploads/2013/12/5519.png', 'author_id' => '2364', 'author_name' => 'শামছুদ্দিন আযযাহাবি', 'book_url' => $url.'/dl/books/bn5519.pdf' );
	$post[5520] = array( 'title' => 'তাওহীদের মর্মকথা', 'excerpt' => ' তাওহীদের মর্মকথা: শায়খুল ইসলাম মুহাম্মদ বিন আব্দুল ওয়াহাব রহ. এর সাড়া জাগানো কিতাবুত তাওহীদের ব্যাখ্যা গ্রন্থ এই আল-কাওলুস সাদীদ। সংক্ষিপ্ত ব্যাখ্যা করেছেন শায়খ আব্দুররহমান নাসের আস- সাদী। তাওহিদের বিভিন্ন দিক, শিরকের বিস্তারিত পরিচয় ও তার সকল পর্যায় আলোচনা করা হয়েছে এ গ্রন্থে। যে তাওহীদ আল্লাহ মানুষের জন্য অপরিহার্য করেছেন। শিরকে আকবর ও শিরকে আছগর এবং শিরকের সকল প্রকার ও দিক তুলে ধরা হয়েছে এ বইতে।  يحتوي على بيان لعقيدة أهل السنة والجماعة بالدليل من القرآن الكريم والسنة النبوية، وهوكتاب عظيم النفع في بابه، بين فيه مؤلفه - رحمه الله - التوحيد وفضله، وما ينافيه من الشرك الأكبر', 'url' => $url.'/bengali/%e0%a6%a4%e0%a6%be%e0%a6%93%e0%a6%b9%e0%a7%80%e0%a6%a6%e0%a7%87%e0%a6%b0-%e0%a6%ae%e0%a6%b0%e0%a7%8d%e0%a6%ae%e0%a6%95%e0%a6%a5%e0%a6%be/', 'image' => $url.'/wp-content/uploads/2013/12/5520.png', 'author_id' => '2328', 'author_name' => 'আব্দররহমান বিন নাসের আস-সাদী', 'book_url' => $url.'/dl/books/bn5520.pdf' );
	$post[5521] = array( 'title' => ' তাওহীদ- শাইখুল ইসলাম মুহাম্মাদ ইবন আবদুল ওয়াহহাব', 'excerpt' => ' কিতাবুত-তাওহীদের অনুবাদ, যা সংকলন করেছেন শাইখুল ইসলাম মুহাম্মদ বিন আব্দুল ওহহাব রহ যে তাওহীদ আল্লাহ তাআলা মানুষের উপর অপরিহার্য করে দিয়েছেন, যার জন্য মানুষের সৃষ্টি। যার জন্য আল্লাহ কুরআন নাযিল করেছেন, সে তাওহীদের যথার্থ ব্যাখ্যার পাশাপাশি তাওহীদ বিরোধী আচার-আকীদা সম্পর্কে সতর্ক করা হয়েছে এ মূল্যবান গ্রন্থে কুরআন ও সুন্নাহর দলিল-প্রমাণের ভিত্তিতে।  كتاب يحتوي على بيان لعقيدة أهل السنة والجماعة بالدليل من القرآن الكريم والسنة النبوية،', 'url' => $url.'/bengali/%e0%a6%a4%e0%a6%be%e0%a6%93%e0%a6%b9%e0%a7%80%e0%a6%a6-%e0%a6%b6%e0%a6%be%e0%a6%87%e0%a6%96%e0%a7%81%e0%a6%b2-%e0%a6%87%e0%a6%b8%e0%a6%b2%e0%a6%be%e0%a6%ae-%e0%a6%ae%e0%a7%81%e0%a6%b9%e0%a6%be/', 'image' => $url.'/wp-content/uploads/2013/12/5521.png', 'author_id' => '2355', 'author_name' => 'মুহাম্মাদ ইবন আব্দুল ওয়াহহাব', 'book_url' => $url.'/dl/books/bn5521.pdf' );
	$post[5522] = array( 'title' => 'কালেমার মর্মকথা', 'excerpt' => ' বইটিতে কালেমার ফযীলত, রুকনসমূহ, শর্তাবলি ও মানব জীবনে এর প্রভাব সম্পর্কে আলোচনা করা হয়েছে।  يتحدث هذا الكتاب عن فضل لا إله إلا الله، وأركانه، وشروطه، ومقتضاه، وأثره في حياة البشرية.', 'url' => $url.'/bengali/%e0%a6%95%e0%a6%be%e0%a6%b2%e0%a7%87%e0%a6%ae%e0%a6%be%e0%a6%b0-%e0%a6%ae%e0%a6%b0%e0%a7%8d%e0%a6%ae%e0%a6%95%e0%a6%a5%e0%a6%be/', 'image' => $url.'/wp-content/uploads/2013/12/5522.png', 'author_id' => '2327', 'author_name' => 'আবু সালমান মুহাম্মাদ মুতিউল ইসলাম ইবন আলী আহমাদ', 'book_url' => $url.'/dl/books/bn5522.pdf' );
	$post[5523] = array( 'title' => 'সৎ মানুষের হৃদয়ে শয়তান প্রবেশের ধরণ ও প্রকৃতি', 'excerpt' => ' প্রত্যেক ব্যক্তির ঈমানের দৃঢ়তা, ইলামের গভীরতা ও ইবাদতে একাগ্রতা বিবেচনায় রেখে শয়তান তার উপর প্রভাব বিস্তার করার চেষ্টা করে, বক্ষ্যমান পুস্তিকায় এ সম্পর্কে আলোচনা করা হয়েছে।  هذا الكتاب القيم نبه أهل الإسلام إلى مداخل الشيطان إلى النفوس، وتنوع هذه المداخل بحسب طبيعة الشخص، وقوة إيمانه، ومبلغ علمه، وصدق تعبده.', 'url' => $url.'/bengali/%e0%a6%b8%e0%a7%8e-%e0%a6%ae%e0%a6%be%e0%a6%a8%e0%a7%81%e0%a6%b7%e0%a7%87%e0%a6%b0-%e0%a6%b9%e0%a7%83%e0%a6%a6%e0%a6%af%e0%a6%bc%e0%a7%87-%e0%a6%b6%e0%a6%af%e0%a6%bc%e0%a6%a4%e0%a6%be%e0%a6%a8/', 'image' => $url.'/wp-content/uploads/2013/12/5523.png', 'author_id' => '2331', 'author_name' => 'আব্দুল্লাহ আল খাতির', 'book_url' => $url.'/dl/books/bn5523.pdf' );
	$post[5524] = array( 'title' => 'প্রাথমিক ইসলাম শিক্ষা', 'excerpt' => ' বক্ষ্যমাণ গ্রন্থ শিশু-কিশোরদের উপযোগী ইসলামের মৌলিক বিষয় সংবলিত একটি টেক্সট বুক। এতে রয়েছে (১) ইসলামী আকীদাহ্, (২) মাসায়েল (৩)ইসলামী সংস্কৃতি, (৪)সীরাতুন্নবী, (৫) নির্বাচিত হাদীস।  هذا الكتاب القيم يحتوي على الأمور الآتية : (1) عقيدة كل مسلم، (2) مبادئ في الفقة، (3) آداب، وفضائل، وأذكار، (4) قبسات من السيرة النبوية، (5) أحاديث مختارة.', 'url' => $url.'/bengali/%e0%a6%aa%e0%a7%8d%e0%a6%b0%e0%a6%be%e0%a6%a5%e0%a6%ae%e0%a6%bf%e0%a6%95-%e0%a6%87%e0%a6%b8%e0%a6%b2%e0%a6%be%e0%a6%ae-%e0%a6%b6%e0%a6%bf%e0%a6%95%e0%a7%8d%e0%a6%b7%e0%a6%be/', 'image' => $url.'/wp-content/uploads/2013/12/5524.png', 'author_id' => '2347', 'author_name' => 'চৌধুরী আবুল কালাম আজাদ', 'book_url' => $url.'/dl/books/bn5524.pdf' );
	$post[5525] = array( 'title' => 'ইসলাম ও জাহেলিয়াতের দ্বন্দ্ব', 'excerpt' => ' বক্ষ্যমাণ গ্রন্থ মুহাম্মদ বিন আব্দুল ওহাব আত-তামীমী রহ. এর একটি গুরুত্বপূর্ণ রচনা, যাতে জাহেলী যুগের এমন ১০০ টি মাসায়েল উল্লেখ করা হয়েছে, রাসুল সাল্লাল্লাহু আলাইহি ওয়া সাল্লাম যেগুলোর বিরোধিতা করেছেন।هذا الكتاب القيم الذي ألفه الإمام المجدد الشيخ محمد بن عبد الوهاب التميمي- رحمه الله- يتضمن مائة مسئلة من مسائل الجاهلية التي خالف فيها رسول الله صلى الله عليه وسلم أهلها', 'url' => $url.'/bengali/%e0%a6%87%e0%a6%b8%e0%a6%b2%e0%a6%be%e0%a6%ae-%e0%a6%93-%e0%a6%9c%e0%a6%be%e0%a6%b9%e0%a7%87%e0%a6%b2%e0%a6%bf%e0%a6%af%e0%a6%bc%e0%a6%be%e0%a6%a4%e0%a7%87%e0%a6%b0-%e0%a6%a6%e0%a7%8d%e0%a6%ac/', 'image' => $url.'/wp-content/uploads/2013/12/5525.png', 'author_id' => '2355', 'author_name' => 'মুহাম্মাদ ইবন আব্দুল ওয়াহহাব', 'book_url' => $url.'/dl/books/bn5525.pdf' );
	$post[5526] = array( 'title' => 'মাতাপিতার প্রতি সন্তানের দায়িত্ব ও কর্তব্য', 'excerpt' => ' মাতাপিতার প্রতি সন্তানের দায়িত্ব ও কর্তব্য বিষয়ে একটি গুরুত্বপূর্ণ আলোচনা স্থান পেয়েছে আলোচ্য বইটিতে। আশা করি পাঠক মাত্রই উপকৃত হবেন।مسئوليات الأبناء نحو الوالدين: رسالةٌ توضِّح ما يجب على المسلم تجاه والدَيْه من خلال كتاب الله وسنة رسوله - صلى الله عليه وسلم -.', 'url' => $url.'/bengali/%e0%a6%ae%e0%a6%be%e0%a6%a4%e0%a6%be%e0%a6%aa%e0%a6%bf%e0%a6%a4%e0%a6%be%e0%a6%b0-%e0%a6%aa%e0%a7%8d%e0%a6%b0%e0%a6%a4%e0%a6%bf-%e0%a6%b8%e0%a6%a8%e0%a7%8d%e0%a6%a4%e0%a6%be%e0%a6%a8%e0%a7%87%e0%a6%b0/', 'image' => $url.'/wp-content/uploads/2013/12/5526.png', 'author_id' => '2354', 'author_name' => 'মুফতী আব্দুল মান্নান', 'book_url' => $url.'/dl/books/bn5526.pdf', 'publisher' => 'www.islamhouse.com' );
	$post[5527] = array( 'title' => 'নবুয়্যতি আলোকধারা', 'excerpt' => ' রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লামের সামগ্রিক জীবন ধারা, অভ্যাস-আচরণ, দিক-নিদের্শনা ও মানবতার ইহ-পারলৌকিক কল্যাণের উদ্দেশে ত্যাগ ও সবর বিশদভাবে ব্যাঞ্জনা পেয়েছে, খুবই যত্নে বর্ণিত হয়েছে, হাদিসসমগ্রে। হাদিসের এ গুরুত্বের নিরিখে জীবনসংলগ্ন মৌলিক কিছু বিষয়ে ব্যাখ্যা বিশ্লেষণসহ বিশটি হাদিসের একটি মূল্যবান সংগ্রহ হিসেবে তৈরি করা হয়েছে আমাদের বর্তমান বইটি। ঈমান-আক্বিদা, মৌলিক ইবাদত ও আমল-আখলাক বিষয়ে ব্যাখ্যা সংবলিত এ সংকলনটি আমাদের ধর্ম চর্চাকে আরো সমৃদ্ধ করবে বলে আশা রাখি।يحتوي هذا الكتاب على عشرين حديثًا من أحاديث رسول الله - صلى الله عليه وسلم -، وهي أحاديث من جوامع الكلِم، مع شرح ما ورد فيها من غريب الألفاظ، وعرض الدروس المستفادة منها.', 'url' => $url.'/bengali/%e0%a6%a8%e0%a6%ac%e0%a7%81%e0%a6%af%e0%a6%bc%e0%a7%8d%e0%a6%af%e0%a6%a4%e0%a6%bf-%e0%a6%86%e0%a6%b2%e0%a7%8b%e0%a6%95%e0%a6%a7%e0%a6%be%e0%a6%b0%e0%a6%be/', 'image' => $url.'/wp-content/uploads/2013/12/5527.png', 'author_id' => '2366', 'author_name' => 'শিহাব উদ্দিন হোসাইন আহমদ - সানাউল্লাহ নজির আহমদ - সিরাজুল ইসলাম আলী আকবর', 'book_url' => $url.'/dl/books/bn5527.pdf' );
