	$post[5621] = array( 'title' => 'বিশ্বের সবচেয়ে বড় সমস্যা হচ্ছে স্রষ্টাকে ভুলে যাওয়া', 'excerpt' => ' দার্শনিকভাবে দেখলে, বিশ্বের সবচেয়ে বড় সমস্যা হচ্ছে আল্লাহকে ভুলে যাওয়া, স্রষ্টাকে ভুলে যাওয়া৷ যিনি আমাকে বানিয়েছেন তাঁকে ভুলে যাওয়া৷ বক্ষ্যমান প্রবন্ধে এ বিষয়ে আলোকপাত করা হয়েছে। يتحدث الكاتب في هده المقالة عن ظاهرة الإلحاد التي تفشت في العالم المعاصر وأصبحت تمثل مشكلة حقيقية حتى في المجتمعات الإسلامية.', 'url' => $url.'/bengali/%e0%a6%ac%e0%a6%bf%e0%a6%b6%e0%a7%8d%e0%a6%ac%e0%a7%87%e0%a6%b0-%e0%a6%b8%e0%a6%ac%e0%a6%9a%e0%a7%87%e0%a6%af%e0%a6%bc%e0%a7%87-%e0%a6%ac%e0%a6%a1%e0%a6%bc-%e0%a6%b8%e0%a6%ae%e0%a6%b8%e0%a7%8d/', 'image' => $url.'/wp-content/uploads/2013/12/5621.png', 'author_id' => '2365', 'author_name' => 'শাহ আব্দুল হান্নান', 'book_url' => $url.'/dl/books/bn5621.pdf' );
	$post[5622] = array( 'title' => 'মুসলমানের চারিত্রিক গুণাবলী', 'excerpt' => ' আধুনিক অন্যান্য চিন্তা ও কর্মতৎপরতার সাথে ইসলামের পার্থক্য হচ্ছে ইসলামের রয়েছে এক প্রাকটিক্যাল রূপ, যা লালনে মানুষ একজন পরিপূর্ণ মানুষে পরিণত হয়। ইসলামের চারিত্রিক মৌলিকত্বগুলো কী, কীভাবে এর সফল রূপায়ণ সম্ভব, অন্যান্য চারিত্রিক রুলের সাথে ইসলামিক চারিত্রিক রুলের কোথায় ছেদ ও সংযোগ ইত্যাদি বিষয়ের একটি সারগর্ভ বর্ণনা রয়েছে এ লেখাটিতে, আশা সকলের ভাল লাগবে।  هذه المقالة تناولت العديد من الجوانب الأخلاقية التي ينبغي لكل مسلم أن يتحلى بها.', 'url' => $url.'/bengali/%e0%a6%ae%e0%a7%81%e0%a6%b8%e0%a6%b2%e0%a6%ae%e0%a6%be%e0%a6%a8%e0%a7%87%e0%a6%b0-%e0%a6%9a%e0%a6%be%e0%a6%b0%e0%a6%bf%e0%a6%a4%e0%a7%8d%e0%a6%b0%e0%a6%bf%e0%a6%95-%e0%a6%97%e0%a7%81%e0%a6%a3%e0%a6%be/', 'image' => $url.'/wp-content/uploads/2013/12/5622.png', 'author_id' => '2323', 'author_name' => 'আদেল বিন আলী আশ-শিদ্দী', 'book_url' => $url.'/dl/books/bn5622.pdf' );
	$post[5623] = array( 'title' => 'রোযাদারের কতিপয় ভুল-ত্রুটি', 'excerpt' => ' রমজানে রোযা পালনকালে আমরা নানা ভুল ভ্রান্তিতে আক্রান্ত হয়ে থাকি, যার প্রতিকার করা রমজানের রোযা শুদ্ধ হওয়ার জন্য অত্যন্ত জরুরী ও আবশ্যক-এতে কোন সন্দেহ নেই। বক্ষ্যমাণ ক্ষুদ্র নিবন্ধটিতে এ বিষয়ে বিস্তারিত আলোকপাত করার প্রয়াস চালান হয়েছে। আশা করি পাঠকদেরকে বিষয়টি খুবই আকৃষ্ট করবে এবং বিশুদ্ধভাবে রোযা পালনে সকলকে সহায়তা করবে।تتحدث هذه المقالة عما يرتكبه الصائمون من الأخطاء في حالة الصيام.', 'url' => $url.'/bengali/%e0%a6%b0%e0%a7%8b%e0%a6%af%e0%a6%be%e0%a6%a6%e0%a6%be%e0%a6%b0%e0%a7%87%e0%a6%b0-%e0%a6%95%e0%a6%a4%e0%a6%bf%e0%a6%aa%e0%a6%af%e0%a6%bc-%e0%a6%ad%e0%a7%81%e0%a6%b2-%e0%a6%a4%e0%a7%8d%e0%a6%b0/', 'image' => $url.'/wp-content/uploads/2013/12/5623.png', 'author_id' => '2333', 'author_name' => 'আব্দুল্লাহ বিন আব্দিররহমান আল-জিবরীন', 'book_url' => $url.'/dl/books/bn5623.pdf', 'publisher' => 'www.islamhouse.com' );
	$post[5624] = array( 'title' => 'নববর্ষ : দ্যূতিময় আগামীর নতুন প্রেরণা', 'excerpt' => ' সময়ই জীবন, আমাদের জীবন থেকে একটি বছর অতিবাহিত হল। এখন আমাদের লক্ষ্য করতে হবে গেল বছরে আমরা কি কি আমল করেছি। সাথে সাথে আত্মসমালোচনা করতে হবে। এ বছর এবং আগামী বছরগুলোতে আমাদেরকে আল্লাহভীতিতে অভ্যস্ত হতে হবে। বক্ষ্যমাণ প্রবন্ধে বিষয় সংক্ষিপ্তাকারে তুলে ধরা হয়েছে।الوقت هو الحياة، قد مضى منا عام من أوقاتنا، فلا بد علينا أن ننظر فيما فعلنا فيها، ونحاسب أنفسنا ونتقي الله في العام الراهن والأعوام القادمة، بل وفي كل وقت من أوقات حياتنا، وهذه المقالة تتحدث عن هذا الموضوع بشيء من الإيجاز.', 'url' => $url.'/bengali/%e0%a6%a8%e0%a6%ac%e0%a6%ac%e0%a6%b0%e0%a7%8d%e0%a6%b7-%e0%a6%a6%e0%a7%8d%e0%a6%af%e0%a7%82%e0%a6%a4%e0%a6%bf%e0%a6%ae%e0%a6%af%e0%a6%bc-%e0%a6%86%e0%a6%97%e0%a6%be%e0%a6%ae%e0%a7%80%e0%a6%b0/', 'image' => $url.'/wp-content/uploads/2013/12/5624.png', 'author_id' => '2347', 'author_name' => 'চৌধুরী আবুল কালাম আজাদ', 'book_url' => $url.'/dl/books/bn5624.pdf' );
	$post[5625] = array( 'title' => 'মূর্তি বনাম ভাস্কর্য : সমকালীন বিতর্ক', 'excerpt' => ' এ নিবন্ধে কুরআন হাদিসের আলোকে মূর্তি ও ভাস্কর্যের বিধান সম্পর্কে আলোচনা করা হয়েছে।هذه المقالة تبين موقف الشرع من صناعة الأصنام وتداولها وتعظيمها وكذلك منتجات الفن التشكيلي التي راجت هذه الأيام رواجا كثيرا.', 'url' => $url.'/bengali/%e0%a6%ae%e0%a7%82%e0%a6%b0%e0%a7%8d%e0%a6%a4%e0%a6%bf-%e0%a6%ac%e0%a6%a8%e0%a6%be%e0%a6%ae-%e0%a6%ad%e0%a6%be%e0%a6%b8%e0%a7%8d%e0%a6%95%e0%a6%b0%e0%a7%8d%e0%a6%af-%e0%a6%b8%e0%a6%ae%e0%a6%95/', 'image' => $url.'/wp-content/uploads/2013/12/5625.png', 'author_id' => '2337', 'author_name' => 'আব্দুল্লাহ শহীদ আব্দুর রহমান - চৌধুরী আবুল কালাম আজাদ', 'book_url' => $url.'/dl/books/bn5625.pdf' );
	$post[5626] = array( 'title' => 'মাযারে প্রচলিত বিদআত', 'excerpt' => ' বক্ষ্যমাণ প্রবন্ধে মাযারে প্রচলিত বিতআতের ভয়াবহতা সম্পর্কে আলোচনা করা হয়েছে।هذه المقالة تتحدث عن خطر البدع والخرافات التي انتشرت في المزارات.  ', 'url' => $url.'/bengali/%e0%a6%ae%e0%a6%be%e0%a6%af%e0%a6%be%e0%a6%b0%e0%a7%87-%e0%a6%aa%e0%a7%8d%e0%a6%b0%e0%a6%9a%e0%a6%b2%e0%a6%bf%e0%a6%a4-%e0%a6%ac%e0%a6%bf%e0%a6%a6%e0%a6%86%e0%a6%a4/', 'image' => $url.'/wp-content/uploads/2013/12/5626.png', 'author_id' => '2344', 'author_name' => 'কাউসার বিন খালিদ', 'book_url' => $url.'/dl/books/bn5626.pdf' );
	$post[5627] = array( 'title' => 'বিদআত (পর্ব ১)', 'excerpt' => ' বিদআত : প্রবন্ধটিতে নিম্নোক্ত বিষয়গুলো স্থান পেয়েছে : বিদআতের অর্থ ও তার প্রকার। বিদআতে হাসানার অস্তিত্ব কি বিদ্যমান ? যে সমস্ত কারণে বিদআতের উৎপত্তি ঘটে। বিদআতের অপকার। বিদআতী সম্প্রদায়ের ব্যাপারে সালাফের অবস্থান। আধুনিক সময়ের বিদআত। বিদআতের কুফল। হেকমতের মাধ্যমে বিদআতের অপনোদন।1- معنى البدعة وأقسامها.  2- هل في الدين بدعة حسنة؟  3- الأسباب التي أدَّت إلى ظهور البدع.  4- مفاسد البدع.  ', 'url' => $url.'/bengali/%e0%a6%ac%e0%a6%bf%e0%a6%a6%e0%a6%86%e0%a6%a4-%e0%a6%aa%e0%a6%b0%e0%a7%8d%e0%a6%ac-%e0%a7%a7/', 'image' => $url.'/wp-content/uploads/2013/12/5627.png', 'author_id' => '2341', 'author_name' => 'ইকবাল হোছাইন মাছুম ', 'book_url' => $url.'/dl/books/bn5627.pdf' );
