	$post[13905] = array( 'title' => 'شخصية المرأة المسلمة كما يصوغها الإسلام', 'excerpt' => 'شخصية المرأة المسلمة كما يصوغها الإسلام في الكتاب والسنة    يبرز شخصية المرأة المسلمة كما أراد لها الإسلام أن تكون،', 'url' => $url.'/arabic/%d8%b4%d8%ae%d8%b5%d9%8a%d8%a9-%d8%a7%d9%84%d9%85%d8%b1%d8%a3%d8%a9-%d8%a7%d9%84%d9%85%d8%b3%d9%84%d9%85%d8%a9-%d9%83%d9%85%d8%a7-%d9%8a%d8%b5%d9%88%d8%ba%d9%87%d8%a7-%d8%a7%d9%84%d8%a5%d8%b3%d9%84/', 'image' => $url.'/wp-content/uploads/2014/04/arabic_The_Ideal_Muslimah.png', 'author_id' => '2032', 'author_name' => 'محمد فؤاد الهاشمي', 'book_url' => $url.'/dl/books/arabic_The_Ideal_Muslimah.pdf' );
	$post[13908] = array( 'title' => 'هذه دعوتنا', 'excerpt' => 'هذه دعوتنا  محاضرة مفرغة لفضيلة الشيخ محمد ناصر الدين الألباني - رحمه الله - تكلم فيها عن أهمية الدعوة ومكانتها وهى ضمن سلسة الهدى والنور .', 'url' => $url.'/arabic/%d9%87%d8%b0%d9%87-%d8%af%d8%b9%d9%88%d8%aa%d9%86%d8%a7/', 'image' => $url.'/wp-content/uploads/2014/04/arabic_This_is_Our_Call.png', 'author_id' => '2060', 'author_name' => 'محمد ناصر الدين الالباني', 'book_url' => $url.'/dl/books/arabic_This_is_Our_Call.pdf' );
