	$post[15711] = array( 'title' => 'أسئلة بيانية في القرآن الكريم', 'excerpt' => 'يضم هذا الكتاب أسئلة وأجابات حول الأسلوب البياني في القرآن الكريم، مرتبة حسب تسلسل الموضوعات في المصحف الشريف.  ويجد القارئ لفتات عميقة، ونظرات صائبة، تدل على حسن التفهم، والربط بين الآيات، تأكيداً لإعجاز القرآن الكريم، وأنه موحى من لدن حكيم عليم.', 'url' => $url.'/arabic/%d8%a3%d8%b3%d8%a6%d9%84%d8%a9-%d8%a8%d9%8a%d8%a7%d9%86%d9%8a%d8%a9-%d9%81%d9%8a-%d8%a7%d9%84%d9%82%d8%b1%d8%a2%d9%86-%d8%a7%d9%84%d9%83%d8%b1%d9%8a%d9%85-2/', 'image' => $url.'/wp-content/uploads/2015/04/arabic-aselah-bayaniyah.png', 'author_id' => '6047', 'author_name' => 'الدكتور فاضل صالح السامرائي ', 'book_url' => $url.'/books/ar_asela_byanya_fe_alkuran_alkareem.pdf', 'publisher' => 'مكتبة الصحابة -الشارقة' );
