	$post[15942] = array( 'title' => '30 Langkah Mendidik Anak Agar Mengamalkan Ajaran Agama', 'excerpt' => 'Pada tulisan ini, penulis menyebutkan 30 langkah praktis mendidik anak agar mengamalkan agama ini, dengan menyebutkan contoh permisalan yang cemerlang dari generasi salafussoleh ketika mendidik putra-putri mereka.', 'url' => $url.'/indonesian/30-langkah-mendidik-anak-agar-mengamalkan-ajaran-agama/', 'image' => $url.'/wp-content/uploads/2014/06/Ajaran-Agama1.jpg', 'author_id' => '6069', 'author_name' => 'Eko Haryanto Abu Ziyad', 'book_url' => $url.'/books/id_30_Langkah_dalam_Mendidik_Anak.pdf' );
	$post[15946] = array( 'title' => '48 Persoalan Puasa', 'excerpt' => 'Buku kecil yang berisi tentang jawaban dari 48 pertanyaan seputar puasa, terdiri dari pertanyaan-pertanyaan yang amat sering diajukan.', 'url' => $url.'/indonesian/48-persoalan-puasa/', 'image' => $url.'/wp-content/uploads/2014/06/persoalan_puasa.jpg', 'author_id' => '385', 'author_name' => 'Muhammad bin Shalih Al Utsaimin', 'book_url' => $url.'/books/id_48_persoalan_puasa.pdf', 'translator' => 'Syafar Abu Difa' );
	$post[15949] = array( 'title' => '50 Nasehat untuk Wanita', 'excerpt' => 'Buku ini berisi 50 nasehat penting berkaitan dengan tauhid dan akhlak yang penulis wasiatkan kepada para wanita muslimah agar senantiasa mengingat Allah dan mematuhi perintah-Nya serta larangan-Nya disetiap aspek kehidupannya, dimanapun dia berada, dan apapun kegiatannya.', 'url' => $url.'/indonesian/50-nasehat-untuk-wanita/', 'image' => $url.'/wp-content/uploads/2014/06/Nasehat_untuk_Wanita1.jpg', 'author_id' => '6070', 'author_name' => 'Abdul Aziz bin Abdullah al-Muqbil', 'book_url' => $url.'/books/id_50_Nasehat_untuk_Wanita.pdf', 'translator' => 'Amrozi Muhammad Rais' );
	$post[15954] = array( 'title' => '70 Pertanyaan Seputar Jenazah', 'excerpt' => 'Buku ini berisi tujuh puluh Tanya jawab tentang hal-hal yang berkaitan dengan jenazah, baik tentang bagaimana mengurus jenazah, dari mendampingi orang yang sakaratul maut hingga menguburkannya. Juga pertanyaan seputar kebiasaan kaum muslimin dalam menghadapi jenazah seperti membacakan surat Yasin dan sebagainya.', 'url' => $url.'/indonesian/70-pertanyaan-seputar-jenazah/', 'image' => $url.'/wp-content/uploads/2014/06/Seputar_Jenazah.jpg', 'author_id' => '385', 'author_name' => 'Muhammad bin Shalih Al Utsaimin', 'book_url' => $url.'/books/id_70_Pertanyaan_Seputar_Jenazah.pdf', 'publisher' => 'IslamHouse' );
	$post[15958] = array( 'title' => 'Beberapa Nasehat Untuk Keluarga Muslim', 'excerpt' => 'Buku ini memuat nasehat kepada setiap individu dalam rumah tangga seorang muslim', 'url' => $url.'/indonesian/beberapa-nasehat-untuk-keluarga-muslim/', 'image' => $url.'/wp-content/uploads/2014/06/islamic_family.jpg', 'author_id' => '6071', 'author_name' => 'Yusuf bin Abdullah At Turki', 'book_url' => $url.'/books/id_advices_to_the_islamic_family.pdf', 'publisher' => 'islamhouse', 'translator' => 'ABU AZKA FARIDY' );
	$post[15961] = array( 'title' => 'Agama Islam Solusi Problematika Kehidupan', 'excerpt' => 'Rangkuman buku : Agama yang benar akan mememecahkan segala macam persoalan hidup, adalah sebuah buku kecil yang didalamnya penulis – semoga Allah merahmatinya - menjelaskan beberapa kebaikan dan kesempurnaan agama Islam.', 'url' => $url.'/indonesian/agama-islam-solusi-problematika-kehidupan/', 'image' => $url.'/wp-content/uploads/2014/06/Solusi_Problematika_Kehidupan.jpg', 'author_id' => '6072', 'author_name' => 'Abdurrahman As Sa&#039;dy', 'book_url' => $url.'/books/id_Agama_yang_Benar_Solusi_Problematika_Kehidupan .pdf', 'translator' => 'Muhammad Iqbal A. Gazali' );
	$post[15964] = array( 'title' => 'Akidah Setiap Muslim', 'excerpt' => 'Soal Jawab Aqidah : Sebuah buku kecil yang memuat 45 tanya jawab seputar aqidah, yang disertai dalil dari al quran dan sunnah sehingga pembaca tenang dalam mendengar jawabanya, karena masalah aqidah adalah masalah yang sangat urgen dalam kehidupan seseorang dalam Islam karena ia merupakan sumber keselamatan baginya baik didunia maupun diakhirat kela', 'url' => $url.'/indonesian/akidah-setiap-muslim/', 'image' => $url.'/wp-content/uploads/2014/06/id_akeeda_ahl_sunnah.jpg', 'author_id' => '6073', 'author_name' => 'Muhammad Jamil Zainu', 'book_url' => $url.'/books/id_akeeda_ahl_sunnah.pdf', 'translator' => 'Mohammad Muinuddin Bashri' );
	$post[15967] = array( 'title' => 'Bantahan terhadap paham pluralisme agama', 'excerpt' => 'Bangsa-bangsa kafir menyelenggarakan berbagai macam konferensi dengan berbagai nama, misalnya: “Pendekatan antar Agama”, “Penyatuan Agama”, “Persaudaraan antar Agama”, atau “Dialog Peradaban”. Hal ini merupakan salah satu penopang terburuk dua gua yang amat gelap yaitu “Tatanan Dunia Baru” dan “Globalisasi” yang memiliki tujuan menyebarkan kekufuran, atheisme, kebebasan, menghapus nilai-nilai Islam dan mengubah fitrah kemanusiaan.', 'url' => $url.'/indonesian/bantahan-terhadap-paham-pluralisme-agama/', 'image' => $url.'/wp-content/uploads/2014/06/Untitled-1.jpg', 'author_id' => '6074', 'author_name' => 'Bakr Bin Abdullah Abu Zaid', 'book_url' => $url.'/books/id_albtal_theory_alkhlt_between_islam_and_other_deen.pdf', 'translator' => 'Ahmad Nizaruddin' );
	$post[15973] = array( 'title' => 'Islam Pondasi dan Landasannya', 'excerpt' => 'Buku yang sangat bagus menjelaskan tentang dasar-dasar agama islam dan landasannya secara terperinci disertai dalil-dalil yang sahih baik dari alquran maupun sunnah serta akibat buruk bagi orang yang tidak mau berpegang kepada agama yang mulia ini .', 'url' => $url.'/indonesian/islam-pondasi-dan-landasannya/', 'image' => $url.'/wp-content/uploads/2014/06/usoolh_wa_mabadeoh.jpg', 'author_id' => '6075', 'author_name' => 'Muhammad Abdullah Shalih Al-Suhaim', 'book_url' => $url.'/books/id_alislam_usoolh_wa_mabadeoh.pdf', 'translator' => 'Eko Haryanto Abu Ziyad' );
	$post[15976] = array( 'title' => 'MASJID &amp; PENGARUHNYA DALAM DUNIA PENDIDIK', 'excerpt' => 'Menjelaskan tentang Kedudukan &amp; Peranan Masjid Dalam Islam, serta Tugas Universalnya bagi Kemaslahatan Dunia &amp; Akhirat, Urgensi Masjid &amp; Keterikatannya dengan Masyarakat Muslim, Masjid merupakan Media Implementasi Amal dalam rangka mengajak kepada Iman &amp; Amal Soleh, Pendidikan, Pembudayaan, Pembinaan dan Penyuluhan.', 'url' => $url.'/indonesian/masjid-pengaruhnya-dalam-dunia-pendidik/', 'image' => $url.'/wp-content/uploads/2014/06/altarboy_to_masjeed-e1440668702781.jpg', 'author_id' => '6076', 'author_name' => 'Shalih Ghanim Al-Sadlan', 'book_url' => $url.'/books/id_althar_altarboy_to_masjeed.pdf', 'translator' => 'Muhammad Khairuddin' );
