	$post[16390] = array( 'title' => 'الأحاديث المشكلة الواردة في تفسير القرآن الكريم: عرض ودراسة', 'excerpt' => 'يتناول هذا البحث الأحاديث التي يوهم ظاهرها التعارض مع القرآن الكريم والأحاديث التي ترد في التفسير وتعد مشكلة في ذاتها أو يوهم ظاهرها التعارض فيما بينها.', 'url' => $url.'/arabic/%d8%a7%d9%84%d8%a3%d8%ad%d8%a7%d8%af%d9%8a%d8%ab-%d8%a7%d9%84%d9%85%d8%b4%d9%83%d9%84%d8%a9-%d8%a7%d9%84%d9%88%d8%a7%d8%b1%d8%af%d8%a9-%d9%81%d9%8a-%d8%a7%d9%84%d8%aa%d9%81%d8%b3%d9%8a%d8%b1/', 'image' => $url.'/wp-content/uploads/2015/11/الاحاديث-المشكاة-.png', 'author_id' => '6486', 'author_name' => 'محمد بن عبد العزيز بن مقرن القصير', 'book_url' => $url.'/books/ar_alahades_almoshkala_alwareda_fi_tafsier_alquran.pdf', 'publisher' => 'دار ابن الجوزي ' );
