	$post[22053] = array( 'title' => 'Skraćena verzija knjige Kako je klanjao Allahov Poslanik', 'excerpt' => 'Skraćena verzija knjige Kako je klanjao Allahov Poslanik    Mala knjižica koja pojašnjava propise namaza i njegova svojstva, upravo onako kako je klanjao Allahov Poslanik sallallahu alejhi ve sellem.', 'url' => $url.'/bosnian/skracena-verzija-knjige-kako-je-klanjao-allahov-poslanik/', 'image' => $url.'/wp-content/uploads/2015/08/bs_Albani_Skracena_verzija_knjige_Kako_je_Poslanik_klanjao-1.jpg', 'author_id' => '408', 'author_name' => 'Muhammad Nashiruddin Al-Albani', 'book_url' => $url.'/books/bs_Albani_Skracena_verzija_knjige_Kako_je_Poslanik_klanjao.pdf', 'publisher' => 'Pomoćni ured za dawu - Riyadh', 'translator' => 'Elvedin Huseinbašić' );
