	$post[22060] = array( 'title' => 'The Concept of Prophethood  in Islam and Hinduism', 'excerpt' => 'In this short publication we are going to compare the concept of Avatar or incarnation of God on earth according to the Hindu philosophy with the concept of prophethood or messengership in the Islamic belief system. We will also explain why Muslims do not believe in incarnation as interpreted by Hindu scholars and philosophers.', 'url' => $url.'/english/prophethood-in-islam-and-hinduism/', 'image' => $url.'/wp-content/uploads/2015/08/Prophethood_in_Islam_and_Hinduism.jpg', 'author_id' => '164', 'author_name' => 'E-Da`wah Committee (EDC)', 'book_url' => $url.'/books/en_Prophethood_in_Islam_and_Hinduism.pdf', 'publisher' => 'E-Da`wah Committee' );
	$post[22066] = array( 'title' => 'Blagodati Džennta u svjetlu Kur’ana i sunneta', 'excerpt' => 'Blagodati Džennta u svjetlu Kur’ana i sunneta    Knjiga koja ima za cilj dvije stvari:  - da ukaže vjerniku na djela koja će ga dovesti do Dženneta i  - da da tačan i precizan opis, zasnovak na Kur’anu i sunnetu, užitaka koje će imati vjernik u Džennetu.  ', 'url' => $url.'/bosnian/blagodati-dzennta-u-svjetlu-kurana-sunneta/', 'image' => $url.'/wp-content/uploads/2015/08/bs_Blagodati_Dzenneta_u_svjetlu_Kurana_i_Sunneta-1.jpg', 'book_url' => $url.'/books/bs_Blagodati_Dzenneta_u_svjetlu_Kurana_i_Sunneta.pdf', 'publisher' => 'Islam House' );
