	$post[22438] = array( 'title' => 'Bazat e Teuhidit – Monoteizmi Islam', 'excerpt' => 'Bazat e Teuhidit – Monoteizmi Islam  Tevhidi, njësimi i Zotit, është thelbi i besimit islam. Njerëzit janë të urdhëruar ta zbatojnë këtë koncept në tokë, në çdo hap të jetës, që nga ditët e Ademit. Në këtë libër fillimisht sqarohen kategoritë e tevhidit e më pas libri në mënyrë të qartë flet për kategorinë: Tevhidul – Ibade (Njësimin e Allahut në adhurim) dhe sqaron rëndësinë e tij pasi që të gjithë Pejgamberët (lavdërimi dhe shpëtimi i Allahut qofshin mbi ta) kanë thirrur në të. Libri flet për bindjet dhe veprat e njerëzve të cilat bien në kundërshtim me të, e të cilat fatkeqësisht janë shumë të përhapura në mesin e muslimanëve edhe në ditët e sotme.', 'url' => $url.'/albanian/bazat-e-teuhidit-monoteizmi-islam/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Bazat_e_Teuhidit-1.jpg', 'author_id' => '143', 'author_name' => 'Bilal Philips', 'book_url' => $url.'/books/sq_Bazat_e_Teuhidit.pdf', 'publisher' => 'Islam House' );
	$post[22443] = array( 'title' => 'Besimi - Bazat, Esenca, Negacioni', 'excerpt' => 'Besimi - Bazat, Esenca, Negacioni  Përshkrimi    Akideja – Besimi, është pjesa më e rëndësishme që duhet ta dijë myslimani rreth fesë së tij. Ky libër që po u ofrojmë është shkruar në lëmin e akides dhe është ndër librat bashkëkohorë më të njohur. Libri është i bazuar në kuptimin e akides sipas gjeneratave të para islame, i mbështetur në argumente dhe larg devijimeve të grupeve të ndryshme.  Libri ka tre kapituj:  I pari: Flet për gjashtë kushtet e besimit.  I dyti: Flet për thelbin dhe esencën e besimit.  I treti: Flet për fjalët dhe veprat që të nxjerrin prej besimit.', 'url' => $url.'/albanian/besimi-bazat-esenca-negacioni/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Besimi_bazat_esenca_dhe_negacionet-1.jpg', 'author_id' => '407', 'author_name' => 'Muhammad Naim Va-Sin', 'book_url' => $url.'/books/sq_Besimi_bazat_esenca_dhe_negacionet.pdf', 'publisher' => 'Islam House' );
	$post[22446] = array( 'title' => 'Besimi i Ehli Sunetit', 'excerpt' => 'Besimi i Ehli Sunetit  Besimi i Ehli Sunetit: Ky libërth përmban sqarimin e akides së Ehli Synetit dhe Xhematit në kaptinën e njësimit të Allahut, emrave të atributeve të Tij si dhe në kapitujt e besimi në Melekë, Libra, Pejgamberë, Botës Tjetër dhe Caktimit të Allahut për të mirë dhe të keqe.', 'url' => $url.'/albanian/besimi-i-ehli-sunetit/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Besimi_i_Ehli_Sunetit-1.jpg', 'author_id' => '362', 'author_name' => 'MUHAMED SALIH UTHEJMIN', 'book_url' => $url.'/books/sq_Besimi_i_Ehli_Sunetit.pdf', 'publisher' => 'Islam House' );
	$post[22449] = array( 'title' => 'Bisedë e përditshme - Shqipe, Angleze dhe Arabe', 'excerpt' => 'Bisedë e përditshme - Shqipe, Angleze dhe Arabe Ky libër përmban fjalë dhe biseda në gjuhët: shqip, anglisht dhe arabisht. Libri është', 'url' => $url.'/albanian/bisede-e-perditshme-shqipe-angleze-dhe-arabe/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Bisede_e_perditshme_Shqipe_Angleze_dhe_Arabe-1.jpg', 'book_url' => $url.'/books/sq_Bisede_e_perditshme_Shqipe_Angleze_dhe_Arabe.pdf', 'publisher' => 'Islam House' );
	$post[22452] = array( 'title' => 'Disa bindje te Shi’iteve', 'excerpt' => 'Disa bindje te Shi’iteve  Shiitët janë një ndër grupet e devijuara më të përhapura në botën islame. Idetë dhe mendimet e tyre janë nuk përkojnë me burimet Islame. Ky libër flet rreth bindjeve dhe kundërshtimeve të tyre me Islamin. Megjithëse i shkurtër, ky libër me fakte dhe argumente qartëson devijimin dhe rrezikshmërinë e tyre për Islamin dhe myslimanët.  ', 'url' => $url.'/albanian/disa-bindje-te-shiiteve/', 'image' => $url.'/wp-content/uploads/2015/09/sq_creed_the_shiites-1.jpg', 'author_id' => '6427', 'author_name' => 'Abdullah b. Muhamed Es Selefij', 'book_url' => $url.'/books/sq_creed_the_shiites.pdf', 'publisher' => 'Islam House' );
	$post[22455] = array( 'title' => 'Dëshiroj të pendohem, por...!', 'excerpt' => 'Dëshiroj të pendohem, por...!  Dëshiroj të pendohem, por... : Ky libërth përmban një parathënie rreth rrezikut të përçmimit të mëkateve, pastaj një koment të shkurtër rreth kushteve të pendimit – Teubes dhe disa udhëzime për shërim të shpirtrave. Libërthi përfundon me disa fetva për të penduarit, të mbështetura në argumentet e Kuranit dhe Sunetit dhe fjalët e Dijetarëve.', 'url' => $url.'/albanian/deshiroj-te-pendohem-por/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Deshiroj_te_pendohempor-1.jpg', 'author_id' => '432', 'author_name' => 'Muhammed Salih Al-Munajjid', 'book_url' => $url.'/books/sq_Deshiroj_te_pendohem,por.pdf', 'publisher' => 'Islam House' );
	$post[22459] = array( 'title' => 'Dyzet Hadithe nga Imam Neveviu', 'excerpt' => 'Dyzet Hadithe nga Imam Neveviu  Ky është një ndër librat e shkurtra (El Metn) më të njohura. Këto dyzet hadithe janë të përmendura pa zinxhirin e transmetimit dhe përfshinë fusha të ndryshme islame, ku çdo hadith prej tyre konsiderohet si një bazë madhështore e bazave të fesë. Çdo musliman duhet t’i dijë këto hadithe për shkak të rëndësisë së mësimeve të cilat i përmbajnë.', 'url' => $url.'/albanian/dyzet-hadithe-nga-imam-neveviu/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Dyzet_hadithe_nga_Imam_Neveviut-1.jpg', 'author_id' => '236', 'author_name' => 'Imam An-Nawawi', 'book_url' => $url.'/books/sq_Dyzet_hadithe_nga_Imam_Neveviut.pdf', 'publisher' => 'Islam House' );
	$post[22463] = array( 'title' => 'Ejani në shpëtim!', 'excerpt' => 'Ejani në shpëtim!  “Duke pasur parasysh rëndësinë e praktikimit të mësimeve islame, të cilave pas besimit, me vlerë dhe rëndësi iu paraprinë namazi, na imponohet që të jemi të mobilizuar në sqarimin e këtyre mësimeve si nga këndi i ndriçimit të vlerës së secilit prej tyre, ashtu edhe në shpjegimin praktik se si duhet të kryhet cilido. Prandaj ju ofrojmë këtë udhëzues të ilustruar për mësimin e namazit dhe gabimet që bëhen në të.”', 'url' => $url.'/albanian/ejani-ne-shpetim/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Ejani_ne_Shpetim-1.jpg', 'author_id' => '6428', 'author_name' => 'Eroll Nesimi', 'book_url' => $url.'/books/sq_Ejani_ne_Shpetim.pdf', 'publisher' => 'Islam House' );
	$post[22466] = array( 'title' => 'Ejani në shpëtim! – version i shkurtuar', 'excerpt' => 'Ejani në shpëtim! – version i shkurtuar Të gjitha lavdërimet i takojnë All-llahut (subhanehu ue teala). Atë e falënderojmë', 'url' => $url.'/albanian/ejani-ne-shpetim-version-i-shkurtuar/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Ejani_ne_shpetim_version_i_shkurtuar-1.jpg', 'author_id' => '6428', 'author_name' => 'Eroll Nesimi', 'book_url' => $url.'/books/sq_Ejani_ne_shpetim_version_i_shkurtuar.pdf', 'publisher' => 'Islam House' );
	$post[22469] = array( 'title' => 'Etika Islame', 'excerpt' => 'Etika Islame  Ky është një libër përmbledhës që përmban një varg rregullash për të cilat ka nevojë muslimani gjatë jetës së tij të përditshme. Këtë libër ia paraqes si këshillë umetit: Mësim për të paditurin, përkujtim për harrestarin dhe vërej-tje për shpërfillësin e këtyre rregullave.  Ky libër është këshillë për besimtarin, që të jetojë me udhëzimet e Pejgamberit (sal-lAllahu alejhi ue sel-lem)', 'url' => $url.'/albanian/etika-islame/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Etika_islame-1.jpg', 'author_id' => '6429', 'author_name' => 'Abdul Hamid Es Suhejbani', 'book_url' => $url.'/books/sq_Etika_islame.pdf', 'publisher' => 'Islam House' );
	$post[22472] = array( 'title' => 'Feja e vërtetë e Zotit', 'excerpt' => 'Feja e vërtetë e Zotit  Cilat janë rregullat e fesë vërtetë? Si duhet të jetë lidhja mes Krijuesit dhe krijesës? Si ta njohësh Zotin tënd, që ta adhurosh dhe ta pasosh rrugën e Tij të drejtë?   Autori iu përgjigjet këtyre dhe shumë pyetjeve tjera me shembuj të qartë dhe gjithashtu sjell citate nga librat e shenjtë të ithtarëve të librit.   Libri në shqip përfundon me një rezyme rreth biografisë së autorit i cili edhe është një nga thirrësit e mirënjohur.', 'url' => $url.'/albanian/feja-e-vertete-e-zotit/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Feja_e_vertete_e_Zotit-1.jpg', 'author_id' => '143', 'author_name' => 'Bilal Philips', 'book_url' => $url.'/books/sq_Feja_e_vertete_e_Zotit.pdf', 'publisher' => 'Islam House' );
	$post[22475] = array( 'title' => 'Fragmente nga jeta e Sahabëve', 'excerpt' => 'Fragmente nga jeta e Sahabëve  Ky libër paraqet fragmente nga jeta e një numër të shokëve të Pejgamberit (paqja dhe mëshira e Allahut qofshin mbi të). Atyre të cilët ishin yje të udhëzimit dhe të cilët u edukuan në djepin e shkollës profetike. Lexuesi që hulumton bukurinë gjuhësore dhe artin e tregimit do ta gjen në këtë libër. Ai që mundohet që t’i merr shëmbëlltyrë këta burra fisnikë do ta arrin dëshirën e tij, sikur që edhe ai që e hulumton të vërtetën historike do ta percepton atë.', 'url' => $url.'/albanian/fragmente-nga-jeta-e-sahabeve/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Fragmente_nga_jeta_e_Sahabeve-1.jpg', 'author_id' => '6430', 'author_name' => 'Abdurr Rrahman Rafet El Basha', 'book_url' => $url.'/books/sq_Fragmente_nga_jeta_e_Sahabeve.pdf', 'publisher' => 'Islam House' );
	$post[22479] = array( 'title' => 'Furnizimi më i mirë', 'excerpt' => 'Furnizimi më i mirë  Furnizimi më i mirë - deri në Ditën e Premtimit (Ringjalljes) veç farzit (obligimit) sipas udhëzimit të më të mirit prej njerëzve - Profetit Muhamed (lavdërimi dhe paqja e Allahut qoftë mbi të ). Ky libër shtjellon këto tematika:  Së pari: Veprime, mirësia e të cilave në dynja dhe Amshim i kthehet vetëm atij që i ka kryer.  Së dyti: Veprime, dobia e të cilave në dynja dhe në Amshim i kthehet kryerësit të tyre dhe tjetërkujt.', 'url' => $url.'/albanian/furnizimi-me-i-mire/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Furnizimi_me_i_mire-1.jpg', 'book_url' => $url.'/books/sq_Furnizimi_me_i_mire.pdf', 'publisher' => 'Islam House' );
	$post[22482] = array( 'title' => 'Gabime në të cilat bien disa haxhilerë', 'excerpt' => 'Gabime në të cilat bien disa haxhilerë  Ky libërth sqaron disa nga ritualet e haxhit, duke bërë të qartë mënyrën e saktë të kryerjes së tyre në pajtim me traditën e Pejgamberit (lavdërimi dhe shpëtimi i Allahut qofshin mbi të) dhe duke tërhequr vërejtjen nga gabimet në të cilat bien disa haxhilerë. Këto rituale dhe gabimet në to janë: Ihrami, tavafi, dy rekatet pas tavafit, ngjitja mbi Safa dhe Merve, qëndrimi në Arafat, hedhja e gurëve, tavafi lamtumirës.', 'url' => $url.'/albanian/gabime-ne-te-cilat-bien-disa-haxhilere/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Gabime_ne_te_cilat_bien_disa_haxhilere-1.jpg', 'author_id' => '362', 'author_name' => 'MUHAMED SALIH UTHEJMIN', 'book_url' => $url.'/books/sq_Gabime_ne_te_cilat_bien_disa_haxhilere.pdf', 'publisher' => 'Islam House' );
	$post[22486] = array( 'title' => 'Međusobno uvažavanje Ehli-bejta i ashaba', 'url' => $url.'/bosnian/medusobno-uvazavanje-ehli-bejta-i-ashaba/', 'image' => $url.'/wp-content/uploads/2015/09/Bosnian-Medusobno-uvazavanje-Ehli-bejta-i-ashaba.jpg', 'book_url' => $url.'/dl/books/Bosnian-Medusobno-uvazavanje-Ehli-bejta-i-ashaba.pdf', 'translator' => 'Nedim Haračić' );
	$post[22491] = array( 'title' => 'Islami dhe Krishterizmi', 'excerpt' => 'Islami dhe Krishterizmi  “Viteve të fundit publiku shqiptar është ballafaquar me  literaturë të shumtë rreth Islamit dhe Krishterimit. Libri të cilin e keni në duar synon që të japë një pikëpamje alternative në shumicën e çështjeve të cilat i ndajnë këto dy besime. Duke konsultuar burime autoktone të dy besimeve sikur edhe duke hyrë në thellësinë e dorëshkrimeve të vjetra të shkrimeve kristiane, e edhe atyre kur‟anore gjithashtu, kemi dhënë ide të përgjithshme për çështje si: a është Jezusi (Isai a.s) Zot, a u kryqëzua ai për të na larë nga mëkatet, cila është Fjala e pandryshuar e Perëndisë – Bibla apo Kurani, etj.”', 'url' => $url.'/albanian/islami-dhe-krishterizmi/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Islami_dhe_Krishterizmi-1.jpg', 'book_url' => $url.'/books/sq_Islami_dhe_Krishterizmi.pdf', 'publisher' => 'Islam House' );
	$post[22494] = array( 'title' => 'Islami - ndikimi i tij në civilizim dhe merita e tij për njerëzimin', 'excerpt' => 'Islami - ndikimi i tij në civilizim dhe merita e tij për njerëzimin  Ky libër në bazë është punim i ofruar Këshillit Nacional për Kulturë i Kuvajtit. Libri shtjellon ndikimin e Islamit në civilizimin njerëzor në vazhdimësi që nga periudha profetike. Por, nëse duhet përmbledhur sferat në të cilat ka ndodhur ky ndikim më tepër, atëherë duhet zgjedhur dhjetë dhurata të cilat ia ka ofruar Islami njerëzimit duke filluar nga besimi i çiltër, të drejtat e gruas, afirmimi i lidhjes mes fesë dhe shkencës etj.', 'url' => $url.'/albanian/islami-ndikimi-i-tij-ne-civilizim-dhe-merita-e-tij-per-njerezimin/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Islami_dhe_ndikimi_i_tij_ne_civilizim-1.jpg', 'author_id' => '163', 'author_name' => 'Ebul-Hasen en-Nedevi', 'book_url' => $url.'/books/sq_Islami_dhe_ndikimi_i_tij_ne_civilizim.pdf', 'publisher' => 'Islam House' );
	$post[22497] = array( 'title' => 'Jeta e profetit Muhamed (sal-lAllahu alejhi ue sel-lem)', 'excerpt' => 'Jeta e profetit Muhamed (sal-lAllahu alejhi ue sel-lem)  Ky libër përmban në vete jetëpërshkrimin e të Dërguarit (sal-lAllahu alejhi ue sel-lem) që nga fillimi e deri në fund. I shkruar me një metodologji të lehtë dhe tërheqëse është i përshtatshëm për fëmijët dhe moshat e reja.', 'url' => $url.'/albanian/jeta-e-profetit-muhamed-sal-lallahu-alejhi-ue-sel-lem/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Jeta_e_Profetit_Muhamed-1.jpg', 'author_id' => '6431', 'author_name' => 'Lejla Azzam &amp; Aishe Gouvernuer', 'book_url' => $url.'/books/sq_Jeta_e_Profetit_Muhamed.pdf', 'publisher' => 'Islam House' );
	$post[22500] = array( 'title' => 'Karta e të drejtave të gruas dhe detyrat e saj në Islam', 'excerpt' => 'Karta e të drejtave të gruas dhe detyrat e saj në Islam  Ky dokument është përgatitur për të sqaruar qëndrimin e sheriatit (legjislacionit) islam rreth çështjes më të përfolur në mesin e muslimanëve; çështjes së gruas, prej së cilës është sprovuar qytetërimi perëndimor, vesa e së cilës ka prekur disa shoqëri islame dhe logjikën e disa prej bijve të saj.   Ky dokument përmban sqarimin e çështjes më të rëndësishme rreth gruas, si dhe çështje të tjera që kanë të bëjnë me të në aspektin e themelimit dhe mbrojtjes, gjë të cilën e kërkon natyra e kësaj etape.  Ky sqarim është përpjekja e dhjetëra dijetarëve dhe mendimtarëve, në mënyrë që të arrinte në formën e dokumentit dhe përmbledhjes.  ...  “Jemi përpjekur në këtë dokument përmbledhës që të komentojmë e argumentojmë në mënyrë të shkurtër rreth këtyre pikave:  - Pikënisjet bazë.  - Bazat e sheriatit rreth të drejtave të gruas dhe detyrave të saj.  - Largpamësi komentuese dhe arsyetuese të disa prej këtyre bazave.  - Këshilla dhe kërkesa.”', 'url' => $url.'/albanian/karta-e-te-drejtave-te-gruas-dhe-detyrat-e-saj-ne-islam/', 'image' => '', 'author_id' => '6432', 'author_name' => 'Ibrahim b. Nasir En Nasir', 'book_url' => $url.'/books/sq_Karta_e_te_drejtave_te_gruas.pdf', 'publisher' => 'Islam House ' );
	$post[22502] = array( 'title' => 'Ndihmëtar për kuptimin e xhuzit të tridhjetë', 'excerpt' => 'Ndihmëtar për kuptimin e xhuzit të tridhjetë Ndihmëtar në kuptimin e xhuzit të tridhjetë: Ky libër veçohet për', 'url' => $url.'/albanian/ndihmetar-per-kuptimin-e-xhuzit-te-tridhjete/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Kuptimi_i_xhuzit_30-te-1.jpg', 'author_id' => '634', 'author_name' => 'Zeinul Abdeen Al-Rikabi', 'book_url' => $url.'/books/sq_Kuptimi_i_xhuzit_30-te.pdf', 'publisher' => 'Islam House' );
	$post[22505] = array( 'title' => 'الحجاب بين الكتاب المقدس والقرآن', 'excerpt' => 'لما كانت شهوة النساء شهوة لا يستطيع الرجال مقاومتها بسهولة، وضع الله تعالى ضوابط صارمة في رسالاته السماوية المتتابعة لضمان أداء هذه الشهوة لدورها المشروع في حياة الإنسان والتأكد من عدم إخراجها عن مسارها وسياقها المباحين التي وضعت فيهما نظرا لما في استباحة هذه الشهوة خارج إطارها المشروع من مفاسد جسيمة وأضرار عظيمة تهدد سعادة الإنسان في الدارين وتدمر حياته وتضيع آخرته.    وكان من هذه الضوابط الصارمة فرض الحجاب على المرأة بمعنى أمرها بإخفاء مفاتنها التي لا يستطيع الرجل مقاومتها مع السماح بإظهار أجزاء الجسم الظاهرة التي لا تتسبب في فتنة شديدة وإباحة الزينة الإنسانية المعقولة البعيدة كل البعد عن التبرج الذي فيه تعمد إبراز مفاتن المرأة وإثارة غرائز الرجل.', 'url' => $url.'/arabic/%d8%a7%d9%84%d8%ad%d8%ac%d8%a7%d8%a8-%d8%a8%d9%8a%d9%86-%d8%a7%d9%84%d9%83%d8%aa%d8%a7%d8%a8-%d8%a7%d9%84%d9%85%d9%82%d8%af%d8%b3-%d9%88%d8%a7%d9%84%d9%82%d8%b1%d8%a2%d9%86/', 'image' => $url.'/wp-content/uploads/2015/09/ar_Hijab_between_the_Bible_and_the_Quran.jpg', 'author_id' => '1794', 'author_name' => 'لجنة الدعوة الإلكترونية', 'book_url' => $url.'/books/ar_Hijab_between_the_Bible_and_the_Quran.pdf', 'publisher' => ' لجنة الدعوة الإلكترونية' );
	$post[22506] = array( 'title' => 'Kurani i madhërishëm', 'excerpt' => 'Kurani i madhërishëm  Ky botim i Kuranit të madhërishëm në shqip përmban përkthimin e domethënieve të Kuranit nga Prof. Hasan I. Nahi (Allahu e mëshiroftë). Prof. Hasan Nahi ishte një ndër hoxhallarët më të shquar të kohës së tij dhe ndër të vetmit që shkollimin superior e kishin kryer jashtë vendit. Sipas disa kritikëve përkthimi i tij konsiderohet si një ndër përkthimet më autentike të Kuranit në shqip.', 'url' => $url.'/albanian/kurani-i-madherishem/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Kurani_i_madherishem-1.jpg', 'book_url' => $url.'/books/sq_Kurani_i_madherishem.pdf', 'publisher' => 'Islam House' );
	$post[22518] = array( 'title' => 'KUR&#039;AN-i', 'excerpt' => 'Kur&#039;an-i: Është përkthim i domethënieve të Kuranit Fisnik në shqip nga një grup përkthyesish pranë shtëpisë botuese Darus Selam.', 'url' => $url.'/albanian/kuran-i/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Kurani_perkthimi_i_Darus_Selam-1.jpg', 'book_url' => $url.'/books/sq_Kurani_perkthimi_i_Darus_Selam.pdf', 'publisher' => 'Islam House', 'translator' => 'Një Grup përkthyesish' );
	$post[22521] = array( 'title' => 'Ky është profeti Muhamed', 'excerpt' => 'Ky është profeti Muhamed  Ky libër është një jetëpërshkrim i shkurtër i jetës së Muhamedit (Alejhis salatu ues selam). Libri përmban katër kapituj:  1. Ta njohim të Dërguarin e fundit (alejhis salatu ues selam)  2. Profeti që përsosi virtytet njerëzore.  3. Profeti (aljehis salatu ues selam) në optikën e personaliteteve botërore.  4. Disa mësime që i nxjerrim nga jeta e Profetit (alejhis salatu ues selam).', 'url' => $url.'/albanian/ky-eshte-profeti-muhamed/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Ky_eshte_profeti_Muhamed-1.jpg', 'book_url' => $url.'/books/sq_Ky_eshte_profeti_Muhamed.pdf', 'publisher' => 'Islam House' );
	$post[22522] = array( 'title' => 'Hijab (Veil) between the Bible and the Qur’an', 'excerpt' => 'Since the desire for women is something which men cannot resist easily, God has imposed strict regulations in His successive divine messages to make sure that such a desire will play its legitimate role in the human life and will not be got out of the lawful context in which it was essentially placed, given the fact that the satisfaction of such a desire outside its legitimate framework has considerable disadvantages and enormous damage threatening man’s happiness as they ruin his life and lose him the Hereafter.    One of such strict regulations is the imposition of hijab on women. That is to say, women are commanded to conceal their attractive parts whose charm cannot be resisted by men and only allowed to expose such outer parts of the body which do not cause much temptation and have such humanly reasonable adornment which is quite far away from such finery which involves deliberate display of woman’s beauty and intentional arousal of men’s desires.    In this sense, hijab was made incumbent in all divine messages, including Judaism, Christianity and Islam. No wonder, the female believers in any of the divine messages used to wear hijab.  ', 'url' => $url.'/english/hijab-3/', 'image' => $url.'/wp-content/uploads/2015/09/enHijab-Veil-between-the-Bible-and-the-Qur’an.jpg', 'author_id' => '164', 'author_name' => 'E-Da`wah Committee (EDC)', 'book_url' => $url.'/books/en_Hijab_(Veil)_between_the_Bible_and_the_Quran.pdf', 'publisher' => 'E-Da`wah Committee' );
	$post[22528] = array( 'title' => 'Dersovi o postu, teraviji i zekatu', 'excerpt' => 'Dersovi o postu, teraviji i zekatu  Nekoliko lekcija koje se ticu mjeseca Ramazana u globalu.', 'url' => $url.'/albanian/dersovi-o-postu-teraviji-i-zekatu/', 'image' => $url.'/wp-content/uploads/2015/09/sq_lessons_on_fasting_taraweeh_zakatat-1.jpg', 'author_id' => '362', 'author_name' => 'MUHAMED SALIH UTHEJMIN', 'book_url' => $url.'/books/sq_lessons_on_fasting_taraweeh_zakatat.pdf', 'publisher' => 'Islam House' );
	$post[22536] = array( 'title' => 'Libri i Teuhidit', 'excerpt' => 'Libri i Teuhidit  Është e ditur se shkenca për akiden islame është shkenca bazë e cila meriton të përkujdesemi për ta mësuar dhe për t’ua mësuar të tjerëve dhe prej saj varet pranimi i veprave dhe saktësia e tyre. Sidomos kur ne jetojmë kur janë shtuar grupet e devijuara si: Rryma e ateizmit, rryma e sufizmit dhe dervishizmit, rryma e idhujtarisë bashkëkohore – adhurimit të varrezave, rryma e risive të cilat janë në kundërshtim me traditën profetike dhe që tërë këto rryma janë të rrezikshme po që se muslimani nuk është i armatosur me dijen e akides së vërtetë e cila mbështetet në Librin e Allahut dhe Synetin e të Dërguarit (sal-lAllahu alejhi ue sel-lem). ky libër është shkruar në lëmin e akides dhe autori është kujdesur të jetë i shkurtër dhe i qartë. Shejhu e ka mbështetur librin e tij në burime të shumta të dijetarëve e sidomos në librat e Shejhul Islam Ibn tejmijes, Ibn Kajjimit, Muhamed b. Abdul Vehabit dhe dijetarë që i përkasin kësaj thirrjeje të begatshme.', 'url' => $url.'/albanian/libri-i-teuhidit/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Libri_i_Tevhidit-1.jpg', 'author_id' => '511', 'author_name' => 'Salih Al-Fawzan', 'book_url' => $url.'/books/sq_Libri_i_Tevhidit.pdf', 'publisher' => 'Islam House' );
	$post[22540] = array( 'title' => 'باطل کننده‌های معاصر روزه', 'excerpt' => 'به معرفی 20 مورد از مبطلات حدید روزه اختصاص دارد که در کتب فقهی قدیمی بدانها اشاره‌ای نشده است. نویسنده با اشاره به اختراع دستگاه‌ها، داروها و پدیده‌های نوظهور در زندگی بشر', 'url' => $url.'/persian/%d8%a8%d8%a7%d8%b7%d9%84-%da%a9%d9%86%d9%86%d8%af%d9%87%e2%80%8c%d9%87%d8%a7%db%8c-%d9%85%d8%b9%d8%a7%d8%b5%d8%b1-%d8%b1%d9%88%d8%b2%d9%87/', 'image' => $url.'/wp-content/uploads/2015/09/fa_breakfast_contemporary-1.jpg', 'author_id' => '6434', 'author_name' => 'خالد بن علي المشيقح', 'book_url' => $url.'/books/fa_breakfast_contemporary', 'translator' => 'اسحاق بن عبدالله دبيرى العوضى' );
	$post[22543] = array( 'title' => 'مختصر روش نماز پيامبر صلى الله عليه وسلم', 'excerpt' => 'مختصر روش نماز پيامبر صلى الله عليه وسلم', 'url' => $url.'/persian/%d9%85%d8%ae%d8%aa%d8%b5%d8%b1-%d8%b1%d9%88%d8%b4-%d9%86%d9%85%d8%a7%d8%b2-%d9%be%d9%8a%d8%a7%d9%85%d8%a8%d8%b1-%d8%b5%d9%84%d9%89-%d8%a7%d9%84%d9%84%d9%87-%d8%b9%d9%84%d9%8a%d9%87-%d9%88%d8%b3%d9%84/', 'image' => $url.'/wp-content/uploads/2015/09/fa_brief_description_of_prayer_albaanee-1.jpg', 'author_id' => '2060', 'author_name' => 'محمد ناصر الدين الالباني', 'book_url' => $url.'/books/fa_brief_description_of_prayer_albaanee.pdf', 'translator' => ' حسين تاجى گله دارى' );
	$post[22546] = array( 'title' => 'Mbi rrugën e të parëve tanë (Selefit)', 'excerpt' => 'Mbi rrugën e të parëve tanë (Selefit)  Libërth i shkruar nga dijetari shqiptar Abdul Kadër Arnauti (Allahu e mëshiroftë) ku sqaron me fjalë të shkurtra por, të qarta akiden - besimin e gjeneratave të arta islame (Selefit) dhe metodologjinë e tyre në kuptimin e fesë. Libri përveç argumenteve nga Kurani dhe Syneti përmban edhe një mori nga fjalët më të arta të dijetarëve të Selefit.', 'url' => $url.'/albanian/mbi-rrugen-e-te-pareve-tane-selefit/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Mbi_rrugen_e_te_pareve_tane-1.jpg', 'book_url' => $url.'/books/sq_Mbi_rrugen_e_te_pareve_tane.pdf', 'publisher' => 'Islam House' );
	$post[22549] = array( 'title' => 'شناخت كوتاهى از اسلام', 'excerpt' => 'شناخت كوتاهى از اسلام مهم‌ترین عقاید و ارکان عقیدتی و عبادی اسلام را به زبان ساده و به صورت کوتاه بیان می‌کند. کتاب با شرح رسالت اسلام و نقش آن در بسط نگرشِ فرهنگی انسان آغاز شده و در ادامه', 'url' => $url.'/persian/%d8%b4%d9%86%d8%a7%d8%ae%d8%aa-%d9%83%d9%88%d8%aa%d8%a7%d9%87%d9%89-%d8%a7%d8%b2-%d8%a7%d8%b3%d9%84%d8%a7%d9%85/', 'image' => $url.'/wp-content/uploads/2015/09/fa_Brief_Presentation_of_Islam-1.jpg', 'author_id' => '6436', 'author_name' => ': عمادة البحث العلمي بالجامعة الإسلامية', 'book_url' => $url.'/books/fa_Brief_Presentation_of_Islam.pdf', 'publisher' => 'www.iu.edu.sa', 'translator' => 'عبد الله حيدري' );
	$post[22553] = array( 'title' => 'نامه اى برادرانه', 'excerpt' => 'نامه اى برادرانه مجموعه آداب، نصایح و فضایل عبادات اسلامی برگرفته از قرآن کریم و سنت حسنه نبی گران‌قدر اسلام- صلی الله علیه وسلم- است. نویسنده در این ....', 'url' => $url.'/persian/%d9%86%d8%a7%d9%85%d9%87-%d8%a7%d9%89-%d8%a8%d8%b1%d8%a7%d8%af%d8%b1%d8%a7%d9%86%d9%87-2/', 'image' => $url.'/wp-content/uploads/2015/09/fa_Brotherly_Message-1.jpg', 'author_id' => '1149', 'author_name' => 'خالد المهيدب', 'book_url' => $url.'/books/fa_Brotherly_Message.pdf', 'publisher' => 'دار القاسم', 'translator' => ' اسحاق بن عبدالله دبيرى العوضى' );
	$post[22556] = array( 'title' => 'Mburoja e muslimanit - Lutje nga Kurani dhe Suneti', 'excerpt' => 'Mburoja e muslimanit - Lutje nga Kurani dhe Suneti  Mburoja e muslimanit është një libër i begatë që përmbledh lutjet dhe dhikrin (përmendjen e Allahut) për të cilin ka nevojë muslimani gjatë ditës dhe natës si dhe në raste të ndryshme me të cilat përballet gjatë jetës së tij. Ky libër është përkthyer në shumë gjuhë të botës dhe atë në miliona e miliona ekzemplarë, vetëm në islamhouse ekziston në më tepër se 30 gjuhë.      ', 'url' => $url.'/albanian/mburoja-e-muslimanit-lutje-nga-kurani-dhe-suneti/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Mburoja_e_Muslimanit-1.jpg', 'book_url' => $url.'/books/sq_Mburoja_e_Muslimanit.pdf', 'publisher' => 'Islam House' );
	$post[22559] = array( 'title' => 'Bëhu Musliman Produktiv', 'excerpt' => 'Bëhu Musliman Produktiv  Ky libër është përmbledhje e 2 viteve të mendimeve produktive, ideve dhe këshillave. I përpiluar nga një mori artikujsh të zgjedhur dhe me një dizajn shumë tërheqës, ka përmbledhur rregulla dhe udhëzime të ndryshme të cilat ia mundësojnë muslimanit të jetë produktiv dhe dobiprurës në jetën e tij.', 'url' => $url.'/albanian/behu-musliman-produktiv/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Muslimani_Produktiv-1.jpg', 'book_url' => $url.'/books/sq_Muslimani_Produktiv.pdf', 'publisher' => 'Islam House' );
	$post[22562] = array( 'title' => 'Nektari i vulosur i Xhenetit', 'excerpt' => 'Nektari i vulosur i Xhenetit  Nevoja e umetit për njohjen e sires (jetëpërshkrimit) të Pejgamberit (paqja dhe mëshira e Allahut qofshin mbi të) si dhe përfitimi nga burimi i virtyteve të tij, është shumë e madhe dhe e domosdoshme.   Sireja është dhe do të mbetet fondi historik, burimi kulturor dhe metodologjia shkencore e praktike nga e cila do të përfitojnë brezat njëri pas tjetrit. Çdokush që shpreson shpërblimin e Allahut dhe takimin me Të në botën tjetër e konsideron të Dërguarin e Tij (paqja dhe mëshira e Allahut qofshin mbi të) shëmbëlltyrë të tij. Allahu i lartësuar thotë: “Ju e kishit shembullin më të lartë në të dërguarin e Allahut, kuptohet, ai që shpreson në shpërblimin e Allahut në botën tjetër, ai që atë shpresë e shoqëron duke e përmendur shumë shpesh Allahun.” [El Ahzab: 21]  Për shkak të rëndësisë së njohjes së Sires e kemi shtuar edhe këtë libër i cili veçohet me metodologjinë e tij të lehtë dhe të thjeshtë. Libri ka fituar çmimin e parë në garën për librin më të mirë të shkruar rreth Sires. Garë të cilën në vitin 1396 h. e ka organizuar Liga e Botës Islame.', 'url' => $url.'/albanian/nektari-i-vulosur-i-xhenetit/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Nektari_i_vulosur_i_Xhennetit-1.jpg', 'author_id' => '498', 'author_name' => 'Safie Arrahmane Almoebaarakfoerie', 'book_url' => $url.'/books/sq_Nektari_i_vulosur_i_Xhennetit.pdf', 'publisher' => 'Islam House' );
	$post[22565] = array( 'title' => 'Një mesazh i vetëm!', 'excerpt' => 'Një mesazh i vetëm!  Ky libër flet për mesazhin e vetëm me të cilin janë ngarkuar tërë pejgamberët dhe të dërguarit që nga koha e Ademit e deri te pejgamberi ynë, Muhamedi (sal-lAllahu alejhi ue sel-lem). Si dhe dallohet për shkak të vërtetimit të njëshmërisë së Allahut – monoteizmit përmes librave të krishterëve dhe jehudëve (Dhjata e vjetër dhe e re), të cilat i posedojnë tash para vetes.', 'url' => $url.'/albanian/nje-mesazh-i-vetem/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Nje_mesazh_i_vetem-1.jpg', 'book_url' => $url.'/books/sq_Nje_mesazh_i_vetem.pdf', 'publisher' => 'Islam House' );
	$post[22569] = array( 'title' => 'Njohje e përgjithshme me Islamin', 'excerpt' => 'Njohje e përgjithshme me Islamin  Libërth i cili përmban një pasqyrë të shkurtë rreth gradave të fesë Islame: Islamit (nënshtrimit përmes veprave të dukshme) dhe kushteve të tij, Imanit (besimit) dhe kushteve të tij si dhe Ihsanit (bamirësë).', 'url' => $url.'/albanian/njohje-e-pergjithshme-me-islamin-2/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Njohje_e_pergjithshme_me_Islamin-1.jpg', 'book_url' => $url.'/books/sq_Njohje_e_pergjithshme_me_Islamin.pdf', 'publisher' => 'Islam House' );
	$post[22572] = array( 'title' => 'Pengesat në rrugë', 'excerpt' => 'Pengesat në rrugë  Rruga për në Ahiret është e gjatë dhe në të hasim pengesa të shumta. Autori në këtë libër flet rreth këtyre pengesave dhe paraqet metodën e largimit të tyre nën dritën e Kuranit dhe Synetit si dhe vë theksin se besimtari duhet të qëndrojë i paluhatur derisa të arrijë në fund të kësaj rruge.', 'url' => $url.'/albanian/pengesat-ne-rruge/', 'image' => $url.'/wp-content/uploads/2015/09/sq_obstacles_in_the_way-1.jpg', 'author_id' => '55', 'author_name' => 'Abdul-Malik al-Qasim', 'book_url' => $url.'/books/sq_obstacles_in_the_way.pdf', 'publisher' => 'Islam House' );
	$post[22576] = array( 'title' => 'Përgjigje jomuslimanëve në pyetjet më të shpeshta rreth Islamit', 'excerpt' => 'Përgjigje jomuslimanëve në pyetjet më të shpeshta rreth Islamit  ', 'url' => $url.'/albanian/pergjigje-jomuslimaneve-ne-pyetjet-me-te-shpeshta-rreth-islamit/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Pergjigjet_jomuslimaneve_ne_pyetjet_me_te_shpeshta_rreth_Islamit-1.jpg', 'author_id' => '631', 'author_name' => 'Zakir Naik', 'book_url' => $url.'/books/sq_Pergjigjet_jomuslimaneve_ne_pyetjet_me_te_shpeshta_rreth_Islamit.pdf', 'publisher' => 'Islam House' );
	$post[22579] = array( 'title' => 'Përmbledhje tregimesh', 'excerpt' => 'Përmbledhje tregimesh  Përmbledhje tregimesh: Është libër i cili ka përmbledhur një sërë tregimesh islame për fëmijë, të cilat janë të shkruara me një metodologji të përshtatshme për fëmijët. Tregimet janë edukative dhe janë marrë nga Libri i Allahut - Kurani, Tradita profetike – Suneti dhe historia islame.', 'url' => $url.'/albanian/permbledhje-tregimesh/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Permbledhje_tregimesh-1.jpg', 'book_url' => $url.'/books/sq_Permbledhje_tregimesh.pdf', 'publisher' => 'Islam House' );
	$post[22582] = array( 'title' => 'آرمان جوان مسلمان', 'excerpt' => 'آرمان جوان مسلمان    وای به حال ملّتی که جوانان آن در جنگ ارزش‌ها شکست خورده و به دنبال پوچ و هیچ، سرمایه‌های ارزشمند زندگانی را به هدر دهند بياييد با آرمانهاي اصيل اسلامي آشنا شويد', 'url' => $url.'/persian/%d8%a2%d8%b1%d9%85%d8%a7%d9%86-%d8%ac%d9%88%d8%a7%d9%86-%d9%85%d8%b3%d9%84%d9%85%d8%a7%d9%86/', 'image' => $url.'/wp-content/uploads/2015/09/fa_arman_javan_mosalman-1.jpg', 'author_id' => '1665', 'author_name' => 'علي الطنطاوي', 'book_url' => $url.'/books/fa_arman_javan_mosalman.pdf', 'publisher' => 'www.aqeedeh.com' );
	$post[22585] = array( 'title' => '40 Hadith nói về ân phúc của câu tuyên thệ « لا إله إِلا الله»', 'excerpt' => '40 Hadith nói về ân phúc của câu tuyên thệ « لا إله إِلا الله»', 'url' => $url.'/vietnamese/40-hadith-noi-ve-an/', 'image' => $url.'/wp-content/uploads/2015/09/vi_40_hadeeth_in_fadl_la_elah_ela_allah-1.jpg', 'author_id' => '1932', 'author_name' => 'محمد بن مرزوق الدعجاني', 'book_url' => $url.'/books/vi_40_hadeeth_in_fadl_la_elah_ela_allah.pdf', 'publisher' => 'Văn phòng Al-Rabwah', 'translator' => ' Abu Zaytune Usman bin Ibrahim' );
	$post[22588] = array( 'title' => '48 Câu Hỏi Về Sự Nhịn Chay', 'excerpt' => '48 Câu Hỏi Về Sự Nhịn Chay Quyển sách nhỏ này gồm 48 câu trả lời về vấn đề nhịn chay và đây là những câu hỏi được nhiều người hỏi đến.', 'url' => $url.'/vietnamese/48-cau-hoi/', 'image' => $url.'/wp-content/uploads/2015/09/vi_48_questions_in_the_fast-1.jpg', 'author_id' => '1901', 'author_name' => 'محمد بن صالح العثيمين', 'book_url' => $url.'/books/vi_48_questions_in_the_fast.pdf', 'publisher' => 'Văn phòng Al-Rabwah', 'translator' => 'Abu Hisaan Ibnu Ysa' );
	$post[22591] = array( 'title' => '50 Đóa Hoa Trong Vườn Khuyên', 'excerpt' => ' 50 Đóa Hoa Trong Vườn Khuyên: Tác giả nói: “Trong những trang giấy nhỏ lẻ này hàm chưa biết bao là lời khuyên vàng, nếu chị em phụ nữ Muslim chịu làm theo, chắc chắn sẽ hưởng được cuộc sống tràn ngập hạnh phúc, sẽ đưa chị em từ khó chịu đến ngạt thở trở thành thoải mái thanh thản. Mong rằng quyển sách nhỏ này mang đến cho chị em nhiều bổ ích và phúc lộc từ Allah”.', 'url' => $url.'/vietnamese/50-doa-hoa-trong-vuon-khuyen/', 'image' => $url.'/wp-content/uploads/2015/09/vi_50_flower_of_the_field_advice-1.jpg', 'author_id' => '6437', 'author_name' => ' عبد العزيز بن عبد الله المقبل', 'book_url' => $url.'/books/vi_50_flower_of_the_field_advice.pdf', 'publisher' => 'Văn phòng Al-Rabwah', 'translator' => 'Abu Hisaan Ibnu Ysa' );
	$post[22594] = array( 'title' => 'Plani dhjetëditor', 'excerpt' => 'Plani dhjetëditor është një libërth i edukatorit dhe dijetarit Muhamed Husejn Jakub, ku flet për vlerën e dhjetë ditëve të Dhul Hixhes dhe prezanton një program për shfrytëzimin sa më të mirë të tyre. Ky plan përmban dhjetë projekte, e ato janë: Projekti i Kuranit Fisnik, banketi për çdo namaz, projekti i dhikrit, agjërimit, haxhit dhe umres, projekti “Kanatirul Firdevs”, projekti i vëllazërisë për hir të Allahut, i lidhjes familjare, ditës së Arafatit, ditës së Bajramit dhe e përfundon librin e tij me shanse të arta që duhet çdo musliman të përfitoj prej tyre.', 'url' => $url.'/albanian/plani-dhjeteditor/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Plani_dhjete_ditor-1.jpg', 'book_url' => $url.'/books/sq_Plani_dhjete_ditor.pdf', 'publisher' => 'Islam House' );
	$post[22597] = array( 'title' => 'Porosi Profetike', 'excerpt' => 'Porosi Profetike  Libër të cilin e shkroi Shejhu i nderuar Abdul Kadër El Arnauti (Allahu e mëshiroftë) në të cilin përmblodhi pesë hadithe të cilat përmbajnë në vete porosi dhe këshilla gjithëpërfshirëse duke iu dhënë një koment të shkurtër por, tërheqës dhe të thuktë.', 'url' => $url.'/albanian/porosi-profetike/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Porosi_profetike-1.jpg', 'author_id' => '6435', 'author_name' => 'Abdul Kadër Arnauti', 'book_url' => $url.'/books/sq_Porosi_profetike.pdf', 'publisher' => 'Islam House' );
	$post[22600] = array( 'title' => 'Priftërinjtë pyesin dhe Hoxhallarët përgjigjen', 'excerpt' => 'Priftërinjtë pyesin dhe Hoxhallarët përgjigjen  Përse ky libër? Nuk do të jenë të paktë ata që ndoshta do ta bëjnë një pyetje të tillë pasi të njihen me tematikën që ai trajton. Në një kohë kur Islami dhe ithtarët e tij janë vënë në bankën e të akuzuarve për një mori akuzash, ku më të spikaturat dallojnë ato të terrorizmit, obskurantizmit, mungesës së tolerancës, prapambetjes, egërsisë, brutalitetit…etj, del në skenë një libër i tillë për ta mbrojtur atë!  Pikërisht ky libër u shkrua për t’u dhënë sadopak përgjigje këtij llumi të shpifur akuzash.  Ky libër i shkurtër dhe përmbledhës jep një ide të përgjithshme të botëkuptimeve islame dhe më pas iu përgjigjet një seri pyetjesh në mënyrë të shkurtër dhe të përmbledhur.”  Ky libër u shkrua si përgjigje ndaj një mori pyetjesh që iu drejtuan Sekretariatit të Këshillit kontinental për Xhamitë në Evropë nga një organizatë evangjeliste, e të cilat kanë të bëjnë me liritë individuale dhe me barazinë mes njerëzve.', 'url' => $url.'/albanian/prifterinjte-pyesin-dhe-hoxhallaret-pergjigjen/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Prifterinjte_pyesin_dhe_hoxhallaret_pergjigjen-1.jpg', 'author_id' => '6438', 'author_name' => 'Abdurr-Rrahman Hasen', 'book_url' => $url.'/books/sq_Prifterinjte_pyesin_dhe_hoxhallaret_pergjigjen.pdf', 'publisher' => 'Islam House' );
	$post[22603] = array( 'title' => 'Porosi Kuranore', 'excerpt' => 'Porosi Kuranore  Ky libër është tërheqës dhe i veçantë në përpilimin e tij. Libri është i ndarë në tematika të ndryshme të cilat argumentohen me ajete të ndryshme Kuranore që kanë të bëjnë me këto tematika. Ky libër është i dobishëm edhe për të gjithë ata që përgatitin ndonjë ligjëratë dhe iu intereson ndarja tematikore e ajeteve.  M.M. Pikthal &amp; M. Fateh Muhammad', 'url' => $url.'/albanian/porosi-kuranore/', 'image' => $url.'/wp-content/uploads/2015/09/sq_quranic_commandments-1.jpg', 'book_url' => $url.'/books/sq_quranic_commandments.pdf', 'publisher' => 'Islam House' );
	$post[22606] = array( 'title' => 'Rigjallërimi Islam - Rregulla dhe Udhëzime', 'excerpt' => 'Rigjallërimi Islam - Rregulla dhe Udhëzime  Rigjallërimi Islam që ka përshkuar tërë botën tash e sa kohë ka nevojë për disa faktorë që të shndërrohet në një lëvizje të dobishme dhe ripërtëritëse. Ky libër në pjesën e tij të parë ofron trembëdhjetë rregulla që orientojnë këtë rigjallërim. Ndërsa në pjesën e tij të dytë, në formë të pyetjeve dhe përgjigjeve, jep udhëzime rreth shumë çështjeve që kanë të bëjnë me thirrjen në rrugë të Allahut, grupimet dhe fraksionet dhe qëndrimin kundrejt tyre dhe sjelljen në raport me ta si dhe për jomuslimanët dhe thirrjen e tyre në Islam. Libri përfundon me një shtojcë për mesataren e cila duhet të ndiqet në Dave – Thirrjen islame.', 'url' => $url.'/albanian/rigjallerimi-islam-rregulla-dhe-udhezime/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Rigjallerimi_Islam-1.jpg', 'author_id' => '362', 'author_name' => 'MUHAMED SALIH UTHEJMIN', 'book_url' => $url.'/books/sq_Rigjallerimi_Islam.pdf', 'publisher' => 'Islam House' );
	$post[22609] = array( 'title' => 'Rijadus Salihin', 'excerpt' => 'Rijadus Salihin  Një ndër enciklopeditë më të njohura të Hadithit. Ky libër do të jetë udhërrëfyes për secilin që ndi¬hmohet me të dhe shërbehet në kërkimin dhe veprimin e veprave të mira, si dhe do të jetë ndalesë prej të këqijave dhe katas¬trofave të ndryshme. Me pak fjalë ky libër është një ndër librat pa të cilat nuk duhet të mbetet shtëpia e myslimanit.', 'url' => $url.'/albanian/rijadus-salihin/', 'image' => $url.'/wp-content/uploads/2015/09/sq_riyad_alsaliheen-1.jpg', 'author_id' => '236', 'author_name' => 'Imam An-Nawawi', 'book_url' => $url.'/books/sq_riyad_alsaliheen.pdf', 'publisher' => 'Islam House' );
	$post[22613] = array( 'title' => 'Rregullat fetare që duhet të ndjekë një Musliman në rast Fitnesh', 'excerpt' => 'Rregullat fetare që duhet të ndjekë një Musliman në rast Fitnesh  Në këtë libër përmenden parime dhe rregulla islame shumë të rëndësishme që u vlejnë të gjithë muslimanëve, në çdo kohë dhe vend, e veçanërisht kur ata kalojnë sprova të rënda që rrezikojnë unitetin dhe bashkësinë e tyre fetare.   Dijetari në parathënien e librit të tij flet për rrezikun e fitneve, dobitë e ndjekjes së këtyre rregullave dhe argumentet në të cilat i ka mbështetur këto rregulla dhe më pas ka përmendur nëntë rregulla.   Që të gjitha na japin një panoramë të shkurtër dhe të përmbledhur se si muslimani gjatë gjithë jetës së tij duhet të ketë vetëkontroll në pajtim me rregullat e fesë, si duhet të vlerësojë njerëzit dhe situatat, për t’iu ruajtur sa më shumë gabimeve dhe për të fituar kënaqësinë e Allahut.', 'url' => $url.'/albanian/rregullat-fetare-qe-duhet-te-ndjeke-nje-musliman-ne-rast-fitnesh/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Rregullat_fetare_ne_rast_fitnesh-1.jpg', 'book_url' => $url.'/books/sq_Rregullat_fetare_ne_rast_fitnesh.pdf', 'publisher' => 'Islam House' );
	$post[22616] = array( 'title' => 'Rruga e muslimanit', 'excerpt' => 'Rruga e muslimanit  Rruga e muslimanit është një doracak që përmbledh njohuritë elementare rreth Islamit.  Pjesa e parë e tij flet rreth disa parimeve të përgjithshme të fesë Islame si: Shtyllat e Islamit, Imanit dhe Ihsanit, pastaj disa sqarime rreth Shehadetit.  Pjesa e dytë: përmban disa nga suret e shkurtra të Kuranit me përkthim në gjuhën shqipe.  Pjesa e tretë: flet rreth rregullave elementare të Fikhut gjegjësisht pastërtisë dhe namazit duke ilustruar me foto mënyrën e marrjes së abdesit dhe faljes së namazit.  Pjesa e katërt: veçohet me komentimin e disa haditheve dhe përfundon me një mori lutjesh të shoqëruara me përkthimin në shqip.', 'url' => $url.'/albanian/rruga-e-muslimanit/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Rruga_e_muslimanit-1.jpg', 'book_url' => $url.'/books/sq_Rruga_e_muslimanit.pdf', 'publisher' => 'Islam House' );
	$post[22620] = array( 'title' => 'Shefati, ndërmjetësimi në Ditën e Gjykimit', 'excerpt' => 'Shefati, ndërmjetësimi në Ditën e Gjykimit  Ky libër shtjellon një ndër tematikat më të rëndësishme të akides e që është: “Shefati - Ndërmjetësimi në Ditën e Gjykimit” dhe në shtjellimin e së cilës kanë devijuar grupe të shumta. Autori sjell besimin e Ehlu Sunetit rreth Shefatit, i cili është besimi mesatar dhe i vërtetë në këtë çështje. Shejhu i nderuar e trajton këtë temë përmes disa kapitujve, si: Kuptimi i shefatit dhe argumentet që e vërtetojnë atë dhe dallimi mes shefatit në këtë botë dhe në tjetrën, llojet e shefatit të Pejgamberit (alejhis salatu ues selam) dhe kush bën shefat përveç tij, kushtet e shefatit dhe shkaqet e përfitimit të tij dhe në fund flet rreth shefatit sipas kundërshtarëve të Ehlu Sunetit dhe përgjigja ndaj tyre.', 'url' => $url.'/albanian/shefati-ndermjetesimi-ne-diten-e-gjykimit/', 'image' => $url.'/wp-content/uploads/2015/09/sq_Shefati_ne_Diten_e_Gjykimit-1.jpg', 'book_url' => $url.'/books/sq_Shefati_ne_Diten_e_Gjykimit.pdf', 'publisher' => 'Islam House' );
	$post[22624] = array( 'title' => 'أبو بكر الصديق رضي الله عنه والرسالة الإلكترونية', 'excerpt' => 'أبو بكر الصديق رضي الله عنه والرسالة الإلكترونية يتطرق الإصدار الثالث من سلسلة (الناشئة في رحاب الآل والأصحاب) الخاصة بأحبائنا الصغار', 'url' => $url.'/arabic/%d8%a3%d8%a8%d9%88-%d8%a8%d9%83%d8%b1-%d8%a7%d9%84%d8%b5%d8%af%d9%8a%d9%82-%d8%b1%d8%b6%d9%8a-%d8%a7%d9%84%d9%84%d9%87-%d8%b9%d9%86%d9%87-%d9%88%d8%a7%d9%84%d8%b1%d8%b3%d8%a7%d9%84%d8%a9-%d8%a7%d9%84/', 'image' => $url.'/wp-content/uploads/2015/09/Arabic-abu-bakr-alsidiq-wa-alrisalah-al-eliktroniyah.jpg', 'author_id' => '6439', 'author_name' => 'طارق البكري', 'book_url' => $url.'/dl/books/Arabic-abu-bakr-alsidiq-wa-alrisalah-al-eliktroniyah.pdf', 'publisher' => 'مبرة الآل والأصحاب' );
