	$post[24261] = array( 'title' => 'Help for New Muslims on Christmas', 'excerpt' => 'One of the problems faced by new Muslims is the issue of different celebrations held throughout the year. Christmas is one typical example.', 'url' => $url.'/english/help-for-new-muslims-on-christmas/', 'image' => $url.'/wp-content/uploads/2015/12/en_Help_for_New_Muslims_on_Christmas-1.jpg', 'author_id' => '164', 'author_name' => 'E-Da`wah Committee (EDC)', 'book_url' => $url.'/books/en_Help_for_New_Muslims_on_Christmas.pdf', 'publisher' => 'E-Da`wah Committee' );
	$post[24419] = array( 'title' => 'معايير الجودة في المواقع الدعوية: دراسة تحليلية تقويمية على عينة من المواقع الدعوية', 'excerpt' => 'معايير الجودة في المواقع الدعوية هي دراسة متخصصة أجرتها الباحثة نورة بنت عبد الرحمن بن علي الزامل لنيل الدرجة العلمية (الماجستير) من قسم الدعوة والدراسات الإسلامية المعاصرة بمعهد الدعوة والاحتساب بجامعة الإمام محمد بن سعود الإسلامية بالمملكة العربية السعودية للعام الهجري ألف أربعمائة وخمسة وثلاثون.', 'url' => $url.'/arabic/%d9%85%d8%b9%d8%a7%d9%8a%d9%8a%d8%b1-%d8%a7%d9%84%d8%ac%d9%88%d8%af%d8%a9-%d9%81%d9%8a-%d8%a7%d9%84%d9%85%d9%88%d8%a7%d9%82%d8%b9-%d8%a7%d9%84%d8%af%d8%b9%d9%88%d9%8a%d8%a9/', 'image' => $url.'/wp-content/uploads/2016/01/aljawda.jpg', 'author_id' => '6490', 'author_name' => 'نو رة بنت عبدالرحمن بن علي الزامل', 'book_url' => $url.'/books/ar_web_sites.pdf', 'publisher' => 'جامعة الإمام محمد بن سعود الإسلامية المعهد العالي للدعوة والاحتساب' );
	$post[24425] = array( 'title' => 'الدعوة إلى الله عبر الانترنت: أساليبها ووسائلها', 'excerpt' => 'إن موضوع - أساليب الدعوة إلى الله عبر الانترنت ووسائلها- من أهم ما ينبغي أن يعتني به الدعاة إلى الله في هذا الزمان الذي وصل فيه الإنترنت إلى كل بيت، بل إلى كل فرد عبر هاتفه الخاص، وأصبح من الضرورة بمكان دراسة هذه الوسائل الحديثة في الدعوة إلى الله لاستثمارها على أكمل وجه، وتسجيل السبق في استخدامها لخدمة الدعوة إلى الله مع أو قبل غيرنا من أُمم العالم، والديانات الأخرى، وفق منهج وضوابط إسلامية واضحة المعالم في ضوء مقاصد الشريعة الإسلامية السمحة، وذات أثر مباشر على مستخدمي الشبكة الدولية للمعلومات.', 'url' => $url.'/arabic/%d8%a7%d9%84%d8%af%d8%b9%d9%88%d8%a9-%d8%a5%d9%84%d9%89-%d8%a7%d9%84%d9%84%d9%87-%d8%b9%d8%a8%d8%b1-%d8%a7%d9%84%d8%a7%d9%86%d8%aa%d8%b1%d9%86%d8%aa-%d8%a3%d8%b3%d8%a7%d9%84%d9%8a%d8%a8%d9%87%d8%a7/', 'image' => $url.'/wp-content/uploads/2016/01/ar_Call_to_God_through-1.jpg', 'author_id' => '6491', 'author_name' => 'د. عبدالرحمن بن معاضة الشهري', 'book_url' => $url.'/books/ar_Call_to_God_through.pdf', 'publisher' => 'جامعة الإمام محمد بن سعود الإسلامية' );
	$post[24433] = array( 'title' => 'استقراء للمواقع الدعوية ومعايير تقويمها', 'excerpt' => 'ستقراء للمواقع الدعوية ومعايير تقويمها هي ورقة عمل مقدمة من الأستاذ الدكتور – عبد العزيز بن داخل المطيري- المشرف العام على مشروع آفاق التيسير لتعليم العلوم الشريعة عن بعد، بندوة المواقع الدعوية الإسلامية الإلكترونية السعودية للعام الهجري ألف وأربعمائة واثنين وثلاثين، والذي خصصه لتقصي واستقراء المواقع الدعوية الإسلامية بالعالم، وتصنيف هذه المواقع حسب الصلة المباشرة بالدعوة إلى الله.', 'url' => $url.'/arabic/%d8%a7%d8%b3%d8%aa%d9%82%d8%b1%d8%a7%d8%a1-%d9%84%d9%84%d9%85%d9%88%d8%a7%d9%82%d8%b9-%d8%a7%d9%84%d8%af%d8%b9%d9%88%d9%8a%d8%a9-%d9%88%d9%85%d8%b9%d8%a7%d9%8a%d9%8a%d8%b1-%d8%aa%d9%82%d9%88%d9%8a/', 'image' => $url.'/wp-content/uploads/2016/02/استقراء-للمواقع-الدعوية-ومعايير-تقويمها-1.png', 'author_id' => '5988', 'author_name' => ' زيد بن محمد الرماني', 'book_url' => $url.'/books/ar_Call_to_God.pdf' );
	$post[24437] = array( 'title' => 'الرؤية الاستراتيجية للمواقع الدعوية الإسلامية السعودية', 'excerpt' => 'لرؤية الاستراتيجية للمواقع الدعوية: هي ورقة عمل بحثية مقدمة من الأستاذة الدكتورة – هند بنت دليجان الدليجان- أستاذ مشارك في التفسير وعلوم القرآن جامعة الملك فيصل بالأحساء ووكيلة أقسام الطالبات بالجامعة، قدمت هذه الورقة البحثية لندوة المواقع الدعوية السعودية الالكترونية الإسلامية التي أقامتها وزارة الأوقاف والشؤون الإسلامية بمدينة الرياض بالمملكة العربية السعودية للعام ألف وأربعمائة واثنان وثلاثون من هجرة المصطفى صلى الله عليه وسلم إلى المدينة المنورة.', 'url' => $url.'/arabic/%d8%a7%d9%84%d8%b1%d8%a4%d9%8a%d8%a9-%d8%a7%d9%84%d8%a7%d8%b3%d8%aa%d8%b1%d8%a7%d8%aa%d9%8a%d8%ac%d9%8a%d8%a9-%d9%84%d9%84%d9%85%d9%88%d8%a7%d9%82%d8%b9-%d8%a7%d9%84%d8%af%d8%b9%d9%88%d9%8a%d8%a9/', 'image' => $url.'/wp-content/uploads/2016/01/الرؤية-الإستراتيجية-للمواقع-الدعوية-السعودية-.png', 'author_id' => '6492', 'author_name' => 'د. هدى بنت دليجان الدليجان', 'book_url' => $url.'/books/ar_Vision.pdf', 'publisher' => 'وزارة الشؤون الإسلامية والدعوة والإرشاد' );
	$post[24442] = array( 'title' => 'التخصص وأثره في تحقيق التكامل بين المواقع الدعوية', 'excerpt' => 'التخصص وأثره في تحقيق التكامل بين المواقع الدعوية هي ورقة بحثية مقدمة من الأستاذ الدكتور - هشام بن عبد الملك بن عبد الله آل الشيخ - أستاذ الفقه المقارن المشارك بالمعهد العالي للقضاء جامعة الإمام محمد بن سعود الإسلامية', 'url' => $url.'/arabic/%d8%a7%d9%84%d8%aa%d9%83%d8%a7%d9%85%d9%84-%d8%a8%d9%8a%d9%86-%d8%a7%d9%84%d9%85%d9%88%d8%a7%d9%82%d8%b9-%d8%a7%d9%84%d8%af%d8%b9%d9%88%d9%8a%d8%a9/', 'image' => $url.'/wp-content/uploads/2016/01/التخصص-وأثره-في-تحقيق-التكامل-بين-المواقع-الدعوية-.png', 'author_id' => '6493', 'author_name' => 'د. هشام بن عبد الملك بن عبد الله آل الشيخ', 'book_url' => $url.'/books/ar_d.hisham.pdf', 'publisher' => 'وزارة الدعوة والإرشاد الديني بالمملكة العربية السعودية' );
	$post[24445] = array( 'title' => 'ضرورة التكامل بين المواقع الدعوية وأثره في خدمة الدعوة إلى الله', 'excerpt' => 'ضرورة التكامل بين المواقع الدعوية هي ورقة عمل مقدمة من الأستاذ الدكتور – عبد الرحمن بن عبد العزيز السديس- إمام وخطيب المسجد الحرام وأستاذ الدراسات العليا الشرعية بجامعة أم القرى بمكة المكرمة بالمملكة العربية السعودية، بندوة المواقع الدعوية الإسلامية الإلكترونية السعودية للعام الهجري ألف وأربعمائة واثنين وثلاثون، والذي خصصه لسبل التعاون والتكامل بين المواقع العاملة في الدعوة إلى الله تعالى حول العالم.  ', 'url' => $url.'/arabic/%d8%b6%d8%b1%d9%88%d8%b1%d8%a9-%d8%a7%d9%84%d8%aa%d9%83%d8%a7%d9%85%d9%84-%d8%a8%d9%8a%d9%86-%d8%a7%d9%84%d9%85%d9%88%d8%a7%d9%82%d8%b9-%d8%a7%d9%84%d8%af%d8%b9%d9%88%d9%8a%d8%a9/', 'image' => $url.'/wp-content/uploads/2016/01/ar_sites-1.jpg', 'author_id' => '6494', 'author_name' => 'عبدالرحمن بن عبدالعزيز السديس', 'book_url' => $url.'/books/ar_sites.pdf' );
	$post[24449] = array( 'title' => 'مجالات الدعوة إلى الله عبر الإنترنت: ورقة بحثية توثيقية', 'excerpt' => 'جالات الدعوة إلى الله عبر الإنترنت: هي ورقة بحثية مقدمة من الدكتور فهد بن إبراهيم بن عبد الله الضالع، المشرف العام على شبكة شواطئ الإسلامية، وهذا الكتاب عبارة عن ورقة عمل مقدمة للندوة الأولى للمواقع الدعوية السعودية المقامة في العام الهجري ألف وأربعمائة واثنين وثلاثين برعاية وزارة الأوقاف والشؤون الإسلامية بالمملكة العربية السعودية.', 'url' => $url.'/arabic/%d9%85%d8%ac%d8%a7%d9%84%d8%a7%d8%aa-%d8%a7%d9%84%d8%af%d8%b9%d9%88%d8%a9-%d8%a5%d9%84%d9%89-%d8%a7%d9%84%d9%84%d9%87-%d8%b9%d8%a8%d8%b1-%d8%a7%d9%84%d8%a5%d9%86%d8%aa%d8%b1%d9%86%d8%aa/', 'image' => $url.'/wp-content/uploads/2016/01/مجالات-الدعوة-إلى-الله-عبر-الإنترنت-ورقة-بحثية-توثيقية.png', 'author_id' => '6495', 'author_name' => 'الدكتور فهد بن إبراهيم بن عبد الله الضالع', 'book_url' => $url.'/books/ar_Call_to_God2.pdf', 'publisher' => 'وزارة الأوقاف والشؤون الإسلامية بالسعودية' );
	$post[24457] = array( 'title' => 'الدعوة إلى الله عبر الإنترنت: أهميتها وخصائصها', 'excerpt' => 'الدعوة إلى الله عبر الانترنت أهميتها وخصائصها: هي ورقة بحثية مقدمة من الدكتور محمد إبراهيم الحمد، وهذا الكتاب عبارة عن ورق عمل مقدمة للندوة الأولى للمواقع الدعوية السعودية المقامة في العام الهجري ألف وأربعمائة واثنين وثلاثين.', 'url' => $url.'/arabic/%d8%a7%d9%84%d8%af%d8%b9%d9%88%d8%a9-%d8%a5%d9%84%d9%89-%d8%a7%d9%84%d9%84%d9%87-%d8%b9%d8%a8%d8%b1-%d8%a7%d9%84%d8%a7%d9%86%d8%aa%d8%b1%d9%86%d8%aa/', 'image' => $url.'/wp-content/uploads/2016/01/الدعوة-إلى-الله-عبر-الإنترنت-2.png', 'author_id' => '6496', 'author_name' => 'الدكتور محمد بن ابراهيم الحمد', 'book_url' => $url.'/books/ar_Call_to_God3.pdf' );
	$post[24460] = array( 'title' => 'وسائل الدعوة إلى الله تعالى في شبكة المعلومات الدولية (الإنترنت)', 'excerpt' => 'وسائل الدعوة إلى الله تعالى في شبكة المعلومات الدولية – الانترنت- هذا الكتاب هو الجزء الأول من الرسالة البحثية العلمية التي حصل بها الباحث – إبراهيم عبد الرحيم عابد- على الدرجة العلمية( الدكتوراه) من قسم الدعوة والدراسات الإسلامية بالمعهد العالي للدعوة الاحتساب بجامعة الإمام محمد بن سعود الإسلامية بالمملكة العربية السعودية.', 'url' => $url.'/arabic/%d9%88%d8%b3%d8%a7%d8%a6%d9%84-%d8%a7%d9%84%d8%af%d8%b9%d9%88%d8%a9-%d8%a5%d9%84%d9%89-%d8%a7%d9%84%d9%84%d9%87/', 'image' => $url.'/wp-content/uploads/2016/01/وسائل-الدعوة-إلى-الله-في-شبكة-المعلومات-الدولية-الإنترنت-وكيفية-استخداماتها-الدعوية-1-2.png', 'book_url' => '' );
	$post[24538] = array( 'title' => 'شك داروين: النشوء المفاجئ لحياة الكائنات وحجة التصميم الذكي', 'excerpt' => 'هذه عينة من كتاب شك داروين: النشوء المفاجئ لحياة الكائنات وحجة التصميم الذكي الذي أصدرته دار الكاتب للنشر والتوزيع في شهر يناير من عام 2016    كان داروين يعلم بعد أن أنهى كتابه الشهير (أصل الأنواع) أن هناك حدث محوري في تاريخ الحياة قد يعصف بنظريته، فالبناء الأساسي لنظرية داروين يعتمد على التطور التدريجي البطيء في ظهور الكائنات، لكن ما حدث في (الانفجار الكامبري) قلب هذا البناء رأسًا على عقب. ', 'url' => $url.'/arabic/%d8%b4%d9%83-%d8%af%d8%a7%d8%b1%d9%88%d9%8a%d9%86-%d8%a7%d9%84%d9%86%d8%b4%d9%88%d8%a1-%d8%a7%d9%84%d9%85%d9%81%d8%a7%d8%ac%d8%a6-%d9%84%d8%ad%d9%8a%d8%a7%d8%a9-%d8%a7%d9%84%d9%83%d8%a7%d8%a6%d9%86/', 'image' => $url.'/wp-content/uploads/2016/01/Arabic-shak-darwin.jpg', 'author_id' => '6498', 'author_name' => 'ستيفن ماير', 'book_url' => $url.'/dl/books/Arabic-shak-darwin.pdf', 'publisher' => 'دار الكاتب للنشر والتوزيع' );
	$post[24544] = array( 'title' => 'الأخلاق: بين الأديان السماوية والفلسفة الغربية', 'excerpt' => 'هذه عينة من كتاب الأخلاق: بين الأديان السماوية والفلسفة الغربية الذي أصدرته دار الكاتب للنشر والتوزيع في شهر يناير من عام 2016    تعتبر الأخلاق أساس البناء الحضاري والتقدم البشري، فهي قطب الرحى والدعامة الأساسية، التي تقوم عليها حياة الفرد والمجتمع، وما سلوك الإنسان القويم إلا تعبير عن تمثله للقيم السامية التي تميزه عن الحيوان، وتخرجه من دائرة البهيمية.    وقد ميز الله تعالى الإنسان وخصه عن سائر المخلوقات بالعقل، الذي يحلق بواسطته في سماء المثالية متحليا بمكارم الأخلاق وفضائل الأعمال، محققا بذلك التوازن النفسي الذي يجعله مستمرا في حياته كإنسان عاقل يدرك أفعاله، ويميز بين ما هو خير وشر لإنسانيته.  ومن البيّن أن الإيمان بسماوية الأخلاق أعمق وأكثر اتساقا معرفيا ونفسيا، فشتان بين دين يقول بأن الاهتمام بالضعفاء والإحسان إليهم سبب للنصر والرزق، وبين من لا يمتلك أدنى حجة لإدانة قتل طفل لمجرد إعاقته.', 'url' => $url.'/arabic/%d8%a7%d9%84%d8%a3%d8%ae%d9%84%d8%a7%d9%82-%d8%a8%d9%8a%d9%86-%d8%a7%d9%84%d8%a3%d8%af%d9%8a%d8%a7%d9%86-%d8%a7%d9%84%d8%b3%d9%85%d8%a7%d9%88%d9%8a%d8%a9-%d9%88%d8%a7%d9%84%d9%81%d9%84%d8%b3%d9%81/', 'image' => $url.'/wp-content/uploads/2016/01/Arabic-Al-akhlaq-bayn-al-adyan-al-samawiyah.jpg', 'author_id' => '6499', 'author_name' => 'كريمة دوز', 'book_url' => $url.'/dl/books/Arabic-Al-akhlaq-bayn-al-adyan-al-samawiyah.pdf', 'publisher' => 'دار الكاتب للنشر والتوزيع' );
	$post[24646] = array( 'title' => 'Biographies of the Imams of Hadith', 'excerpt' => 'The book provides brief biographies of the Imams of Hadith and Sunan, including: Al-Bukhari, Muslim, Abu Dawud, At-Tirmidhi, An-Nasa’i and Ibn Majah.', 'url' => $url.'/english/biographies-of-the-imams-of-hadith/', 'image' => $url.'/wp-content/uploads/2016/02/En_Biographies_of_Hadith_Imams-1.jpg', 'author_id' => '164', 'author_name' => 'E-Da`wah Committee (EDC)', 'book_url' => $url.'/books/En_Biographies_of_Hadith_Imams.pdf', 'publisher' => 'E-Da`wah Committee' );
	$post[24673] = array( 'title' => 'A Journey to God with Ibn Ata’s Words of Wisdom in light of Universal Laws', 'excerpt' => ' The start of the journey  There is no real distance between you and Him in order for you to journey. And the  connection between you and Him is not cut in order for you to seek to mend it. ', 'url' => $url.'/english/a-journey-to-god/', 'image' => $url.'/wp-content/uploads/2016/02/Journey-to-God.jpg', 'author_id' => '6305', 'author_name' => 'Jasser Auda', 'book_url' => $url.'/books/A_Journey_to_God.pdf' );
	$post[24680] = array( 'title' => 'السلوك مع الله: رحلة مع حكم ابن عطاء الله السكندري في ضوء القرآن والسنة والسنن الإلهية', 'excerpt' => 'السلوك مع الله: هذا الكتاب عبارة عن سرد لأهم القيم الروحية والسلوكية التي دونها وسجلها العارف بالله - وأحد أهم أئمة التصوف المعتدلين عقديًا وشريعةً – ابن عطاء الله السكندري- وهي رحلة يُطوف بنا فيها الدكتور-جاسر عودة - مع حكم ومأثورات ابن عطاء الله رضي الله عنه في ضوء القرآن والسنة النبوية المطهرة والسنن الإلهية الحاكمة لهذا الكون.', 'url' => $url.'/arabic/%d8%a7%d8%a8%d9%86-%d8%b9%d8%b7%d8%a7%d8%a1-%d8%a7%d9%84%d9%84%d9%87-%d8%a7%d9%84%d8%b3%d9%83%d9%86%d8%af%d8%b1%d9%8a/', 'image' => $url.'/wp-content/uploads/2016/02/السلوك-مع-الله.jpg', 'author_id' => '6505', 'author_name' => 'د. جاسر عودة ', 'book_url' => $url.'/books/Assuluk_ma3a_Allah.pdf' );
	$post[24685] = array( 'title' => 'الفهرس الوصفي لمخطوطات الشيخ عبد الله بن عبد اللطيف آل الشيخ', 'excerpt' => 'الفهرس الوصفي ل مخطوطات الشيخ عبد الله بن عبد اللطيف آل الشيخ: هو رسالة بحثية أعدها أحد الباحثين في جامعة الإمام محمد بن سعود الإسلامية في الرياض بالمملكة العربية السعودية – دكتور قاسم السمرائي- على أثر اقتراح من قسم المخطوطات والبحث العلمي بالجامعة بضرورة الاعتناء والاهتمام بموروث العالم الثبت الشيخ عبد الله بن عبد اللطيف آل الشيخ من قبل الجامعة.', 'url' => $url.'/arabic/%d8%a7%d9%84%d8%b4%d9%8a%d8%ae-%d8%b9%d8%a8%d8%af-%d8%a7%d9%84%d9%84%d9%87-%d8%a8%d9%86-%d8%b9%d8%a8%d8%af-%d8%a7%d9%84%d9%84%d8%b7%d9%8a%d9%81-%d8%a2%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%ae/', 'image' => $url.'/wp-content/uploads/2016/02/الفهرس-الوصفي-لمخطوطات-الشيخ-عبدالله-بن-عبد-اللطيف-آل-الشيخ.jpg', 'author_id' => '6506', 'author_name' => 'د. قاسم السامرائي', 'book_url' => $url.'/books/Descriptive_Index_of_Manuscripts_of_Shaykh_Abdullah_ibn_Abdulateef_Aal_Shaykh.pdf', 'publisher' => 'جامعة الامام محمد بن سعود' );
	$post[24689] = array( 'title' => 'علم الاكتناه العربي الإسلامي', 'excerpt' => 'كتاب علم الاكتناه العربي الإسلامي: هذا الكتاب هو عبارة عن رسالة بحثية استقصائية توثيقية عن علم الاكتناه الإسلامي أعدها الدكتور قاسم السمرائي ليوثق لعلم الاكتناه عند المسلمين والعرب من حيث نشأته وتطوره وأهم ما صنف فيه من مؤلفات.  ', 'url' => $url.'/arabic/%d8%b9%d9%84%d9%85-%d8%a7%d9%84%d8%a7%d9%83%d8%aa%d9%86%d8%a7%d9%87-%d8%a7%d9%84%d8%b9%d8%b1%d8%a8%d9%8a-%d8%a7%d9%84%d8%a5%d8%b3%d9%84%d8%a7%d9%85%d9%8a/', 'image' => $url.'/wp-content/uploads/2016/02/codi-ar-1.jpg', 'author_id' => '6506', 'author_name' => 'د. قاسم السامرائي', 'book_url' => $url.'/books/arabic_islamic_palaeography_and_codicology.pdf', 'publisher' => 'مركز الملك فيصل للبحوث والدراسات الإسلامية' );
	$post[24693] = array( 'title' => 'الفهرس الوصفي لمخطوطات السيرة النبوية ومتعلقاتها -المجلد الأول', 'excerpt' => 'الفهرس الوصفي لمخطوطات السيرة النبوية ومتعلقاتها: هذا الكتاب هو عبارة عن رسالة بحثية استقصائية توثيقية لكل ما كتب عن سيرة خاتم الأنبياء والمرسلين محمد صلى الله عليه وسلم، وما يتصل بهذه السيرة من فوائد وعبر وأحكام مستنبطة ودروس مستفادة، أعدها الدكتور قاسم السامرائي ليوثق بها علم السيرة النبوية منذ نشأته وتطوره وأهم ما صنف فيه من مؤلفات.', 'url' => $url.'/arabic/%d8%a7%d9%84%d8%b3%d9%8a%d8%b1%d8%a9-%d8%a7%d9%84%d9%86%d8%a8%d9%88%d9%8a%d8%a9-%d9%88%d9%85%d8%aa%d8%b9%d9%84%d9%82%d8%a7%d8%aa%d9%87%d8%a7/', 'image' => $url.'/wp-content/uploads/2016/02/3794-1-1.jpg', 'author_id' => '6506', 'author_name' => 'د. قاسم السامرائي', 'book_url' => $url.'/books/Descriptive_Index_of Sirah_Manuscripts_p1.pdf', 'publisher' => 'جامعه الامام محمد بن سعود' );
	$post[24695] = array( 'title' => 'الفهرس الوصفي لمخطوطات السيرة النبوية ومتعلقاتها - المجلد الثاني', 'excerpt' => 'الفهرس الوصفي لمخطوطات السيرة النبوية ومتعلقاتها: هذا الكتاب هو عبارة عن رسالة بحثية استقصائية توثيقية لكل ما كتب عن سيرة خاتم الأنبياء والمرسلين محمد صلى الله عليه وسلم، وما يتصل بهذه السيرة من فوائد وعبر وأحكام مستنبطة ودروس مستفادة، أعدها أحد الباحثين بجامعة الملك محمد بن سعود الإسلامية بالرياض بالمملكة العربية السعودية - الدكتور قاسم السامرائي- ليوثق بها علم السيرة النبوية منذ نشأته وتطوره وأهم ما صنف فيه من مؤلفات.', 'url' => $url.'/arabic/%d8%a7%d9%84%d8%b3%d9%8a%d8%b1%d8%a9-%d8%a7%d9%84%d9%86%d8%a8%d9%88%d9%8a%d8%a9-%d9%88%d9%85%d8%aa%d8%b9%d9%84%d9%82%d8%a7%d8%aa%d9%87%d8%a7-2/', 'image' => $url.'/wp-content/uploads/2016/02/Descriptive_Index_of_Sirah_Manuscripts_p2-1.jpg', 'author_id' => '6506', 'author_name' => 'د. قاسم السامرائي', 'book_url' => $url.'/books/Descriptive_Index_of Sirah_Manuscripts_p2.pdf', 'publisher' => 'جامعه الإمام محمد بن سعود' );
	$post[24699] = array( 'title' => 'الفهرس الوصفي لمخطوطات السيرة النبوية ومتعلقاتها - المجلد الثالث', 'excerpt' => 'الفهرس الوصفي لمخطوطات السيرة النبوية ومتعلقاتها المجلد الثالث: هذا الكتاب هو عبارة عن رسالة بحثية استقصائية توثيقية لكل ما كتب عن سيرة خاتم الأنبياء والمرسلين محمد صلى الله عليه وسلم، وما يتصل بهذه السيرة من فوائد وعبر وأحكام مستنبطة ودروس مستفادة، أعدها الدكتور قاسم السامرائي- ليوثق بها علم السيرة النبوية منذ نشأته وتطوره وأهم ما صنف فيه من مؤلفات.', 'url' => $url.'/arabic/%d8%a7%d9%84%d8%b3%d9%8a%d8%b1%d8%a9-%d8%a7%d9%84%d9%86%d8%a8%d9%88%d9%8a%d8%a9-%d9%88%d9%85%d8%aa%d8%b9%d9%84%d9%82%d8%a7%d8%aa%d9%87%d8%a7-3/', 'image' => $url.'/wp-content/uploads/2016/02/Descriptive_Index_of-Sirah_Manuscripts_p3-1.jpg', 'author_id' => '6506', 'author_name' => 'د. قاسم السامرائي', 'book_url' => $url.'/books/Descriptive_Index_of Sirah_Manuscripts_p3.pdf', 'publisher' => 'جامعه الامام محمد بن سعود' );
	$post[24703] = array( 'title' => 'المستشرقون الناطقون بالإنجليزية: دراسة نقدية', 'excerpt' => 'المستشرقون الناطقون بالإنجليزية: هي رسالة بحثية مترجمة  من الإنجليزية شاركت بها جامعة الإمام محمد ابن سعود الإسلامية بالرياض للتعرف عن قرب بالمستشرقين ومعرفة أهدافهم وغاياتهم التي يسعون إليها من دراساتهم الاستشرافية.', 'url' => $url.'/arabic/%d8%a7%d9%84%d9%85%d8%b3%d8%aa%d8%b4%d8%b1%d9%82%d9%88%d9%86-%d8%a7%d9%84%d9%86%d8%a7%d8%b7%d9%82%d9%88%d9%86-%d8%a8%d8%a7%d9%84%d8%a5%d9%86%d8%ac%d9%84%d9%8a%d8%b2%d9%8a%d8%a9/', 'image' => $url.'/wp-content/uploads/2016/02/Orientalists-1.jpg', 'author_id' => '1542', 'author_name' => 'عبد اللطيف الطيباوي', 'book_url' => $url.'/books/Orientalists.pdf', 'publisher' => 'جامعه الامام محمد بن سعود', 'translator' => 'الدكتور قاسم السامرئي' );
	$post[24706] = array( 'title' => 'وفاء الوفا بأخبار دار المصطفى (الجزء الاول)', 'excerpt' => 'وفاء الوفا بأخبار دار المصطفى (الجزء الأول): هذا الكتاب هو أجمع وأوفى ما صنف في وصف المدينة المنورة على ساكنها أفضل وأتم التسليم، أما مصنف هذا الكتاب فهو الإمام الحافظ العلم البحر واسع المعرفة، نور الدين علي بن عبد الله بن أحمد السمهودي، الشافعي الفقيه، جاور مدينة رسول الله صلى الله عليه وسلم وسكن بها ما يزيد على عشرين سنة، وقد تتبع كل ما صنف وألف من قبله في فضائل المدينة المنورة ووصف ما بها من طرقات وبيوت ووصف المسجد النبوي الشريف ما كان عليه في عهد النبوة ثم تتابع التجديد والتوسعة التي طرأت على المسجد النبوي منذ عصر الخليفة الراشد عمر بن الخطاب إلى أن خط السمهودي هذا المصنف بيديه، ويقع الكتاب في خمسة أجزاء.  ', 'url' => $url.'/arabic/%d9%88%d9%81%d8%a7%d8%a1-%d8%a7%d9%84%d9%88%d9%81%d8%a7-%d8%a8%d8%a3%d8%ae%d8%a8%d8%a7%d8%b1-%d8%af%d8%a7%d8%b1-%d8%a7%d9%84%d9%85%d8%b5%d8%b7%d9%81%d9%89-%d8%a7%d9%84%d8%ac%d8%b2%d8%a1-%d8%a7%d9%84-2/', 'image' => $url.'/wp-content/uploads/2016/02/wafa_al_wafa_bi_akhbar_dar_al_mustafa_p1-1.jpg', 'author_id' => '6507', 'author_name' => ' نور الدين علي بن عبد الله السمهودي', 'book_url' => $url.'/books/wafa_al_wafa_bi_akhbar_dar_al_mustafa_p1.pdf', 'publisher' => 'مؤسسة الفرقان للتراث الإسلامي' );
	$post[24709] = array( 'title' => 'وفاء الوفا بأخبار دار المصطفى (الجزء الثاني)', 'excerpt' => 'وفاء الوفا بأخبار دار المصطفى (الجزء الثاني) هذا الكتاب هو أجمع وأوفى ما صنف في وصف المدينة المنورة على ساكنها أفضل وأتم التسليم، أما مصنف هذا الكتاب فهو الإمام الحافظ العلم البحر واسع المعرفة، نور الدين علي بن عبد الله بن أحمد السمهودي، الشافعي الفقيه، جاور مدينة رسول الله صلى الله عليه وسلم وسكن بها ما يزيد على عشرين سنة، وقد تتبع كل ما صنف وألف من قبله في فضائل المدينة المنورة ووصف ما بها من طرقات وبيوت ووصف المسجد النبوي الشريف ما كان عليه في عهد النبوة ثم تتابع التجديد والتوسعة التي طرأت على المسجد النبوي منذ عصر الخليفة الراشد عمر بن الخطاب إلى أن خط السمهودي هذا المصنف بيديه، ويقع الكتاب في خمسة أجزاء.  ', 'url' => $url.'/arabic/%d9%88%d9%81%d8%a7%d8%a1-%d8%a7%d9%84%d9%88%d9%81%d8%a7-%d8%a8%d8%a3%d8%ae%d8%a8%d8%a7%d8%b1-%d8%af%d8%a7%d8%b1-%d8%a7%d9%84%d9%85%d8%b5%d8%b7%d9%81%d9%89-%d8%a7%d9%84%d8%ac%d8%b2%d8%a1-%d8%a7%d9%84/', 'image' => $url.'/wp-content/uploads/2016/02/wafa_al_wafa_bi_akhbar_dar_al_mustafa_p2-1.jpg', 'author_id' => '6507', 'author_name' => ' نور الدين علي بن عبد الله السمهودي', 'book_url' => $url.'/books/wafa_al_wafa_bi_akhbar_dar_al_mustafa_p2.pdf', 'publisher' => 'مؤسسة الفرقان للتراث الإسلامي' );
	$post[24712] = array( 'title' => 'وفاء الوفا بأخبار دار المصطفى (الجزء الثالث)', 'excerpt' => 'وفاء الوفاء بأخبار دار المصطفى ', 'url' => $url.'/arabic/%d9%88%d9%81%d8%a7%d8%a1-%d8%a7%d9%84%d9%88%d9%81%d8%a7-%d8%a8%d8%a3%d8%ae%d8%a8%d8%a7%d8%b1-%d8%af%d8%a7%d8%b1-%d8%a7%d9%84%d9%85%d8%b5%d8%b7%d9%81%d9%89/', 'image' => $url.'/wp-content/uploads/2016/02/wafa_al_wafa_bi_akhbar_dar_al_mustafa_p3-1.jpg', 'author_id' => '6507', 'author_name' => ' نور الدين علي بن عبد الله السمهودي', 'book_url' => $url.'/books/wafa_al_wafa_bi_akhbar_dar_al_mustafa_p3.pdf', 'publisher' => 'مؤسسة الفرقان للتراث الإسلامي' );
	$post[24715] = array( 'title' => 'وفاء الوفا بأخبار دار المصطفى (الجزء الرابع)', 'excerpt' => 'وفاء الوفا بأخبار دار المصطفى (الجزء الرابع) هذا الكتاب هو أجمع وأوفى ما صنف في وصف المدينة المنورة على ساكنها أفضل وأتم التسليم، أما مصنف هذا الكتاب فهو الإمام الحافظ العلم البحر واسع المعرفة، نور الدين علي بن عبد الله بن أحمد السمهودي، الشافعي الفقيه، جاور مدينة رسول الله صلى الله عليه وسلم وسكن بها ما يزيد على عشرين سنة، وقد تتبع كل ما صنف وألف من قبله في فضائل المدينة المنورة ووصف ما بها من طرقات وبيوت ووصف المسجد النبوي الشريف ما كان عليه في عهد النبوة ثم تتابع التجديد والتوسعة التي طرأت على المسجد النبوي منذ عصر الخليفة الراشد عمر بن الخطاب إلى أن خط السمهودي هذا المصنف بيديه، ويقع الكتاب في خمسة أجزاء.  ', 'url' => $url.'/arabic/%d9%88%d9%81%d8%a7%d8%a1-%d8%a7%d9%84%d9%88%d9%81%d8%a7-%d8%a8%d8%a3%d8%ae%d8%a8%d8%a7%d8%b1-%d8%af%d8%a7%d8%b1-%d8%a7%d9%84%d9%85%d8%b5%d8%b7%d9%81%d9%89-2/', 'image' => $url.'/wp-content/uploads/2016/02/wafa_al_wafa_bi_akhbar_dar_al_mustafa_p4-1.jpg', 'author_id' => '6507', 'author_name' => ' نور الدين علي بن عبد الله السمهودي', 'book_url' => $url.'/books/wafa_al_wafa_bi_akhbar_dar_al_mustafa_p4.pdf', 'publisher' => 'مؤسسة الفرقان للتراث الإسلامي' );
	$post[24719] = array( 'title' => 'وفاء الوفا بأخبار دار المصطفى: الجزء الخامس', 'excerpt' => 'وفاء الوفا بأخبار دار المصطفى (الجزء الخامس): هذا الكتاب هو أجمع وأوفى ما صنف في وصف المدينة المنورة على ساكنها أفضل وأتم التسليم، أما مصنف هذا الكتاب فهو الإمام الحافظ العلم البحر واسع المعرفة، نور الدين علي بن عبد الله بن أحمد السمهودي، الشافعي الفقيه، جاور مدينة رسول الله صلى الله عليه وسلم وسكن بها ما يزيد على عشرين سنة، وقد تتبع كل ما صنف وألف من قبله في فضائل المدينة المنورة ووصف ما بها من طرقات وبيوت ووصف المسجد النبوي الشريف ما كان عليه في عهد النبوة ثم تتابع التجديد والتوسعة التي طرأت على المسجد النبوي منذ عصر الخليفة الراشد عمر بن الخطاب إلى أن خط السمهودي هذا المصنف بيديه، ويقع الكتاب في خمسة أجزاء.', 'url' => $url.'/arabic/%d9%88%d9%81%d8%a7%d8%a1-%d8%a7%d9%84%d9%88%d9%81%d8%a7-%d8%a8%d8%a3%d8%ae%d8%a8%d8%a7%d8%b1-%d8%af%d8%a7%d8%b1-%d8%a7%d9%84%d9%85%d8%b5%d8%b7%d9%81%d9%89-3/', 'image' => $url.'/wp-content/uploads/2016/02/wafa_al_wafa_bi_akhbar_dar_al_mustafa_p5-1.jpg', 'author_id' => '6507', 'author_name' => ' نور الدين علي بن عبد الله السمهودي', 'book_url' => $url.'/books/wafa_al_wafa_bi_akhbar_dar_al_mustafa_p5.pdf', 'publisher' => 'مؤسسة الفرقان للتراث الإسلامي' );
	$post[24723] = array( 'title' => 'موارد السمهودي ومنهجه التاريخي في كتابه وفاء الوفا بأخبار المصطفى', 'excerpt' => 'موارد السمهودي ومنهجه التاريخي في كتابه وفاء الوفا بأخبار المصطفى: هذا الكتاب هو عبارة عن رسالة علمية بحثية لنيل الدرجة العلمية – الماجستير – في التاريخ الإسلامي ، من قسم التاريخ وعلومه بكلية الدرسات الإسلامية بجامعة أم القرى بمكة المكرمة – زادها الله تعظيما وتشريفا- للباحثة الدكتورة(هدى محمد سعيد سندي) تناولت فيه أهم موارد المحدث الحافظ السمهودي في كتابه القيم الجليل- وفاء الوفا بأخبار دار المصطفى، باعتباره أجمع وأشمل ما كتب في وصف مدينة رسول الله صلى الله عليه وسلم.', 'url' => $url.'/arabic/%d9%85%d9%88%d8%a7%d8%b1%d8%af-%d8%a7%d9%84%d8%b3%d9%85%d9%87%d9%88%d8%af%d9%8a-%d9%88%d9%85%d9%86%d9%87%d8%ac%d9%87-%d8%a7%d9%84%d8%aa%d8%a7%d8%b1%d9%8a%d8%ae%d9%8a/', 'image' => $url.'/wp-content/uploads/2016/03/اخبار-الوفا-1-1.png', 'author_id' => '6508', 'author_name' => 'هدى محمد سعيد', 'book_url' => $url.'/books/mawarid_al_samhudi_wa_manhajuhu_al_tarikhi_fi_kitabih_wafa_al_wafa_bi_akhbar_al_mustafa.pdf', 'publisher' => 'جامعة أم القرى' );
	$post[24747] = array( 'title' => 'الملخص المفيد في أحكام المسلم الجديد', 'excerpt' => 'كتاب الملخص المفيد في أحكام المسلم الجديد أحد أهم إصدارات وحدة البحث العلمي بإدارة الإفتاء التابعة لوزارة الأوقاف والشئون الإسلامية بدولة الكويت.', 'url' => $url.'/arabic/%d8%a7%d9%84%d9%85%d9%84%d8%ae%d8%b5-%d8%a7%d9%84%d9%85%d9%81%d9%8a%d8%af-%d9%81%d9%8a-%d8%a3%d8%ad%d9%83%d8%a7%d9%85-%d8%a7%d9%84%d9%85%d8%b3%d9%84%d9%85-%d8%a7%d9%84%d8%ac%d8%af%d9%8a%d8%af/', 'image' => $url.'/wp-content/uploads/2016/02/ar_almulakhas_almufeed-1.jpg', 'author_id' => '2249', 'author_name' => 'وزارة الأوقاف والشئون الإسلامية - الكويت', 'book_url' => $url.'/books/ar_almulakhas_almufeed.pdf', 'publisher' => 'وزارة الأوقاف والشؤون الإسلامية - إدارة الإفتاء' );
	$post[24757] = array( 'title' => 'التطور الموجه بين العلم والدين', 'url' => $url.'/arabic/%d8%a7%d9%84%d8%aa%d8%b7%d9%88%d8%b1-%d8%a7%d9%84%d9%85%d9%88%d8%ac%d9%87-%d8%a8%d9%8a%d9%86-%d8%a7%d9%84%d8%b9%d9%84%d9%85-%d9%88%d8%a7%d9%84%d8%af%d9%8a%d9%86/', 'image' => $url.'/wp-content/uploads/2016/02/Arabic-al-tatawor-al-muwajah.jpg', 'author_id' => '6449', 'author_name' => 'هشام عزمي', 'book_url' => $url.'/dl/books/Arabic-al-tatawor-al-muwajah.pdf', 'publisher' => 'دار الكاتب للنشر والتوزيع' );
	$post[24761] = array( 'title' => 'الإجابة: القرآن وأسئلتك الوجودية', 'excerpt' => 'في رحلة غير تقليدية مع الأسئلة الوجودية، تلك الأسئلة التي (وجدنا) أنفسنا مغموسين فيها دون أن ندري، حيث انزلق وعينا الإنساني بشكل مفاجئ من ذلك العالم الساكن الغامض الذي كان يحيا فيه إلى عالم مادي واقعي تمامًا يمكننا فيه أن نشعر بهواء البحر، وبمذاق الجمال، وبدفء الحب، وبرهبة العجز وألم الخيانة..  وجدنا أنفسنا في عالم مادي أقل غموضًا مما يبدو في أذهاننا المليئة بالمعاني المجردة، مع وعي فريد أكثر تعقيدًا ممّا تحتاجه المتطلبات الحياتية! حينها بدأنا نتساءل: من أين أتينا؟ وإلى أين سنذهب؟ ما المصير؟ من أوجدنا؟ ماذا يريد منا؟  وحالنا مع هذه الأسئلة، أقرب لحال الطالب في (الاختبار المفتوح)، حيث يمكنك أن تدخل الامتحان بكل ما تشاء من المراجع؛ فالهدف في النهاية اختبار فهمك وتطبيقك لا قدرتك على الحفظ. وبالفعل أنت لن تحتاج أن تحفظ الكتاب عن ظهر قلب، تحتاج كي تصل إلى ما تريده منه أن تفهمه فهمًا كاملًا، فبالرغم من أنك لن تحتاج إلا لكتاب واحد، لكن تناولك لهذا الكتاب يجب أن يكون مختلفا تماما. ', 'url' => $url.'/arabic/%d8%a7%d9%84%d8%a5%d8%ac%d8%a7%d8%a8%d8%a9-%d8%a7%d9%84%d9%82%d8%b1%d8%a2%d9%86-%d9%88%d8%a3%d8%b3%d8%a6%d9%84%d8%aa%d9%83-%d8%a7%d9%84%d9%88%d8%ac%d9%88%d8%af%d9%8a%d8%a9/', 'image' => $url.'/wp-content/uploads/2016/02/Arabic-Al-ejabah.jpg', 'author_id' => '6509', 'author_name' => 'مهاب السعيد', 'book_url' => $url.'/dl/books/Arabic-Al-ejabah.pdf', 'publisher' => 'دار الكاتب للنشر والتوزيع' );
	$post[24767] = array( 'title' => 'ŠTA BI SVAKI MUSLIMAN TREBAO DA ZNA', 'excerpt' => 'ŠTA BI SVAKI MUSLIMAN TREBAO DA ZNA    Ova knjiga definiše vjeru islam, pojašnjava da je to prirodna vjera, i vjera svih vjerovjesnika, a zatim pojašnjava najvažnije temelje te vjere. Potom, u njoj se ukazuje na najvažnija pitanja vezana za akidu ili vjerovanje jednog muslimana, a koje on mora spoznati. U nastavku knjige se govori o stubovima, ili rukonovima vjere islama, a potom se ukazuje na načinu ophođenja muslimana sa društvom u kojem živi.', 'url' => $url.'/bosnian/sta-bi-svaki-musliman-trebao-da-zna/', 'image' => $url.'/wp-content/uploads/2016/03/Bosnian-ŠTA-BI-SVAKI-MUSLIMAN-TREBAO-DA-ZNA.jpg', 'author_id' => '2249', 'author_name' => 'وزارة الأوقاف والشئون الإسلامية - الكويت', 'book_url' => $url.'/dl/books/Bosnian-STA-BI-SVAKI-MUSLIMAN-TREBAO-DA-ZNA.pdf' );
	$post[24827] = array( 'title' => 'حبي العظيم للمسيح قادني إلى الإسلام', 'excerpt' => 'هذا الكتاب هو عبارة عن تجربة حياتية عايشها الكاتب – سايمون الفريدو كاراباللو- بنفسه  قادته إلى المعرفة الحقّة بحقيقة الإله الذي ينبغي أن يعبد وأن يوحد، فقادته هذه التجربة إلى الانتقال من الكاثوليكية التي لاحظ أنها مليئة بالمتناقضات التي يصعب على فكر الشخص الصحيح أن يستوعب ويجمع بين هذه المتناقضات إلى الدين الذي رآه يتوافق ويتطابق مع الصورة التي رسمها هو بنفسه لحقيقة الإله الحق، وأسلوب الحياة المستقيم الذي يدفع إلى طريق الفلاح في الدينا والآخرة، فأقر الباحث عن الحقيقة بالإسلام وشهد أن لا إله إلا الله وأن محمدا رسول الله.', 'url' => $url.'/arabic/%d8%ad%d8%a8%d9%8a-%d8%a7%d9%84%d8%b9%d8%b8%d9%8a%d9%85-%d9%84%d9%84%d9%85%d8%b3%d9%8a%d8%ad-%d9%82%d8%a7%d8%af%d9%86%d9%8a-%d8%a5%d9%84%d9%89-%d8%a7%d9%84%d8%a5%d8%b3%d9%84%d8%a7%d9%85/', 'image' => $url.'/wp-content/uploads/2016/03/My-Great-Love-for-Jesus-Led-Me-to-Islam_ara.png', 'author_id' => '6511', 'author_name' => 'سايمون الفريدو كارابللو', 'book_url' => $url.'/wp-content/uploads/2016/03/My-Great-Love-for-Jesus-Led-Me-to-Islam_ara.pdf', 'publisher' => 'نسخة مواقع الانترنت ', 'translator' => 'د. أحمد عبدالفتاح الليثي' );
	$post[24885] = array( 'title' => 'لك القرار', 'excerpt' => 'لك القرار هو عبارة عن قصص من واقع الحياة يقوم المؤلف بسردها سردا موضوعيا خاليا من أي هوى أو نزوع إلى طرف معين، محكما في هذه المشاهد الحياتية الواقعية العقل والمنطق كمحور مشترك يمكن التعويل عليه في التحكيم والاحتكام عند الاختلاف في الرؤى والاتجاهات الفكرية والعقدية، وهو كتاب من سلسلة كتب تصدرها مؤسسة الجديد النافع تحمل نفس الاسم &quot;سلسلة الجديد النافع&quot; بدأتها المؤسسة بهذا الكتاب القيم الرائع- لك القرار- للكاتب الأستاذ الدكتورتوفيق بن خلف الرفاعي.', 'url' => $url.'/arabic/%d9%84%d9%83-%d8%a7%d9%84%d9%82%d8%b1%d8%a7%d8%b1/', 'image' => $url.'/wp-content/uploads/2016/03/لك_القرار-1.jpg', 'author_id' => '6512', 'author_name' => 'توفيق بن خلف الرفاعي', 'book_url' => $url.'/books/%D9%84%D9%83_%D8%A7%D9%84%D9%82%D8%B1%D8%A7%D8%B1.pdf', 'publisher' => 'مؤسسة الجديد النافع ' );
