	$post[24931] = array( 'title' => 'A Visão do Islam quanto ao sexo', 'excerpt' => 'Em nome de Deus, o Clemente, o Misericordioso Louvado seja Deus, que as benções e a paz estejam com o nosso Profeta Mohammad, com sua família e com seus companheiros.  ', 'url' => $url.'/portuguese/visao-islam-quanto-ao-sexo/', 'image' => $url.'/wp-content/uploads/2016/03/A-Visão-do-Islam-quanto-ao-sexo-.png', 'author_id' => '6513', 'author_name' => 'Dr. Abd Ar-Rahman bin Abd Al-Karim Ash-Sheha', 'book_url' => $url.'/books/po_A_vision_do_Islam_quanto_ao_sexo_por.pdf', 'publisher' => 'www.islamland.com', 'translator' => 'EUROPEAN ISLAMIC RESEARCH CENTER (EIRC) ' );
	$post[24936] = array( 'title' => 'Uma Única Mensagem', 'excerpt' => 'Uma Única Mensagem    Então, se você é um buscador sincero da verdade e amante da salvação, você pode querer considerar isso AGORA, antes que seja tarde demais! ANTES DA MORTE! Isso pode ser em breve! Quem sabe?! Mais uma coisa…', 'url' => $url.'/portuguese/uma-unica-mensagem/', 'image' => $url.'/wp-content/uploads/2016/03/po_Uma_Única_Mensagem_03-1.jpg', 'author_id' => '451', 'author_name' => 'Naji Ibrahim Arfaj', 'book_url' => $url.'/books/po_Uma_Uunica_Mensagem.pdf', 'publisher' => 'http://www.islamland.com/' );
