	$post[25177] = array( 'title' => 'الضوء اللامع لأهل القرن التاسع (المجلد الأول)', 'excerpt' => 'الضوء اللامع لأهل القرن التاسع (المجلد الأول) هو كتاب للعلامة الحافظ المؤرخ الناقد شمس الدين محمد بن عبد الرحمن السخاوي - رحمه الله ونفع بما خلف من علم - يسلط فيه الضوء على أهم العلماء وأعلام الملة والملوك والقضاة والخلفاء في القرن التاسع من الهجرة النبوية المباركة من مكة المكرمة إلى المدينة النبوية المنورة.', 'url' => $url.'/arabic/%d8%a7%d9%84%d8%b6%d9%88%d8%a1-%d8%a7%d9%84%d9%84%d8%a7%d9%85%d8%b9-%d9%84%d8%a3%d9%87%d9%84-%d8%a7%d9%84%d9%82%d8%b1%d9%86-%d8%a7%d9%84%d8%aa%d8%a7%d8%b3%d8%b9/', 'image' => $url.'/wp-content/uploads/2016/04/الضوء-اللامع-1.png', 'author_id' => '6522', 'author_name' => 'شمس الدين محمد بن عبد الرحمن السخاوي', 'book_url' => $url.'/books/ar_Al_daw_al_lami_li_ahl_al_qarn_al_tasi_part_1.pdf', 'publisher' => 'دار الجيل' );
