	$post[25300] = array( 'title' => 'ﻓﻜﺎ ﻥ ﺇﺴﻼﻡ ﻫﻭﻍ ﺼﻐﻜﻬﻴﺏ (التعريف الموجز بالإسلام) باللغة التشامية', 'excerpt' => ' مقالة باللغة التشامية تعرف بالدين الإسلامي بإيجاز، وتبين شموليته لجميع جوانب الحياة مع بيان أهم أركانه الستة.', 'url' => $url.'/chami/%ef%bb%93%ef%bb%9c%ef%ba%8e-%ef%bb%a5-%ef%ba%87%ef%ba%b4%ef%bb%bc%ef%bb%a1-%ef%bb%ab%ef%bb%ad%ef%bb%8d-%ef%ba%bc%ef%bb%90%ef%bb%9c%ef%bb%ac%ef%bb%b4%ef%ba%8f/', 'image' => $url.'/wp-content/uploads/2016/04/cj_Brief_Presentation_of_Islam-1.jpg', 'author_id' => '6524', 'author_name' => 'عمادة البحث العلمي بالجامعة الإسلامية', 'book_url' => $url.'/books/cj_Brief_Presentation_of_Islam.pdf', 'publisher' => 'www.iu.edu.sa' );
	$post[25305] = array( 'title' => 'ಇಸ್ಲಾಂ ಎಂದರೇನು? (What is Islam?)', 'excerpt' => 'ಈ ಪುಸ್ತಕವು ಇಸ್ಲಾಮಿನ ಕುರಿತಾದ ಕೆಲವು ತಪ್ಪುಕಲ್ಪನೆಗಳನ್ನು ವಿವರಿಸುತ್ತದೆ . ಒಂದು ಜ್ಞಾನಪುರ್ಣ ರೀತಿಯಲ್ಲಿ ಅವುಗಳನ್ನು ಖುರ್’ಆನ್ ಹಾಗೂ ಸುನ್ನತ್ ನ ಆಧಾರದಲ್ಲಿ ಹೋಗಲಾಡಿಸುವ ಪ್ರಯತ್ನವನ್ನು ಮಾಡುತ್ತದೆ.  ', 'url' => $url.'/kannada/%e0%b2%87%e0%b2%b8%e0%b3%8d%e0%b2%b2%e0%b2%be%e0%b2%82-%e0%b2%8e%e0%b2%82%e0%b2%a6%e0%b2%b0%e0%b3%87%e0%b2%a8%e0%b3%81/', 'image' => $url.'/wp-content/uploads/2016/04/kn_islam_yendarenu-1.jpg', 'author_id' => '6525', 'author_name' => 'Muhammad Akbar', 'book_url' => $url.'/books/kn_islam_yendarenu.pdf', 'publisher' => 'DAWA PUBLICATIONS Affiliated to Jamiate Ahle Hadees Karnataka Goa' );
	$post[25308] = array( 'title' => 'ಮರಣ ಮತ್ತು ಮರಣಾನಂತರ ಜೀವನ; ಇಸ್ಲಾಮಿನ ದೃಷ್ಟಿಕೋನದಲ್ಲಿ (Death and life after death in Islam)', 'excerpt' => 'ಮರಣದ ಕುರಿತು ಕೆಲವು ಉದ್ಭೋಧನೆಗಳ ಕಿರುಪತ್ರ. ಇದರಲ್ಲಿ ಮರಣದ ನೆನಪು, ಅದರ ವಿವರಣೆ, ಮರಣಾನಂತರ ಜೀವನ, ಅಂತ್ಯದಿನದ ಕೆಲವು ಭಯಾನಕ ಸನ್ನಿವೇಶಗಳನ್ನು ಉಲ್ಲೇಖಿಸಲಾಗಿವೆ. ಇದನ್ನು ಮುದ್ರಿಸಿ ಸಾರ್ವಜನಿಕ ಸ್ಥಳಗಳಲ್ಲಿ ವಿತರಿಸುವುದು ಉತ್ತಮವಾಗಿದೆ.  ', 'url' => $url.'/kannada/%e0%b2%ae%e0%b2%b0%e0%b2%a3-%e0%b2%ae%e0%b2%a4%e0%b3%8d%e0%b2%a4%e0%b3%81-%e0%b2%ae%e0%b2%b0%e0%b2%a3%e0%b2%be%e0%b2%a8%e0%b2%82%e0%b2%a4%e0%b2%b0-%e0%b2%9c%e0%b3%80%e0%b2%b5%e0%b2%a8-%e0%b2%87/', 'image' => $url.'/wp-content/uploads/2016/04/kn_death-1.jpg', 'author_id' => '6526', 'author_name' => 'Umar Ahmad Almadani', 'book_url' => $url.'/books/kn_death.pdf', 'publisher' => 'Islamic Propagation Office in Rabwah' );
