	$post[26262] = array( 'title' => 'Does Islam Command Attacking Churches?', 'excerpt' => 'It is safe to say that a given religion can be judged correctly only by two things: its own teachings and the practice of the mainstream doctrine of this religion. A religion cannot be judged by the centrifugal practices or beliefs of some followers, be they liberal or extremist, hither or thither.', 'url' => $url.'/english/does-islam-command-attacking-churches/', 'image' => $url.'/wp-content/uploads/2016/08/Does-Islam-Command-Attacking-Churches-1.jpg', 'author_id' => '164', 'author_name' => 'E-Da`wah Committee (EDC)', 'book_url' => $url.'/books/en_Does_Islam_Command_Attacking_Churches.pdf', 'publisher' => 'E-Da`wah Committee' );
