	$post[27248] = array( 'title' => 'JESUS era Cristão ou Muçulmano?', 'excerpt' => 'Cristo é derivado do antigo Grego: Χριστός, Khristós, que signiöca ‘ungido’, que é uma tradução do Hebreu ח ַשׁי ִמ)  Māšîah), o Messias, utilizado como nome de Jesus. “Islam” signiöca Completa, Perfeita e Pacíöca Submissão à vontade de Deus Todo-Poderoso.', 'url' => $url.'/portuguese/jesus-era-cristao-ou-muculmano/', 'image' => $url.'/wp-content/uploads/2016/12/pt_Jesus_era_cristao_ou_muculmano-1-240x312.jpg', 'author_id' => '6672', 'author_name' => 'Abu Karim El-Marakshy', 'book_url' => $url.'/books/pt_Jesus_era_cristao_ou_muculmano.pdf', 'publisher' => 'islamhouse.com - www.islamland.com - islam-port.com', 'translator' => 'Tarek Youssef Fawaz' );
