	$post[27479] = array( 'title' => 'O QUE DIZ O ISLÃO ACERCA DO TERRORISMO', 'excerpt' => ' “terrorismo” é considerado como uma das principais barreiras à paz e à segurança das nossas sociedades. A palavra terrorismo entrou em uso somente algumas décadas atrás.', 'url' => $url.'/portuguese/o-que-diz-o-islao-acerca-do-terrorismo/', 'image' => $url.'/wp-content/uploads/2017/02/pt_what_islam_says_about_terrorism-1-240x312.jpg', 'author_id' => '614', 'author_name' => 'www.islamic-message.net', 'book_url' => $url.'/books/pt_what_islam_says_about_terrorism.pdf', 'publisher' => 'islamhouse.com' );
