	$post[28594] = array( 'title' => 'GUIADOS? El Islam La culminación de la Revelación?', 'excerpt' => 'Siguiendo el primer libro de esta serie –el tsunami teológico, MisGod’ed[¿Desviados?]– el autor, teólogo y médico, Laurence B. Brown, nos provee un convincente argumento en yGod’ed[¿Guiados?', 'url' => $url.'/spanish/guiados-el-islam-la-culminacion-de-la-revelacion/', 'image' => $url.'/wp-content/uploads/2017/04/GUIADOS-El-Islam-La-culminación-de-la-Revelación-228x312.jpg', 'author_id' => '279', 'author_name' => 'Laurence B. Brown MD', 'book_url' => $url.'/books/se_GODED.pdf', 'publisher' => 'http://leveltruth.com', 'translator' => 'Said Abdunur Pedraza' );
	$post[28599] = array( 'title' => 'GLORIFIÉ Étude de cas : L’islam, ultime complément de la Révélation', 'excerpt' => 'À la suite du premier livre de cette série, le tsunami théologique, Dieu Malgré Lui, l’auteur, érudit religieux et médecin, Laurence B. Brown apporte un argument irréfutable dans Glorifié? Étude de cas : L’Islam, ultime complément de la Révélation.', 'url' => $url.'/french/glorifie-etude-de-cas-lislam-ultime-complement-de-la-revelation/', 'image' => $url.'/wp-content/uploads/2017/04/GLORIFIÉ-Étude-de-cas-L’islam-ultime-complément-de-la-Révélation-240x312.jpg', 'author_id' => '279', 'author_name' => 'Laurence B. Brown MD', 'book_url' => $url.'/books/fr_GODED.pdf', 'publisher' => 'http://leveltruth.com', 'translator' => 'Suzanne Charest' );
	$post[28611] = array( 'title' => 'E PRANOVA ISLAMIN, POR... Ç’ TË BËJ MË TEJ…?', 'excerpt' => 'E PRANOVA ISLAMIN, POR... Ç’ TË BËJ MË TEJ…?   Një nga mësimet e para që kam nxënë që në fillimet e mia si autor, ka qenë si ta lokalizoja ', 'url' => $url.'/albanian/e-pranova-islamin-por-c-te-bej-tej/', 'image' => $url.'/wp-content/uploads/2017/04/E-PRANOVA-ISLAMIN-240x312.jpg', 'author_id' => '279', 'author_name' => 'Laurence B. Brown MD', 'book_url' => $url.'/books/al_Bearing_True_Witness.pdf', 'publisher' => 'http://leveltruth.com' );
	$post[28614] = array( 'title' => 'Wahres Zeugnis ablegend', 'excerpt' => 'Nachdem eine Person diese Wahl getroffen hat, tritt sie durch die Schahada, d.h. die Bezeugung des Glaubens, in den Islam ein und wird Muslim. Diese Bezeugung lautet: “Asch-hadu an la ilaha illa Llah(u), wa asch-hadu anna Muhammadan Rasulu Llah”', 'url' => $url.'/deutsch/wahres-zeugnis-ablegendwahres-zeugnis-ablegend/', 'image' => $url.'/wp-content/uploads/2017/04/Wahres-Zeugnis-ablegend-240x312.jpg', 'author_id' => '279', 'author_name' => 'Laurence B. Brown MD', 'book_url' => $url.'/books/de_Wahres_Zeugnis_ablegend.pdf', 'publisher' => 'http://leveltruth.com', 'translator' => 'Hamid Hennawi' );
	$post[28617] = array( 'title' => 'L’INFLUENCE D’UN TÉMOIGNAGE AUTHENTIQUE', 'excerpt' => 'Dr Brown est un ophtalmologiste praticien, qui est revenu à l&#039;islam, il est l&#039;auteur de plusieurs livres d&#039;avant-garde de Dawa islamique (c.-à-d. invitation). Son premier livre, Le Premier et Dernier Commandement, est un argument complet à l&#039;appui de la revendication islamique en ce qui a trait à la continuité de la révélation.', 'url' => $url.'/french/linfluence-dun-temoignage-authentique/', 'image' => $url.'/wp-content/uploads/2017/04/L’INFLUENCE-D’UN-TÉMOIGNAGE-AUTHENTIQUE-240x312.jpg', 'author_id' => '279', 'author_name' => 'Laurence B. Brown MD', 'book_url' => $url.'/books/fr_LINFLUENCE_DUN_TEMOIGNAGE_AUTHENTIQUE.pdf', 'publisher' => 'http://leveltruth.com', 'translator' => 'Suzanne Charest' );
