	$post[28899] = array( 'title' => 'अज़ान और नमाज़ क्या है?', 'excerpt' => 'दुश्मनों के क्या अधिकार हैं? अज़ान और नमाज़ के संबंध में अनभिगता के कारण बड़ी भ्रान्तियाँ पाई जाती हैं। यह बात उस समय और दुखद हो जाती है जब बिना सही जानकारी के इस्लाम की इस पवित्र एवं कल्याणकारी उपासना के संबंध में निसंकोच अनुचित टीका-टिप्पणी तक ', 'url' => $url.'/hindi/%e0%a4%85%e0%a4%9c%e0%a4%bc%e0%a4%be%e0%a4%a8-%e0%a4%94%e0%a4%b0-%e0%a4%a8%e0%a4%ae%e0%a4%be%e0%a4%9c%e0%a4%bc-%e0%a4%95%e0%a5%8d%e0%a4%af%e0%a4%be-%e0%a4%b9%e0%a5%88/', 'image' => $url.'/wp-content/uploads/2017/05/अज़ान-और-नमाज़-क्या-है-240x312.jpg', 'author_id' => '6772', 'author_name' => 'नसीम ग़ाज़ी', 'book_url' => $url.'/books/in_Definition_of_prayer_and_adhan.pdf', 'publisher' => 'www.islamicwebdunia.com' );
	$post[28919] = array( 'title' => 'इस्लाम और मानव-समाज', 'excerpt' => 'इस्लाम और मानव समाजः इस्लाम जहाँ एक तरफ मानव की उत्पत्ति की वास्तविकता, इस संसार में उसके उद्देश्य, अपने पालनहार के प्रति उसके कर्तव्यों को स्पष्ट करता है, वहीं दूसरी ओर उस समाज के प्रति भी मार्गदर्शन करता है जिसमें मनुष्य जीवन यापन करता है। इस्लाम उसे ', 'url' => $url.'/hindi/%e0%a4%87%e0%a4%b8%e0%a5%8d%e0%a4%b2%e0%a4%be%e0%a4%ae-%e0%a4%94%e0%a4%b0-%e0%a4%ae%e0%a4%be%e0%a4%a8%e0%a4%b5-%e0%a4%b8%e0%a4%ae%e0%a4%be%e0%a4%9c/', 'image' => $url.'/wp-content/uploads/2017/05/इस्लाम-और-मानव-समाज-240x312.jpg', 'author_id' => '6773', 'author_name' => 'सैयद मुहम्मद इक़बाल', 'book_url' => $url.'/books/in_Islam_and_human_society.pdf', 'publisher' => 'islamhouse.com' );
	$post[28923] = array( 'title' => 'इस्लाम का रास्ता', 'excerpt' => 'यह पुस्तक इस्लाम धर्म का परिचय प्रस्तुत करती है जिस पर अल्लाह ने धर्मों का अंत कर दिया है और उसे अपने समस्त बंदों के लिए पसंद कर लिया है तथा इस धर्म में प्रवेश करने का आदेश दिया है।', 'url' => $url.'/hindi/%e0%a4%87%e0%a4%b8%e0%a5%8d%e0%a4%b2%e0%a4%be%e0%a4%ae-%e0%a4%95%e0%a4%be-%e0%a4%b0%e0%a4%be%e0%a4%b8%e0%a5%8d%e0%a4%a4%e0%a4%be/', 'image' => $url.'/wp-content/uploads/2017/05/इस्लाम-का-रास्ता-240x312.jpg', 'author_id' => '6773', 'author_name' => 'सैयद मुहम्मद इक़बाल', 'book_url' => $url.'/books/in_The_road_to_Islam.pdf', 'publisher' => 'दारुल वरक़ात अल-इल्मिया मुद्रक एवं वितरक' );
	$post[28928] = array( 'title' => 'इस्लाम धर्म', 'excerpt' => 'इस्लाम धर्मः इस पुस्तक में इस्लाम धर्म के आचार-विचार, उसके मूल सिद्धांत, उपासना, इस्लामी जीवन-व्यवस्था आदि का तर्क और तत्वदर्शिता सहित विस्तृत परिचय प्रस्तुत किया गया है। इस्लाम क्या है?', 'url' => $url.'/hindi/%e0%a4%87%e0%a4%b8%e0%a5%8d%e0%a4%b2%e0%a4%be%e0%a4%ae-%e0%a4%a7%e0%a4%b0%e0%a5%8d%e0%a4%ae/', 'image' => $url.'/wp-content/uploads/2017/05/इस्लाम-धर्म-240x312.jpg', 'author_id' => '2292', 'author_name' => 'अबुल आला मौदूदी', 'book_url' => $url.'/books/in_Religion_of_Islam.pdf', 'publisher' => 'http://www.mmipublishers.net', 'translator' => 'मुहम्मद फ़ारूक़ खाँ' );
	$post[28933] = array( 'title' => 'इस्लाम में खाललस इन्सानी अधिकार', 'excerpt' => 'इस्लाम इन्सान की हैसियत से इन्सान के कुछ हक़ और अधिकार मुक़र्रर करता है। दूसरे शब्दों में इसका मतलब यह है कि हर इन्सान चाहे, वह हमारे अपने देश और वतन का हो या किसी दूसरे देश और वतन का,', 'url' => $url.'/hindi/%e0%a4%87%e0%a4%b8%e0%a5%8d%e0%a4%b2%e0%a4%be%e0%a4%ae-%e0%a4%ae%e0%a5%87%e0%a4%82-%e0%a4%96%e0%a4%be%e0%a4%b2%e0%a4%b2%e0%a4%b8-%e0%a4%87%e0%a4%a8%e0%a5%8d%e0%a4%b8%e0%a4%be%e0%a4%a8%e0%a5%80/', 'image' => $url.'/wp-content/uploads/2017/05/इस्लाम-में-खाललस-इन्सानी-अधिकार-240x312.jpg', 'author_id' => '2291', 'author_name' => 'अताउर्रहमान ज़ियाउल्लाह', 'book_url' => $url.'/books/in_Human_rights_in_Islam.pdf', 'publisher' => 'islamhouse.com' );
	$post[28936] = array( 'title' => 'इस्लाम और विज्ञान', 'excerpt' => 'इस्लाम के अनुयायी मुसलमानों का मानना है कि कुर्आन करीम अल्लाह का वचन – कलाम – है, जिसे उसने वह्य –प्रकाशना- के माध्यम से अपने अंतिम संदेष्टा मुहम्मद सल्लल्लाहु अलैहि व सल्लम पर अवतिरत किया है', 'url' => $url.'/hindi/%e0%a4%87%e0%a4%b8%e0%a5%8d%e0%a4%b2%e0%a4%be%e0%a4%ae-%e0%a4%94%e0%a4%b0-%e0%a4%b5%e0%a4%bf%e0%a4%9c%e0%a5%8d%e0%a4%9e%e0%a4%be%e0%a4%a8/', 'image' => $url.'/wp-content/uploads/2017/05/इस्लाम-और-विज्ञान-240x312.jpg', 'author_id' => '2303', 'author_name' => 'ज़ाकिर नायिक', 'book_url' => $url.'/books/in_Quran_and_sciences.pdf', 'publisher' => 'http://www.alhasanatbooks.com/' );
	$post[28944] = array( 'title' => 'क़ुरआन पर अनुचित आक्षेप', 'excerpt' => 'क़ुरआन पर अनुचित आक्षेपः यह पुस्तक उन आक्षेपों पर आधारित है जिन्हें कुछ हिन्दू संस्थाओं और लोगों की ओर से क़ुरआन की कुछ आयतों के बारे में उन्हें उनकी पृष्टिभूमि और संदर्भ से अलग करके और उनका मनमाना अनुवाद और व्याख्या करके बड़े पैमाने पर फैलाया जाता है। ये आक्षेप क़ुरआन मजीद की उन आयतों के बारे में हैं जिनका संबंध विशेषकर जिहाद,', 'url' => $url.'/hindi/%e0%a4%95%e0%a4%bc%e0%a5%81%e0%a4%b0%e0%a4%86%e0%a4%a8-%e0%a4%aa%e0%a4%b0-%e0%a4%85%e0%a4%a8%e0%a5%81%e0%a4%9a%e0%a4%bf%e0%a4%a4-%e0%a4%86%e0%a4%95%e0%a5%8d%e0%a4%b7%e0%a5%87%e0%a4%aa/', 'image' => $url.'/wp-content/uploads/2017/05/क़ुरआन-पर-अनुचित-आक्षेप-240x312.jpg', 'author_id' => '6772', 'author_name' => 'नसीम ग़ाज़ी', 'book_url' => $url.'/books/in_False_misconceptions_about_the_quran.pdf', 'publisher' => ' www.momeen.blogspot.com' );
	$post[28947] = array( 'title' => 'मानवता का संदेश', 'excerpt' => 'इस पुस्तिका में यह उल्लेख किया गया है कि समस्त मानवीय धर्मों में मानवता और नैतिकता सम्बन्धी शिक्षाओं का वर्णन है, तथा विशेष रूप से इस्लाम धर्म के मूल ग्रंथ दिव्य कुरआन की अमृत वाणियों और मानवता उपकारक पैगंबर मुहम्मद सल्लल्लाहु अलैहि व सल्लम के मधुर ', 'url' => $url.'/hindi/%e0%a4%ae%e0%a4%be%e0%a4%a8%e0%a4%b5%e0%a4%a4%e0%a4%be-%e0%a4%95%e0%a4%be-%e0%a4%b8%e0%a4%82%e0%a4%a6%e0%a5%87%e0%a4%b6/', 'image' => $url.'/wp-content/uploads/2017/05/मानवता-का-संदेश-240x312.jpg', 'author_id' => '6775', 'author_name' => 'रफीक़ अहमद', 'book_url' => $url.'/books/in_Human.pdf', 'publisher' => 'islamhouse.com' );
	$post[28950] = array( 'title' => 'सत्य धर्म', 'excerpt' => 'सत्य धर्मः इस पुस्तक में हर बुद्धिमान पुरूष और नारी को अपने महान सृष्टा सर्वसंसार के पालनहार को पहचानने और उसके दर्शाए हुए सत्य मार्ग पर चलने का निमंत्रण दिया गया है। क्योंकि उसी के अंदर लोक और परलोक में कल्याण', 'url' => $url.'/hindi/%e0%a4%b8%e0%a4%a4%e0%a5%8d%e0%a4%af-%e0%a4%a7%e0%a4%b0%e0%a5%8d%e0%a4%ae/', 'image' => $url.'/wp-content/uploads/2017/05/सत्य-धर्म-240x312.jpg', 'author_id' => '6776', 'author_name' => 'अब्दुर्रहमान बिन हम्माद अल-उम्र', 'book_url' => $url.'/books/in_Religion_of_truth.pdf', 'publisher' => 'www.islamicbook.ws', 'translator' => 'रज़ाउर्रहमान अनसारी' );
	$post[28955] = array( 'title' => 'सत्य मार्ग', 'excerpt' => 'यह पुस्तक सत्य धर्म को पहचानने और उसे स्वीकारने का आमंत्रण देती है क्योंकि वही एक मात्र विकल्प है जो मानवता के लिए लोक एवं परलोक में सफलता, सौभाग्य और नरक से मोक्ष प्राप्त करने का एकमात्र साधन है। प्रस्तुत पुस्तक इस बात पर प्रकाश डालती है कि मानव जाति की रचना का उद्देश्य क्या है ', 'url' => $url.'/hindi/%e0%a4%b8%e0%a4%a4%e0%a5%8d%e0%a4%af-%e0%a4%ae%e0%a4%be%e0%a4%b0%e0%a5%8d%e0%a4%97/', 'image' => $url.'/wp-content/uploads/2017/05/सत्य-मार्ग-240x312.jpg', 'author_id' => '2290', 'author_name' => 'अताउर्रहमान अब्दुल्लाह सईदी', 'book_url' => $url.'/books/in_Come_to_the_truth.pdf', 'publisher' => 'www.ahsaic.com' );
	$post[28957] = array( 'title' => 'मुहम्मद सल्लल्लाहु अलैहि व सल्लम और भारतीय धर्म ग्रन्थ', 'excerpt' => 'मुहम्मद सल्लल्लाहु अलैहि व सल्लम के आगमन की पूर्व सूचना हमें बाइबल, तौरेत और अन्य धर्म ग्रन्थों में मिलती है, यहाँ तक कि भारतीय धर्मग्रम्थों में भी आप के आने की भविष्यवाणियाँ मिलती हैं। हिन्दू, बौद्ध और जैन धर्म की पुस्तकों में इस प्रकार की पूर्व-सूचनाएँ मिलती हैं। इस ', 'url' => $url.'/hindi/%e0%a4%ae%e0%a5%81%e0%a4%b9%e0%a4%ae%e0%a5%8d%e0%a4%ae%e0%a4%a6-%e0%a4%b8%e0%a4%b2%e0%a5%8d%e0%a4%b2%e0%a4%b2%e0%a5%8d%e0%a4%b2%e0%a4%be%e0%a4%b9%e0%a5%81-%e0%a4%85%e0%a4%b2%e0%a5%88%e0%a4%b9%e0%a4%bf/', 'image' => $url.'/wp-content/uploads/2017/05/मुहम्मद-सल्लल्लाहु-अलैहि-व-सल्लम-और-भारतीय-धर्म-ग्रन्थ-240x312.jpg', 'author_id' => '6777', 'author_name' => 'डाॅ. एम. ए. श्रीवास्तव', 'book_url' => $url.'/books/in_Muhammad_in_Hindu_scriptures.pdf', 'publisher' => 'islamhouse.com' );
	$post[28971] = array( 'title' => 'Die Religion der Wahrheit', 'excerpt' => 'Der Autor sagte: &quot;Oh du vernünftig denkender Mensch! Du musst verstehen, dass es im Diesseits und im Jenseits weder Errettung noch Glück gibt, es sei denn, du erkennst deinen Herrn – Gott, ', 'url' => $url.'/deutsch/die-religion-der-wahrheit/', 'image' => $url.'/wp-content/uploads/2017/05/Die-Religion-der-Wahrheit-240x312.jpg', 'author_id' => '6778', 'author_name' => 'Abdurrahman ibn Hammad al-’Umar', 'book_url' => $url.'/books/de_Die_Religion_der_Wahrheit.pdf', 'publisher' => 'www.alukah.net', 'translator' => 'Abu ´Ammar Ghembaza Moulay-Mohamed' );
	$post[28974] = array( 'title' => '真理的宗教', 'excerpt' => '一切赞颂归于养育众世界的真主，并祈求真主恩赐他派遣的众使者幸福与平安！ 我谨以此书献给世上的芸芸众生； 向有理智的人们发表这得救的宣言： 没有幸福；也不会得救；', 'url' => $url.'/chinese/%e7%9c%9f%e7%90%86%e7%9a%84%e5%ae%97%e6%95%99/', 'image' => $url.'/wp-content/uploads/2017/05/真理的宗教-240x312.jpg', 'author_id' => '6778', 'author_name' => 'Abdurrahman ibn Hammad al-’Umar', 'book_url' => $url.'/books/cn_The_Right_Religion.pdf', 'publisher' => 'www.islamhouse.com' );
	$post[28978] = array( 'title' => 'Diinul-Haq', 'excerpt' => 'Amma ba`du: Inilah ajakan  kepada keselamatan, aku persembahkan kepada setiap yang berakal di alam semesta ini – laki-laki maupun perempuan- dengan mengharap kepada Allah Yang Maha Tinggi dan Berkuasa', 'url' => $url.'/indonesian/diinul-haq/', 'image' => $url.'/wp-content/uploads/2017/05/Diinul-Haq-240x312.jpg', 'author_id' => '6778', 'author_name' => 'Abdurrahman ibn Hammad al-’Umar', 'book_url' => $url.'/books/id_the_right_religion.pdf', 'publisher' => 'islamhouse.com', 'translator' => 'MUHAMMAD SAIFUDIN' );
	$post[28982] = array( 'title' => 'دين حق', 'excerpt' => 'اين پيام نجات (دعوت بسوى نجات) را به همه خرد مندان ـ مردان وزنان ـ تقديم ميدارم، ازبارگاه خداوند بزرگ وتوانا مسئلت ميجويم كه توسط اين (دعوتنامه) گمراهان را خوشنود سازد، وبراى من وآنانكه در نشر اين كتاب شركت ميورزند ثواب جزيل وپاداش نيك عطا فرمايد. پس به يارى خداوند متذكر ميشوم كه', 'url' => $url.'/persian/%d8%af%d9%8a%d9%86-%d8%ad%d9%82/', 'image' => $url.'/wp-content/uploads/2017/05/دين-حق-240x312.jpg', 'author_id' => '6779', 'author_name' => 'عبدالرحمن بن حماد آل عمر ', 'book_url' => $url.'/books/fa_the_right_religion.pdf', 'publisher' => 'http://www.alukah.net/', 'translator' => 'عبدالستار عطازاده كوهستانى' );
