	$post[35117] = array( 'title' => 'Thankfulness', 'excerpt' => 'Thankfulness Since faith consists of two halves, the first being thankfulness, and the other being patience, it is important for the person who admonishes their soul, wishes to safeguard i', 'url' => $url.'/english/thankfulness/', 'image' => $url.'/wp-content/uploads/2018/02/Thankfulness-240x312.jpg', 'author_id' => '411', 'author_name' => 'Muhammad Salih Al-Munajjid', 'book_url' => $url.'/books/2018/02/en_Thankfulness.pdf', 'publisher' => 'Zad Group' );
