	$post[39512] = array( 'title' => 'ఇస్లాం గురించి సాధారణంగా హిందువులు అడిగే కొన్ని ప్రశ్నలు - వాటి జవాబులు', 'excerpt' => 'ఇస్లాం గురించి సాధారణంగా హిందువులు అడిగే కొన్ని ప్రశ్నలు - వాటి జవాబులు ఇస్లాం మరియు ముస్లింల గురించి అర్థం చేసుకునేందుకు ఉపయోగపడే కొన్న', 'url' => $url.'/telugu/%e0%b0%87%e0%b0%b8%e0%b1%8d%e0%b0%b2%e0%b0%be%e0%b0%82-%e0%b0%97%e0%b1%81%e0%b0%b0%e0%b0%bf%e0%b0%82%e0%b0%9a%e0%b0%bf-%e0%b0%b8%e0%b0%be%e0%b0%a7%e0%b0%be%e0%b0%b0%e0%b0%a3%e0%b0%82%e0%b0%97%e0%b0%be/', 'image' => $url.'/wp-content/uploads/2018/12/ఇస్లాం-గురించి-సాధారణంగా-హిందువులు-అడిగే-కొన్ని-ప్రశ్నలు-వాటి-జవాబులు-240x312.jpg', 'author_id' => '2381', 'author_name' => 'ముహమ్మద్ కరీముల్లాహ్', 'book_url' => $url.'/books/2018/12/te_Common_questions_asked_by_Hindus_about_Islam.pdf', 'publisher' => 'islamhouse.com' );
	$post[39515] = array( 'title' => 'ఇస్లామీయ మూలసిద్ధాంతంపై కొన్ని ప్రశ్నోత్తరాలు', 'excerpt' => 'ఇస్లామీయ మూలసిద్ధాంతంపై కొన్ని ప్రశ్నోత్తరాలు ఇస్లామీయ మూలసిద్ధాంతాల గురించి అర్థం చేయుకోవటానికి ఉపయోగపడే కొన్ని ప్రశ్నోత్తరాలు.', 'url' => $url.'/telugu/%e0%b0%87%e0%b0%b8%e0%b1%8d%e0%b0%b2%e0%b0%be%e0%b0%ae%e0%b1%80%e0%b0%af-%e0%b0%ae%e0%b1%82%e0%b0%b2%e0%b0%b8%e0%b0%bf%e0%b0%a6%e0%b1%8d%e0%b0%a7%e0%b0%be%e0%b0%82%e0%b0%a4%e0%b0%82%e0%b0%aa%e0%b1%88/', 'image' => $url.'/wp-content/uploads/2018/12/ఇస్లామీయ-మూలసిద్ధాంతంపై-కొన్ని-ప్రశ్నోత్తరాలు-240x312.jpg', 'author_id' => '2381', 'author_name' => 'ముహమ్మద్ కరీముల్లాహ్', 'book_url' => $url.'/books/2018/12/te_question_about_aqeeda.pdf', 'publisher' => 'islamhouse.com' );
