	$post[39553] = array( 'title' => 'బైబిల్ దేవుని వాక్యమా?', 'excerpt' => 'షేఖ్ అహ్మద్ దీదాత్ రచించిన గొప్ప పుస్తకాలలో ఇది ఒకటి. దీనిలో బైబిలు గురించిన అసలు వాస్తవికతలు స్పష్టంగా చర్చించబడినవి.', 'url' => $url.'/telugu/%e0%b0%ac%e0%b1%88%e0%b0%ac%e0%b0%bf%e0%b0%b2%e0%b1%8d-%e0%b0%a6%e0%b1%87%e0%b0%b5%e0%b1%81%e0%b0%a8%e0%b0%bf-%e0%b0%b5%e0%b0%be%e0%b0%95%e0%b1%8d%e0%b0%af%e0%b0%ae%e0%b0%be/', 'image' => $url.'/wp-content/uploads/2018/12/బైబిల్-దేవుని-వాక్యమా-240x312.jpg', 'author_id' => '7070', 'author_name' => 'అహ్మద్ దీదాత్', 'book_url' => $url.'/books/2018/12/te_Is_the_bible_gods_word.pdf', 'publisher' => 'islamhouse.com' );
	$post[39556] = array( 'title' => 'హిందూ ధర్మాలలో ముహమ్మద్ (స.అ.సం.)', 'excerpt' => 'అంతిమ ప్రవక్త ముహమ్మద్ సల్లల్లాహు అలైహి వసల్లమ్ గురించి, ఏకదైవారాధన మరియు పరలోకం గురించీ హిందూ ధర్మ గ్రంథాలలో స్పష్టంగా వివరించబడినది – ఈ పుస్తకంలో దీనిని ప్రామాణిక ఆధారాలతో స్పష్టంగా చర్చించినారు.', 'url' => $url.'/telugu/%e0%b0%b9%e0%b0%bf%e0%b0%82%e0%b0%a6%e0%b1%82-%e0%b0%a7%e0%b0%b0%e0%b1%8d%e0%b0%ae%e0%b0%be%e0%b0%b2%e0%b0%b2%e0%b1%8b-%e0%b0%ae%e0%b1%81%e0%b0%b9%e0%b0%ae%e0%b1%8d%e0%b0%ae%e0%b0%a6%e0%b1%8d/', 'image' => $url.'/wp-content/uploads/2018/12/హిందూ-ధర్మాలలో-ముహమ్మద్-స.అ.సం.-240x312.jpg', 'author_id' => '7071', 'author_name' => 'ముహమ్మద్ సరూర్ ఆశిమ్', 'book_url' => $url.'/books/2018/12/te_Muhammad_fil_kutub_el_hindusijje.pdf', 'publisher' => 'islamhouse.com' );
	$post[39559] = array( 'title' => 'జీసస్ మరియు ముహమ్మద్ బైబిల్ మరియు ఖుర్ఆన్ లలో', 'excerpt' => 'ఈ పుస్తకం జీసస్ మరియు ముహమ్మద్ గురించి క్రైస్తవులలో ఉన్న అనేక అపోహలను ప్రామాణిక ఆధారాలతో దూరం చేస్తున్నది. సత్యం తెలుసుకోగోరిని ప్రతి ఒక్కరికీ ఇది ప్రయోజనం చేకూర్చును.  ', 'url' => $url.'/telugu/%e0%b0%9c%e0%b1%80%e0%b0%b8%e0%b0%b8%e0%b1%8d-%e0%b0%ae%e0%b0%b0%e0%b0%bf%e0%b0%af%e0%b1%81-%e0%b0%ae%e0%b1%81%e0%b0%b9%e0%b0%ae%e0%b1%8d%e0%b0%ae%e0%b0%a6%e0%b1%8d-%e0%b0%ac%e0%b1%88%e0%b0%ac/', 'image' => $url.'/wp-content/uploads/2018/12/జీసస్-మరియు-ముహమ్మద్-బైబిల్-మరియు-ఖుర్ఆన్-లలో-240x312.jpg', 'author_id' => '7072', 'author_name' => 'ముహమ్మద్ ముహ్సిన్ ఖాన్', 'book_url' => $url.'/books/2018/12/te_Jesus_and_Muhammed_in_Bible_and_Quran.pdf', 'publisher' => 'islamhouse.com' );
	$post[39562] = array( 'title' => 'దేవుడే మానవుడిగా మారినాడా', 'excerpt' => 'దేవుడిని విశ్వసించేవారిలో తమ విశ్వాసపు స్వభావం గురించి వివేకం మరియు దివ్యసందేశం ఆధారంగా పునరాలోచన కలిగించటమే ఈ పుస్తకపు ముఖ్యోద్దేశ్యం.', 'url' => $url.'/telugu/%e0%b0%a6%e0%b1%87%e0%b0%b5%e0%b1%81%e0%b0%a1%e0%b1%87-%e0%b0%ae%e0%b0%be%e0%b0%a8%e0%b0%b5%e0%b1%81%e0%b0%a1%e0%b0%bf%e0%b0%97%e0%b0%be-%e0%b0%ae%e0%b0%be%e0%b0%b0%e0%b0%bf%e0%b0%a8%e0%b0%be%e0%b0%a1/', 'image' => $url.'/wp-content/uploads/2018/12/దేవుడే-మానవుడిగా-మారినాడా-240x312.jpg', 'author_id' => '2377', 'author_name' => 'బిలాల్ ఫిలిఫ్స్', 'book_url' => $url.'/books/2018/12/te_Did_God_become_man.pdf', 'publisher' => 'islamhouse.com', 'translator' => 'ముహమ్మద్ కరీముల్లాహ్' );
	$post[39567] = array( 'title' => 'സ്ത്രീ നേതൃത്വം ഇസ്‌ലാമിൽ', 'excerpt' => 'സ്ത്രീയുടെ മഹത്വവും ഇസ്‌ലാമിൽ അവൾ ആദരിക്കപ്പെടുന്നത് എപ്രകാരമാണെന്നും സ്ത്രീ നേതൃത്വം ഇസ്‌ലാമിൽ എന്ന ഈ ഗ്രന്ഥം വിശദീകരിക്കുന്നു.', 'url' => $url.'/malayalam/%e0%b4%b8%e0%b5%8d%e0%b4%a4%e0%b5%8d%e0%b4%b0%e0%b5%80-%e0%b4%a8%e0%b5%87%e0%b4%a4%e0%b5%83%e0%b4%a4%e0%b5%8d%e0%b4%b5%e0%b4%82-%e0%b4%87%e0%b4%b8%e0%b5%8d%e2%80%8c%e0%b4%b2%e0%b4%be%e0%b4%ae%e0%b4%bf/', 'image' => $url.'/wp-content/uploads/2018/12/സ്ത്രീ-നേതൃത്വം-ഇസ്‌ലാമിൽ-240x312.jpg', 'author_id' => '7073', 'author_name' => 'Hanif Abdul Rahman Al Rayyan', 'book_url' => $url.'/books/2018/12/ml_sni_final.pdf' );
	$post[39571] = array( 'title' => 'നിത്യ സത്യത്തിലേക്ക്', 'excerpt' => 'അമുസ്ലിംകൾക്കും ഇസ്ലാമിൻറെ ബാലപാഠങ്ങൾ പഠിക്കുന്നവർക്കും ഇസ്ലാമിനെ കുറിച്ച് പരിചയപ്പെടുത്തുന്ന ലഘു കൃതി.  ', 'url' => $url.'/malayalam/%e0%b4%a8%e0%b4%bf%e0%b4%a4%e0%b5%8d%e0%b4%af-%e0%b4%b8%e0%b4%a4%e0%b5%8d%e0%b4%af%e0%b4%a4%e0%b5%8d%e0%b4%a4%e0%b4%bf%e0%b4%b2%e0%b5%87%e0%b4%95%e0%b5%8d%e0%b4%95%e0%b5%8d/', 'image' => $url.'/wp-content/uploads/2018/12/നിത്യ-സത്യത്തിലേക്ക്-240x312.jpg', 'author_id' => '7074', 'author_name' => 'മിദ് ലാജ് സ്വലാഹി', 'book_url' => $url.'/books/2018/12/ml_Come_to_the_right.pdf', 'publisher' => 'islamhouse.com' );
	$post[39574] = array( 'title' => 'ഞങ്ങൾ മുസ്ലിംകളായി !', 'excerpt' => 'വ്യത്യസ്ത മത സാഹചര്യങ്ങളിൽ ജനിച്ച് വളര്ന്ന് സൃഷ്ടാവിന്റെ മതത്തിലേക്ക് എത്തിച്ചേർന്ന ഏതാനും മലയാളി സുഹ്രുത്തുക്കളുടെ ജീവിതാനുഭാവങ്ങളാണ് ഈ കൃതി .  ', 'url' => $url.'/malayalam/%e0%b4%9e%e0%b4%99%e0%b5%8d%e0%b4%99%e0%b5%be-%e0%b4%ae%e0%b5%81%e0%b4%b8%e0%b5%8d%e0%b4%b2%e0%b4%bf%e0%b4%82%e0%b4%95%e0%b4%b3%e0%b4%be%e0%b4%af%e0%b4%bf/', 'image' => $url.'/wp-content/uploads/2018/12/ഞങ്ങൾ-മുസ്ലിംകളായി--240x312.jpg', 'author_id' => '7075', 'author_name' => 'മുഹമ്മദ് കുട്ടി അബൂബക്കര്‍', 'book_url' => $url.'/books/2018/12/ml_njangaL_MuslimkaLaayi.pdf', 'publisher' => 'lamhouse.com' );
	$post[39585] = array( 'title' => 'ക്രിസ്തു മാര്ഗ്ഗം ,യാഥാർഥ്യ മെന്ത് ?', 'excerpt' => 'സമീപ കാലത്ത് ക്രിസ്തു മിഷനറിമാർ തങ്ങളുടെ ഊന്നലുകളിൽ വരുത്തിയ അഴിച്ചുപണിയുടെ മര്മ്മം തിരിച്ച റിഞ്ഞ് ക്രൈസ്തവ സമൂഹത്തിന്റെ തന്നെ ഭാഷയിൽ ആധുനിക ക്രിസ്തു മതം ക്രിസ്തുവിന്റെ മതമല്ലെന്നും പ്രത്യുത പൗലോസ് നിര്മിച്ചെടുത്ത ക്രിസ്തുവിരുദ്ധമായ ആശയങ്ങളുടെ ലോകമാണെന്നും തെളിയിക്കുന്ന ഇസ്ലാം ക്രൈസ്തവ സംവാദം.  ', 'url' => $url.'/malayalam/%e0%b4%95%e0%b5%8d%e0%b4%b0%e0%b4%bf%e0%b4%b8%e0%b5%8d%e0%b4%a4%e0%b5%81-%e0%b4%ae%e0%b4%be%e0%b4%b0%e0%b5%8d%e0%b4%97%e0%b5%8d%e0%b4%97%e0%b4%82-%e0%b4%af%e0%b4%be%e0%b4%a5%e0%b4%be%e0%b5%bc/', 'image' => $url.'/wp-content/uploads/2018/12/ക്രിസ്തു-മാര്ഗ്ഗം-യാഥാർഥ്യ-മെന്ത്-240x312.jpg', 'author_id' => '7076', 'author_name' => 'മുഹമ്മദ് ഈസ', 'book_url' => $url.'/books/2018/12/ml_Kristhu_Margam_yadarthyamenth.pdf', 'publisher' => 'islamhouse.com' );
